    const _mmoNormTextCache = new Map();
    function normApiText(str) {
      const key = String(str || '');
      if (_mmoNormTextCache.has(key)) return _mmoNormTextCache.get(key);
      const res = key.toLowerCase()
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .replace(/[đĐ]/g, 'd')
        .replace(/[^a-z0-9]/g, ' ')
        .replace(/\s+/g, ' ').trim();
      if (_mmoNormTextCache.size < 6000) _mmoNormTextCache.set(key, res);
      return res;
    }
    window.normApiText = normApiText;

    function cleanCompareText(str) {
      return normApiText(str)
        .replace(/\b(kenh|trang|live|full|mod|cho|thue|ngay|gio|phut|gia|re|cuc|trau|moi|new|old|co)\b/g, '')
        .replace(/\s+/g, ' ')
        .trim();
    }
    window.cleanCompareText = cleanCompareText;

