    window.quickOpenStockForProduct = quickOpenStockForProduct;


    // =========================================================================
    // CORE SYSTEM: USER BALANCE MODAL & DETAIL MODAL
    // =========================================================================
    function getUserComprehensiveTransactions(targetEmail) {
      const cleanEmail = (targetEmail || "").toLowerCase().trim();
      if (!cleanEmail) return { transactions: [], currentBalance: 0 };

      const rawLogs = [];

      // A. Lấy từ mmo_transaction_history (hệ thống giao dịch chuẩn)
      try {
        const localHistory = typeof getTransactionHistory === "function" ? getTransactionHistory() : [];
        localHistory.forEach(tx => {
          if ((tx.userEmail || "").toLowerCase().trim() === cleanEmail) {
            rawLogs.push({
              id: tx.id || tx.txId,
              orderId: tx.orderId || "",
              time: tx.time || tx.date,
              type: tx.type || "Giao dịch ví",
              amount: Number(tx.amount) || 0,
              balanceAfter: (tx.balanceAfter !== undefined && tx.balanceAfter !== null) ? Number(tx.balanceAfter) : null,
              note: tx.note || ""
            });
          }
        });
      } catch(e) {}

      // B. Quét từ mmo_transactions & mmo_wallet_transactions
      try {
        const extraTxs = JSON.parse(localStorage.getItem("mmo_transactions") || localStorage.getItem("mmo_wallet_transactions") || "[]");
        if (Array.isArray(extraTxs)) {
          extraTxs.forEach(etx => {
            if ((etx.userEmail || "").toLowerCase().trim() === cleanEmail) {
              rawLogs.push({
                id: etx.id || etx.txId,
                orderId: etx.orderId || "",
                time: etx.time || etx.date,
                type: etx.type || "Giao dịch ví",
                amount: Number(etx.amount) || 0,
                balanceAfter: (etx.balanceAfter !== undefined && etx.balanceAfter !== null) ? Number(etx.balanceAfter) : null,
                note: etx.note || etx.content || ""
              });
            }
          });
        }
      } catch(e) {}

      // C. Quét toàn bộ đơn hàng (Cả đơn mua hàng và đơn hoàn tiền)
      try {
        const uOrders = typeof getUserOrders === "function" ? getUserOrders() : [];
        const aOrders = typeof getAllOrders === "function" ? getAllOrders() : [];
        const combinedOrders = [...uOrders];
        aOrders.forEach(ao => {
          if (!combinedOrders.some(co => (co.orderId === ao.orderId || co.id === ao.id))) {
            combinedOrders.push(ao);
          }
        });

        combinedOrders.forEach(o => {
          const ordEmail = (o.email || o.userEmail || "").toLowerCase().trim();
          if (ordEmail === cleanEmail) {
            const oId = String(o.orderId || o.id || "").trim();
            const pName = o.productName || o.prodName || "Sản phẩm";
            const vName = (o.variantName && o.variantName !== "Mặc định") ? (" (" + o.variantName + ")") : "";
            const ordAmt = Number(o.total || o.totalCost || o.totalPrice || o.totalAmount) || 0;
            const ordTime = o.date || (o.createdAt ? new Date(o.createdAt).toLocaleString("vi-VN") : "") || "";

            // 1. Đơn mua hàng (trừ tiền)
            if (ordAmt > 0) {
              rawLogs.push({
                id: "ORD_" + oId,
                orderId: oId,
                time: ordTime,
                type: "Thanh toán mua hàng",
                amount: -ordAmt,
                balanceAfter: o.balanceAfter !== undefined ? Number(o.balanceAfter) : null,
                note: "Mua SP: " + pName + vName + " - Đơn #" + oId
              });
            }

            // 2. Đơn được hoàn tiền bảo hành (cộng tiền)
            const st = String(o.status || "").toLowerCase();
            const isRefunded = o.refundedAt || o.refundAmount || st.includes("hoàn tiền") || st.includes("refund");
            if (isRefunded) {
              const refAmt = Number(o.refundAmount) || ordAmt || 15000;
              const refTime = o.refundedAt || ordTime;
              rawLogs.push({
                id: "REFUND_" + oId,
                orderId: oId,
                time: refTime,
                type: "Hoàn tiền đơn hàng bảo hành",
                amount: +refAmt,
                balanceAfter: o.refundBalanceAfter !== undefined ? Number(o.refundBalanceAfter) : null,
                note: "Hoàn tiền bảo hành đơn #" + oId + " (" + pName + ")"
              });
            }
          }
        });
      } catch(e) {}

      // D. Gộp từ Cloud SePay / VietQR (cachedCloudWalletHistory)
      if (typeof cachedCloudWalletHistory !== "undefined" && Array.isArray(cachedCloudWalletHistory)) {
        cachedCloudWalletHistory.forEach(ch => {
          rawLogs.push({
            id: ch.id,
            orderId: ch.id,
            time: ch.time || ch.date,
            type: ch.type || "Nạp tiền VietQR / SePay",
            amount: Number(ch.amount) || 0,
            balanceAfter: null,
            note: ch.note || ch.content || "Nạp tiền tự động qua QR"
          });
        });
      }

      // E. Lọc trùng thông minh theo mã giao dịch và loại
      const seenMap = new Map();
      rawLogs.forEach(item => {
        const amt = Number(item.amount) || 0;
        const oId = String(item.orderId || item.id || "").replace(/^REFUND_|^ORD_/, "").trim();
        const isRef = amt > 0 && (String(item.type).toLowerCase().includes("hoàn tiền") || String(item.note).toLowerCase().includes("hoàn tiền"));
        const isPurchase = amt < 0;

        let key = "";
        if (oId && isRef) {
          key = "REFUND_" + oId;
        } else if (oId && isPurchase) {
          key = "PURCHASE_" + oId;
        } else if (item.id) {
          key = "ID_" + item.id;
        } else {
          key = "TIME_" + (item.time || "") + "_" + amt;
        }

        if (!seenMap.has(key)) {
          seenMap.set(key, item);
        } else {
          const existing = seenMap.get(key);
          if (!existing.balanceAfter && item.balanceAfter) {
            seenMap.set(key, item);
          }
        }
      });

      const allLogs = Array.from(seenMap.values());

      // F. Sắp xếp theo thời gian mới nhất lên đầu danh sách
      function parseVietnamDateTime(str) {
        if (!str) return 0;
        if (typeof str === "number") return str;
        str = String(str).trim();
        
        const tokens = str.split(/\s+/);
        let dPart = "", tPart = "00:00:00";
        for (let t of tokens) {
          if (t.includes("/")) dPart = t;
          else if (t.includes(":")) tPart = t;
        }

        if (dPart) {
          const dp = dPart.split("/");
          if (dp.length === 3) {
            const d = parseInt(dp[0], 10);
            const m = parseInt(dp[1], 10) - 1;
            const y = parseInt(dp[2], 10);
            const tp = tPart.split(":");
            const h = parseInt(tp[0] || "0", 10);
            const min = parseInt(tp[1] || "0", 10);
            const s = parseInt(tp[2] || "0", 10);
            const res = new Date(y, m, d, h, min, s).getTime();
            if (!isNaN(res)) return res;
          }
        }

        const parsed = new Date(str).getTime();
        return isNaN(parsed) ? 0 : parsed;
      }

      allLogs.sort((a, b) => parseVietnamDateTime(b.time || b.date) - parseVietnamDateTime(a.time || a.date));

      // G. Xác định số dư hiện tại của tài khoản
      let curBal = 0;
      if (typeof currentUser !== "undefined" && currentUser && (currentUser.email || "").toLowerCase().trim() === cleanEmail && currentUser.balance !== undefined) {
        curBal = Number(currentUser.balance) || 0;
      } else {
        const uList = (typeof getRegisteredUsers === "function") ? getRegisteredUsers() : [];
        const uFound = uList.find(item => (item.email || "").toLowerCase().trim() === cleanEmail);
        if (uFound && uFound.balance !== undefined) {
          curBal = Number(uFound.balance) || 0;
        }
      }

      // H. Tính toán số dư sau chuẩn xác theo chuỗi thời gian ngược dần từ số dư thực tế
      let runningBal = curBal;
      for (let idx = 0; idx < allLogs.length; idx++) {
        const tx = allLogs[idx];
        if (idx === 0) {
          tx.balanceAfter = curBal;
          runningBal = curBal;
        } else {
          const prevTx = allLogs[idx - 1];
          const prevAmt = Number(prevTx.amount) || 0;
          runningBal = runningBal - prevAmt;
          tx.balanceAfter = Math.max(0, runningBal);
        }
      }

      return { transactions: allLogs, currentBalance: curBal };
    }
    window.getUserComprehensiveTransactions = getUserComprehensiveTransactions;

    function openUserBalanceModal(email) {
      let users = getRegisteredUsers();
      const u = users.find(item => (item.email || "").toLowerCase().trim() === (email || "").toLowerCase().trim());
      if (!u) {
        showToast("Không tìm thấy người dùng này!", "danger");
        return;
      }

      let curBal = (u.balance !== undefined) ? Number(u.balance) : 0;
      if (typeof currentUser !== "undefined" && currentUser && (currentUser.email || "").toLowerCase().trim() === (email || "").toLowerCase().trim() && currentUser.balance !== undefined) {
        curBal = Number(currentUser.balance);
      } else if (typeof getUserComprehensiveTransactions === "function") {
        const res = getUserComprehensiveTransactions(u.email);
        curBal = res.currentBalance;
      }

      const inpEmail = document.getElementById("balModalUserEmail");
      const nameTxt = document.getElementById("balModalUserName");
      const emailTxt = document.getElementById("balModalUserEmailText");
      const curBalTxt = document.getElementById("balModalCurrentBalance");
      const amtInp = document.getElementById("balModalAmountInput");
      const noteInp = document.getElementById("balModalNoteInput");

      if (inpEmail) inpEmail.value = u.email;
      if (nameTxt) nameTxt.innerText = u.name;
      if (emailTxt) emailTxt.innerText = u.email;
      if (curBalTxt) curBalTxt.innerText = formatVND(curBal);
      if (amtInp) amtInp.value = "20000";
      if (noteInp) noteInp.value = "Nạp tiền thủ công qua ngân hàng";

      const radio = document.querySelector("input[name='balActionType'][value='add']");
      if (radio) radio.checked = true;

      const modal = document.getElementById("userBalanceModal");
      if (modal) modal.style.display = "flex";
    }
    window.openUserBalanceModal = openUserBalanceModal;

    function openAdminUserDetailModal(email) {
      const cleanEmail = (email || "").toLowerCase().trim();
      let users = getRegisteredUsers();
      let u = users.find(item => (item.email || "").toLowerCase().trim() === cleanEmail);
      if (!u) {
        showToast("Không tìm thấy thông tin thành viên này!", "danger");
        return;
      }

      // 1. Thu thập toàn bộ biến động số dư & số dư chuẩn xác
      const result = (typeof getUserComprehensiveTransactions === "function") 
        ? getUserComprehensiveTransactions(cleanEmail) 
        : { transactions: [], currentBalance: (u.balance || 0) };
      
      const allTx = result.transactions;
      let accurateBalance = result.currentBalance;

      // Đồng bộ số dư chuẩn vào người dùng và hệ thống
      u.balance = accurateBalance;
      saveRegisteredUsers(users);

      if (typeof currentUser !== "undefined" && currentUser && (currentUser.email || "").toLowerCase().trim() === cleanEmail) {
        currentUser.balance = accurateBalance;
        localStorage.setItem("mmo_user", JSON.stringify(currentUser));
        if (typeof updateUserUI === "function") updateUserUI();
      }

      const avatarEl = document.getElementById("admDetailUserAvatar");
      const nameEl = document.getElementById("admDetailUserName");
      const emailEl = document.getElementById("admDetailUserEmail");
      const roleBadge = document.getElementById("admDetailUserRoleBadge");
      const statusBadge = document.getElementById("admDetailUserStatusBadge");
      const createdEl = document.getElementById("admDetailUserCreated");
      const balanceEl = document.getElementById("admDetailUserBalance");
      const txCountEl = document.getElementById("admDetailTxCount");
      const btnTopup = document.getElementById("admDetailBtnTopup");
      const btnLock = document.getElementById("admDetailBtnLock");

      const isAdm = (u.email === ROOT_ADMIN_EMAIL || (typeof getAdminEmails === "function" && getAdminEmails().map(e => (e||"").toLowerCase().trim()).includes((u.email||"").toLowerCase().trim())) || u.role === "Quản Trị Viên");
      const isLocked = !!u.isLocked;

      if (avatarEl) avatarEl.src = u.avatar || "https://cdn-icons-png.flaticon.com/512/3135/3135715.png";
      if (nameEl) nameEl.innerText = u.name || "Thành Viên";
      if (emailEl) emailEl.innerText = u.email;
      if (createdEl) createdEl.innerText = u.created || "01/03/2026";
      if (balanceEl) balanceEl.innerText = formatVND(accurateBalance);
      if (txCountEl) txCountEl.innerText = allTx.length + " giao dịch";

      if (roleBadge) {
        roleBadge.innerText = isAdm ? "Quản Trị Viên" : "Thành Viên";
        roleBadge.style.color = isAdm ? "#f59e0b" : "#10b981";
      }

      if (statusBadge) {
        statusBadge.innerText = isLocked ? "Đã Khóa" : "Hoạt Động";
        statusBadge.style.color = isLocked ? "#ef4444" : "#10b981";
      }

      if (btnTopup) {
        btnTopup.onclick = function() { openUserBalanceModal(u.email); };
      }
      if (btnLock) {
        btnLock.onclick = function() { toggleLockUser(u.email); };
        btnLock.innerHTML = isLocked ? '<i class="fa-solid fa-unlock"></i> Mở Khóa' : '<i class="fa-solid fa-lock"></i> Khóa Acc';
      }

      const tbody = document.getElementById("admDetailUserTxTableBody");
      if (tbody) {
        if (allTx.length === 0) {
          tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:24px; color:#64748b;">Thành viên này chưa có giao dịch nào phát sinh.</td></tr>';
        } else {
          tbody.innerHTML = allTx.map(tx => {
            const amt = Number(tx.amount) || 0;
            const isPlus = amt > 0;
            const amtHtml = isPlus 
              ? '<span style="color:#10b981; font-weight:800;">+' + formatVND(amt) + '</span>' 
              : '<span style="color:#ef4444; font-weight:800;">' + formatVND(amt) + '</span>';

            const tLow = String(tx.type || "").toLowerCase();
            const nLow = String(tx.note || "").toLowerCase();
            const isRefund = tLow.includes("hoàn tiền") || nLow.includes("hoàn tiền");
            const isPurchase = tLow.includes("thanh toán") || tLow.includes("mua hàng") || amt < 0;

            let typeHtml = "";
            if (isRefund) {
              typeHtml = '<span class="badge-verified" style="font-size:0.72rem; color:#10b981; border-color:rgba(16,185,129,0.3); background:rgba(16,185,129,0.1);"><i class="fa-solid fa-hand-holding-dollar"></i> Hoàn tiền bảo hành</span>';
            } else if (isPurchase) {
              typeHtml = '<span class="badge-verified" style="font-size:0.72rem; color:#f87171; border-color:rgba(239,68,68,0.3); background:rgba(239,68,68,0.1);"><i class="fa-solid fa-cart-shopping"></i> Thanh toán mua hàng</span>';
            } else if (tLow.includes("rút")) {
              typeHtml = '<span class="badge-verified" style="font-size:0.72rem; color:#fbbf24; border-color:rgba(245,158,11,0.3); background:rgba(245,158,11,0.1);"><i class="fa-solid fa-arrow-up-right-from-square"></i> Rút tiền</span>';
            } else if (tLow.includes("thủ công") || nLow.includes("thủ công")) {
              typeHtml = '<span class="badge-trust" style="font-size:0.72rem; color:#38bdf8; border-color:rgba(56,189,248,0.3); background:rgba(56,189,248,0.1);"><i class="fa-solid fa-user-shield"></i> Nạp thủ công Admin</span>';
            } else {
              typeHtml = '<span class="badge-trust" style="font-size:0.72rem; color:#38bdf8; border-color:rgba(56,189,248,0.3); background:rgba(56,189,248,0.1);"><i class="fa-solid fa-wallet"></i> Nạp tiền ví</span>';
            }

            let balAfterStr = (tx.balanceAfter !== undefined && tx.balanceAfter !== null && !isNaN(Number(tx.balanceAfter))) ? formatVND(Math.max(0, tx.balanceAfter)) : "-";

            let displayNote = tx.note || "";
            if (isRefund && (!displayNote || displayNote.includes("NAP ") || displayNote.includes("SePay"))) {
              displayNote = "Hoàn tiền đơn hàng bảo hành mã đơn #" + (tx.orderId || "");
            }

            return '<tr>' +
              '<td style="font-size:0.75rem; color:#94a3b8; white-space:nowrap;">' + (tx.time || tx.date || '') + '</td>' +
              '<td>' + typeHtml + '</td>' +
              '<td>' + amtHtml + '</td>' +
              '<td style="color:#38bdf8; font-weight:700; font-size:0.82rem; font-family:monospace; white-space:nowrap;">' + balAfterStr + '</td>' +
              '<td style="font-size:0.75rem; color:#cbd5e1;">' + escapeHtml(displayNote) + '</td>' +
            '</tr>';
          }).join("");
        }
      }

      const modal = document.getElementById("adminUserDetailModal");
      if (modal) modal.style.display = "flex";
    }
    window.openAdminUserDetailModal = openAdminUserDetailModal;

    // =========================================================================
    // HỆ THỐNG TIẾP THỊ LIÊN KẾT (AFFILIATE ENGINE) - QUY TRÌNH CHUẨN HOÁ
    // - Tạm giữ hoa hồng 3 ngày (72 giờ)
    // - Tự động hủy khi khách khiếu nại, hủy đơn hoặc hoàn tiền
    // - Tự động cộng tiền vào ví sau 3 ngày hoàn tất an toàn
    // =========================================================================

    function getAffiliateOrders() {
      try {
        const raw = localStorage.getItem("mmo_affiliate_orders");
        return raw ? JSON.parse(raw) : [];
      } catch(e) {
        return [];
      }
    }
    window.getAffiliateOrders = getAffiliateOrders;

    function saveAffiliateOrders(list) {
      try {
        localStorage.setItem("mmo_affiliate_orders", JSON.stringify(list || []));
      } catch(e) {}
    }
    window.saveAffiliateOrders = saveAffiliateOrders;

    function recordAffiliateCommissionForOrder(order) {
      if (!order) return null;
      const orderId = String(order.orderId || order.orderCode || order.id || "").replace("#", "").trim();
      if (!orderId) return null;

      let affOrders = getAffiliateOrders();
      if (affOrders.some(a => a.orderId === orderId)) {
        return null; // Đã ghi nhận hoa hồng cho đơn này rồi
      }

      const buyerEmail = String(order.buyerEmail || order.email || order.userEmail || (currentUser ? currentUser.email : "")).toLowerCase().trim();
      if (!buyerEmail || !buyerEmail.includes("@")) return null;

      // 1. Tìm mã người giới thiệu (refCode)
      const allUsers = typeof getRegisteredUsers === "function" ? getRegisteredUsers() : [];
      const buyerUser = allUsers.find(u => (u.email || "").toLowerCase().trim() === buyerEmail);
      let refCode = (buyerUser && buyerUser.referredBy) ? String(buyerUser.referredBy).toLowerCase().trim() : "";

      if (!refCode) {
        refCode = (localStorage.getItem("mmo_ref_code") || sessionStorage.getItem("mmo_ref_code") || "").toLowerCase().trim();
      }
      if (!refCode && order.refCode) {
        refCode = String(order.refCode).toLowerCase().trim();
      }

      if (!refCode) return null;

      // 2. Tìm thông tin người giới thiệu (referrer)
      const referrer = allUsers.find(u => {
        const uMail = (u.email || "").toLowerCase().trim();
        const uPrefix = uMail.split("@")[0];
        const uId = (u.userId || u.id || "").toLowerCase().trim();
        return uMail === refCode || uPrefix === refCode || uId === refCode;
      });

      if (!referrer) return null;

      // Chống tự giới thiệu chính mình (Self-referral check)
      if ((referrer.email || "").toLowerCase().trim() === buyerEmail) {
        return null;
      }

      // 3. Tính toán hoa hồng
      const totalAmt = Number(order.total || order.totalPrice || order.amount || 0);
      if (totalAmt <= 0) return null;

      let commRate = 10; // Mặc định 10%
      if (typeof order.commissionRate === "number" && order.commissionRate > 0) {
        commRate = order.commissionRate;
      } else if (order.productId || order.prodId) {
        const pId = order.productId || order.prodId;
        const p = (typeof MOCK_DATA !== "undefined" && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products.find(x => x.id === pId) : null;
        if (p) {
          if (typeof p.commissionRate === "number") commRate = p.commissionRate;
          else if (typeof p.commission === "number") commRate = p.commission;
          else {
            const m = String(p.commission || p.commissionRate || "").match(/[0-9]+/);
            if (m) commRate = parseInt(m[0], 10);
          }
        }
      }
      if (isNaN(commRate) || commRate <= 0) commRate = 10;

      const commAmount = Math.round(totalAmt * (commRate / 100));
      if (commAmount <= 0) return null;

      const nowTs = Date.now();
      const holdDuration = 3 * 24 * 60 * 60 * 1000; // 3 ngày = 72 giờ

      const affRecord = {
        id: "AFF_" + orderId + "_" + nowTs,
        orderId: orderId,
        buyerEmail: buyerEmail,
        buyerName: (buyerUser && buyerUser.name) ? buyerUser.name : (order.buyerUsername || order.userName || buyerEmail.split("@")[0]),
        referrerEmail: referrer.email,
        referrerCode: refCode,
        referrerName: referrer.name || referrer.email.split("@")[0],
        productId: order.productId || order.prodId || "",
        productName: order.productName || order.prodName || "Tài khoản MMO",
        variant: order.variant || order.variantName || "Mặc định",
        orderTotal: totalAmt,
        commissionRate: commRate,
        commissionAmount: commAmount,
        createdAt: nowTs,
        holdUntil: nowTs + holdDuration,
        holdDays: 3,
        status: "HOLDING", // HOLDING: Tạm giữ 3 ngày
        statusText: "Tạm giữ 3 ngày (Chờ duyệt)",
        settledAt: null,
        cancelledAt: null,
        cancelReason: ""
      };

      affOrders.unshift(affRecord);
      saveAffiliateOrders(affOrders);

      // Nếu người giới thiệu đang đăng nhập, hiển thị thông báo
      if (currentUser && currentUser.email && currentUser.email.toLowerCase().trim() === referrer.email.toLowerCase().trim()) {
        if (typeof addUserNotification === "function") {
          addUserNotification({
            title: "💰 Hoa hồng tạm tính đơn #" + orderId,
            message: "Thành viên F1 (" + buyerEmail + ") vừa mua đơn #" + orderId + ". Bạn được tạm giữ " + (typeof formatVND === "function" ? formatVND(commAmount) : commAmount + " đ") + " hoa hồng (sẽ tự động cộng vào ví sau 3 ngày hoàn tất).",
            type: "AFFILIATE",
            email: referrer.email
          });
        }
        if (typeof renderAffiliateDashboard === "function") renderAffiliateDashboard();
      }

      return affRecord;
    }
    window.recordAffiliateCommissionForOrder = recordAffiliateCommissionForOrder;

    function cancelAffiliateCommissionForOrder(orderId, reason) {
      if (!orderId) return false;
      const cleanId = String(orderId).replace("#", "").trim();
      let affOrders = getAffiliateOrders();
      let modified = false;

      affOrders.forEach(item => {
        if (item.orderId === cleanId && item.status === "HOLDING") {
          item.status = "CANCELLED";
          item.statusText = "Đã hủy hoa hồng (Đơn hủy/hoàn tiền)";
          item.cancelledAt = Date.now();
          item.cancelReason = reason || "Đơn hàng bị khiếu nại / hoàn tiền";
          modified = true;

          // Thông báo cho người giới thiệu
          if (typeof addUserNotification === "function") {
            addUserNotification({
              title: "⚠️ Hủy hoa hồng đơn #" + cleanId,
              message: "Đơn hàng #" + cleanId + " của thành viên F1 đã bị hủy hoặc hoàn tiền. Hoa hồng tạm tính (" + (typeof formatVND === "function" ? formatVND(item.commissionAmount) : item.commissionAmount + " đ") + ") đã bị hủy theo quy định.",
              type: "AFFILIATE_CANCEL",
              email: item.referrerEmail
            });
          }
        }
      });

      if (modified) {
        saveAffiliateOrders(affOrders);
        if (typeof renderAffiliateDashboard === "function") renderAffiliateDashboard();
      }
      return modified;
    }
    window.cancelAffiliateCommissionForOrder = cancelAffiliateCommissionForOrder;

    function processAffiliateSettlement() {
      let affOrders = getAffiliateOrders();
      if (!affOrders || affOrders.length === 0) return 0;

      const nowTs = Date.now();
      let settledCount = 0;
      let users = typeof getRegisteredUsers === "function" ? getRegisteredUsers() : [];
      let allOrders = typeof getAllOrders === "function" ? getAllOrders() : [];
      let preOrders = typeof getPreOrders === "function" ? getPreOrders(true) : [];
      let modified = false;

      affOrders.forEach(item => {
        if (item.status !== "HOLDING") return;

        // 1. Kiểm tra xem đơn hàng gốc có bị hủy hoặc khiếu nại không
        const oMatch = allOrders.find(o => String(o.orderId || o.id).replace("#", "").trim() === item.orderId) ||
                       preOrders.find(p => String(p.id || p.orderCode).replace("#", "").trim() === item.orderId);

        if (oMatch) {
          const st = String(oMatch.status || "").toUpperCase();
          const isCancelOrRefund = st === "CANCELLED" || st === "REFUNDED" || st.includes("HỦY") || st.includes("HOÀN TIỀN") || st.includes("KHIẾU NẠI") || Boolean(oMatch.isCancelled) || Boolean(oMatch.isRefunded);
          if (isCancelOrRefund) {
            item.status = "CANCELLED";
            item.statusText = "Đã hủy hoa hồng (Đơn hủy/hoàn tiền)";
            item.cancelledAt = nowTs;
            item.cancelReason = "Đơn hàng gốc đã hủy hoặc hoàn tiền ví";
            modified = true;
            return;
          }
        }

        // 2. Nếu đã qua 3 ngày (72 giờ)
        if (nowTs >= item.holdUntil) {
          item.status = "APPROVED";
          item.statusText = "Đã cộng vào ví";
          item.settledAt = nowTs;
          modified = true;
          settledCount++;

          // Cộng tiền vào số dư ví của người giới thiệu
          const refEmail = (item.referrerEmail || "").toLowerCase().trim();
          const rIdx = users.findIndex(u => (u.email || "").toLowerCase().trim() === refEmail);
          let newBal = item.commissionAmount;
          let rName = item.referrerName || refEmail.split("@")[0];

          if (rIdx !== -1) {
            users[rIdx].balance = (Number(users[rIdx].balance) || 0) + item.commissionAmount;
            newBal = users[rIdx].balance;
            rName = users[rIdx].name || rName;
          } else {
            users.push({
              userId: "USR_" + Math.floor(100000 + Math.random() * 900000),
              email: refEmail,
              name: rName,
              balance: item.commissionAmount,
              role: "MEMBER"
            });
            newBal = item.commissionAmount;
          }

          if (typeof saveRegisteredUsers === "function") saveRegisteredUsers(users);

          // Ghi nhận lịch sử giao dịch & log số dư
          if (typeof recordTransaction === "function") {
            recordTransaction(
              refEmail,
              rName,
              "Hoa hồng tiếp thị liên kết",
              item.commissionAmount,
              newBal,
              "Hoa hồng " + item.commissionRate + "% từ thành viên F1 (" + item.buyerEmail + ") cho đơn #" + item.orderId + " sau 3 ngày hoàn tất"
            );
          }

          // Cập nhật currentUser nếu đang là người giới thiệu
          if (currentUser && currentUser.email && currentUser.email.toLowerCase().trim() === refEmail) {
            currentUser.balance = newBal;
            localStorage.setItem("mmo_user", JSON.stringify(currentUser));
            if (typeof updateUserUI === "function") updateUserUI();
            if (typeof showToast === "function") {
              showToast("🎉 Chúc mừng! Bạn vừa nhận được " + (typeof formatVND === "function" ? formatVND(item.commissionAmount) : item.commissionAmount + " đ") + " hoa hồng tiếp thị liên kết từ đơn #" + item.orderId + "!", "success");
            }
          }

          // Gửi thông báo chuông
          if (typeof addUserNotification === "function") {
            addUserNotification({
              title: "🎉 Nhận hoa hồng tiếp thị #" + item.orderId,
              message: "Bạn đã nhận được +" + (typeof formatVND === "function" ? formatVND(item.commissionAmount) : item.commissionAmount + " đ") + " hoa hồng từ đơn hàng #" + item.orderId + " vào ví sau 3 ngày hoàn tất an toàn.",
              type: "AFFILIATE_PAID",
              email: refEmail
            });
          }
        }
      });

      if (modified) {
        saveAffiliateOrders(affOrders);
      }
      return settledCount;
    }
    window.processAffiliateSettlement = processAffiliateSettlement;

    // =========================================================================
    // AFFILIATE CLOUD SYNC ENGINE (TURSO DB & REALTIME BROADCAST)
    // =========================================================================
    async function syncAffiliateRegistrationToCloud(buyerEmail, buyerName, referrerCode, authType = "EMAIL") {
      try {
        if (!buyerEmail || !referrerCode) return;
        const cleanRef = String(referrerCode).trim().toLowerCase();
        const cleanEmail = String(buyerEmail).trim().toLowerCase();
        if (!cleanEmail || !cleanRef || cleanEmail === cleanRef || cleanEmail.split("@")[0] === cleanRef) return;

        // 1. Post trực tiếp lên Cloudflare Worker Turso Database (SSOT tập trung toàn cầu)
        fetch("https://mmo-shop-api.manhdongvtc.workers.dev/api/affiliate/register", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            buyerEmail: cleanEmail,
            buyerName: buyerName || cleanEmail.split("@")[0],
            referrerCode: cleanRef,
            authType: authType
          }),
          keepalive: true
        }).catch(e => console.warn("Worker affiliate register error:", e));

        // 2. Phát sóng BroadcastChannel tức thì xuyên tab/cửa sổ cùng trình duyệt (0ms)
        try {
          if (typeof BroadcastChannel !== "undefined") {
            const bc = new BroadcastChannel("mmo_affiliate_channel");
            bc.postMessage({
              type: "NEW_F1_MEMBER",
              member: {
                name: buyerName || cleanEmail.split("@")[0],
                email: cleanEmail,
                referredBy: cleanRef,
                authType: authType,
                created: new Date().toLocaleDateString("vi-VN")
              }
            });
            setTimeout(() => bc.close(), 1000);
          }
        } catch(e) {}
      } catch(err) {
        console.warn("syncAffiliateRegistrationToCloud err:", err);
      }
    }
    window.syncAffiliateRegistrationToCloud = syncAffiliateRegistrationToCloud;

    async function fetchCloudAffiliateMembers(referrerCode) {
      try {
        if (!referrerCode) return [];
        const cleanRef = String(referrerCode).trim().toLowerCase();
        const res = await fetch("https://mmo-shop-api.manhdongvtc.workers.dev/api/affiliate/members?referrer=" + encodeURIComponent(cleanRef), {
          method: "GET",
          headers: { "Accept": "application/json" }
        });
        const json = await res.json().catch(() => null);
        if (json && json.status === "success" && Array.isArray(json.members)) {
          return json.members;
        }
      } catch(e) {
        console.warn("fetchCloudAffiliateMembers error:", e);
      }
      return [];
    }
    window.fetchCloudAffiliateMembers = fetchCloudAffiliateMembers;

    function renderAffiliateDashboard() {
      try {
        if (!currentUser) return;
        const affCode = (currentUser.email ? currentUser.email.split('@')[0] : (currentUser.userId || "aff")).toLowerCase();
        const myEmail = (currentUser.email || "").toLowerCase().trim();

        // 0. Tự động quét và quyết toán các khoản hoa hồng đã qua 3 ngày
        if (typeof processAffiliateSettlement === "function") {
          processAffiliateSettlement();
        }

        // 1. Điền link giới thiệu vào ô input
        const refLinkInp = document.getElementById("affRefLinkInput");
        if (refLinkInp) {
          refLinkInp.value = window.location.origin + window.location.pathname + "?ref=" + encodeURIComponent(affCode);
        }

        function renderAffiliateF1AndCommissions() {
          const allUsers = (typeof getRegisteredUsers === "function") ? getRegisteredUsers() : [];
          const f1Users = allUsers.filter(function(u) {
            if (!u || !u.referredBy) return false;
            const ref = (u.referredBy || "").toLowerCase().trim();
            return ref === affCode || ref === myEmail || ref === affCode.split("@")[0];
          });

          const affOrders = (typeof getAffiliateOrders === "function") ? getAffiliateOrders() : [];
          const myAffOrders = affOrders.filter(function(o) {
            const rEmail = (o.referrerEmail || "").toLowerCase().trim();
            const rCode = (o.referrerCode || "").toLowerCase().trim();
            return rEmail === myEmail || rCode === affCode;
          });

          const pendingCommissions = myAffOrders.filter(o => o.status === "HOLDING");
          const approvedCommissions = myAffOrders.filter(o => o.status === "APPROVED");

          const totalPending = pendingCommissions.reduce(function(sum, o) {
            return sum + (Number(o.commissionAmount) || 0);
          }, 0);

          const totalApproved = approvedCommissions.reduce(function(sum, o) {
            return sum + (Number(o.commissionAmount) || 0);
          }, 0);

          // Cập nhật các thẻ số liệu
          const affPending = document.getElementById("affPendingComm");
          if (affPending) affPending.innerText = (typeof formatVND === "function") ? formatVND(totalPending) : (totalPending.toLocaleString("vi-VN") + " đ");

          const affApproved = document.getElementById("affApprovedComm");
          if (affApproved) affApproved.innerText = (typeof formatVND === "function") ? formatVND(totalApproved) : (totalApproved.toLocaleString("vi-VN") + " đ");

          const affF1Count = document.getElementById("affTotalF1Count");
          if (affF1Count) affF1Count.innerText = f1Users.length;

          const affF1Orders = document.getElementById("affTotalF1Orders");
          if (affF1Orders) affF1Orders.innerText = myAffOrders.filter(o => o.status !== "CANCELLED").length;

          const affF1Badge = document.getElementById("affF1ListBadge");
          if (affF1Badge) affF1Badge.innerText = f1Users.length + " thành viên";

          // Điền bảng danh sách thành viên F1
          const tbody = document.getElementById("affF1TableBody");
          if (tbody) {
            if (f1Users.length === 0) {
              tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:24px; color:#64748b;">Chưa có thành viên nào đăng ký qua link của bạn. Hãy chia sẻ link ngay để nhận hoa hồng!</td></tr>';
            } else {
              tbody.innerHTML = f1Users.map(function(u) {
                const uOrders = myAffOrders.filter(function(o) {
                  return (o.buyerEmail || "").toLowerCase().trim() === (u.email || "").toLowerCase().trim();
                });
                const uComm = uOrders.reduce(function(sum, o) { return sum + (Number(o.commissionAmount) || 0); }, 0);
                return '<tr>' +
                  '<td style="font-weight:700; color:#fff; vertical-align:middle;"><i class="fa-solid fa-user-tag green" style="margin-right:6px;"></i>' + escapeHtml(u.name || u.email.split("@")[0]) + '</td>' +
                  '<td style="color:#94a3b8; font-family:monospace; vertical-align:middle;">' + escapeHtml(u.email) + '</td>' +
                  '<td style="color:#64748b; vertical-align:middle;">' + escapeHtml(u.created || '2026') + '</td>' +
                  '<td style="font-weight:700; color:#10b981; vertical-align:middle;">' + uOrders.length + ' đơn (' + (typeof formatVND === "function" ? formatVND(uComm) : uComm + " đ") + ')</td>' +
                  '<td style="vertical-align:middle;"><span style="background:rgba(16,185,129,0.15); color:#10b981; padding:3px 8px; border-radius:4px; font-weight:700; font-size:0.75rem;">Đang hoạt động</span></td>' +
                '</tr>';
              }).join('');
            }
          }

          // Điền bảng lịch sử hoa hồng
          const commTbody = document.getElementById("affCommHistoryTableBody");
          const commBadge = document.getElementById("affCommCountBadge");
          if (commBadge) commBadge.innerText = myAffOrders.length + " đơn hoa hồng";

          if (commTbody) {
            if (myAffOrders.length === 0) {
              commTbody.innerHTML = '<tr><td colspan="8" style="text-align:center; padding:28px; color:#64748b;">Chưa có đơn hàng nào phát sinh hoa hồng. Chia sẻ link giới thiệu của bạn để nhận hoa hồng 10% - 30% trên mỗi đơn hàng!</td></tr>';
            } else {
              const nowTs = Date.now();
              commTbody.innerHTML = myAffOrders.map(function(o) {
                const oId = o.orderId || "";
                const dateStr = o.createdAt ? new Date(o.createdAt).toLocaleString("vi-VN", { hour:"2-digit", minute:"2-digit", day:"2-digit", month:"2-digit", year:"numeric" }) : "--";
                const totalStr = (typeof formatVND === "function") ? formatVND(o.orderTotal) : (o.orderTotal.toLocaleString("vi-VN") + " đ");
                const commStr = (typeof formatVND === "function") ? formatVND(o.commissionAmount) : (o.commissionAmount.toLocaleString("vi-VN") + " đ");

                let holdText = "";
                let statusBadge = "";

                if (o.status === "HOLDING") {
                  const remainMs = Math.max(0, (o.holdUntil || 0) - nowTs);
                  const totalHours = Math.floor(remainMs / (1000 * 60 * 60));
                  const days = Math.floor(totalHours / 24);
                  const hours = totalHours % 24;
                  const minutes = Math.floor((remainMs % (1000 * 60 * 60)) / (1000 * 60));

                  let countdownStr = "";
                  if (days > 0) countdownStr = days + " ngày " + hours + " giờ";
                  else if (hours > 0) countdownStr = hours + " giờ " + minutes + " phút";
                  else countdownStr = minutes + " phút";

                  holdText = '<span style="color:#f59e0b; font-weight:700; font-size:0.78rem; display:inline-flex; align-items:center; gap:5px;"><i class="fa-solid fa-hourglass-half fa-spin"></i> Còn ' + countdownStr + '</span>';
                  statusBadge = '<span style="background:rgba(245,158,11,0.18); border:1px solid #f59e0b; color:#fbbf24; font-weight:800; padding:3px 8px; border-radius:4px; font-size:0.72rem; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-clock"></i> Tạm Giữ 3 Ngày</span>';
                } else if (o.status === "APPROVED") {
                  holdText = '<span style="color:#10b981; font-weight:700; font-size:0.78rem; display:inline-flex; align-items:center; gap:5px;"><i class="fa-solid fa-circle-check"></i> Đã hoàn tất 3 ngày</span>';
                  statusBadge = '<span style="background:rgba(16,185,129,0.18); border:1px solid #10b981; color:#34d399; font-weight:800; padding:3px 8px; border-radius:4px; font-size:0.72rem; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-wallet"></i> Đã Vào Ví (+' + commStr + ')</span>';
                } else if (o.status === "CANCELLED") {
                  holdText = '<span style="color:#ef4444; font-weight:600; font-size:0.78rem; display:inline-flex; align-items:center; gap:5px;"><i class="fa-solid fa-ban"></i> Đã dừng giữ</span>';
                  statusBadge = '<span style="background:rgba(239,68,68,0.18); border:1px solid #ef4444; color:#f87171; font-weight:800; padding:3px 8px; border-radius:4px; font-size:0.72rem; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;" title="' + escapeHtml(o.cancelReason || 'Đơn hoàn tiền / khiếu nại') + '"><i class="fa-solid fa-circle-xmark"></i> Đã Hủy (Hoàn Tiền)</span>';
                }

                return '<tr>' +
                  '<td style="font-family:monospace; font-weight:800; color:#38bdf8; font-size:0.82rem; white-space:nowrap;">#' + escapeHtml(oId) + '</td>' +
                  '<td style="font-size:0.75rem; color:#94a3b8; white-space:nowrap;">' + dateStr + '</td>' +
                  '<td style="font-size:0.82rem; color:#fff; white-space:nowrap;"><strong style="display:block;">' + escapeHtml(o.buyerName || o.buyerEmail.split("@")[0]) + '</strong><span style="color:#94a3b8; font-size:0.72rem; font-family:monospace;">' + escapeHtml(o.buyerEmail) + '</span></td>' +
                  '<td style="font-size:0.82rem; color:#cbd5e1;"><strong style="color:#fff; display:block;">' + escapeHtml(o.productName || 'Sản phẩm MMO') + '</strong>' + (o.variant && o.variant !== 'Mặc định' ? ('<span style="font-size:0.72rem; color:#a855f7;">' + escapeHtml(o.variant) + '</span>') : '') + '</td>' +
                  '<td style="font-weight:700; color:#fff; font-size:0.82rem; white-space:nowrap;">' + totalStr + '</td>' +
                  '<td style="font-weight:800; color:#10b981; font-size:0.85rem; white-space:nowrap;">+' + commStr + ' <span style="font-size:0.7rem; color:#94a3b8;">(' + (o.commissionRate || 10) + '%)</span></td>' +
                  '<td style="white-space:nowrap;">' + holdText + '</td>' +
                  '<td style="white-space:nowrap;">' + statusBadge + '</td>' +
                '</tr>';
              }).join('');
            }
          }
        }

        // Render ngay lập tức từ bộ nhớ cục bộ (0ms không giật lag)
        renderAffiliateF1AndCommissions();

        // Đồng bộ tức thì từ Cloudflare Worker Turso DB để lấy thành viên đăng ký từ máy khác / trình duyệt khác
        if (typeof fetchCloudAffiliateMembers === "function") {
          fetchCloudAffiliateMembers(affCode).then(function(cloudMembers) {
            if (Array.isArray(cloudMembers) && cloudMembers.length > 0) {
              let localUsers = getRegisteredUsers();
              let updated = false;
              cloudMembers.forEach(function(cm) {
                const cmEmail = (cm.email || "").toLowerCase().trim();
                if (!cmEmail) return;
                const found = localUsers.find(u => (u.email || "").toLowerCase().trim() === cmEmail);
                if (!found) {
                  localUsers.push({
                    name: cm.name || cmEmail.split("@")[0],
                    email: cmEmail,
                    role: "MEMBER",
                    balance: 0,
                    created: cm.created || new Date().toLocaleDateString("vi-VN"),
                    avatar: "https://api.dicebear.com/7.x/bottts/svg?seed=" + encodeURIComponent(cmEmail),
                    referredBy: affCode
                  });
                  updated = true;
                } else if (!found.referredBy || found.referredBy.toLowerCase().trim() !== affCode) {
                  found.referredBy = affCode;
                  updated = true;
                }
              });
              if (updated) {
                saveRegisteredUsers(localUsers);
                renderAffiliateF1AndCommissions();
              }
            }
          }).catch(function() {});
        }

      } catch(e) {
        console.error("renderAffiliateDashboard error:", e);
      }
    }
    window.renderAffiliateDashboard = renderAffiliateDashboard;

    // Lắng nghe BroadcastChannel cập nhật F1 thời gian thực (0ms)
    try {
      if (typeof window !== "undefined" && typeof BroadcastChannel !== "undefined") {
        const affBc = new BroadcastChannel("mmo_affiliate_channel");
        affBc.onmessage = function(ev) {
          if (ev && ev.data && ev.data.type === "NEW_F1_MEMBER") {
            const mem = ev.data.member;
            if (mem && mem.referredBy) {
              const curRef = (currentUser && currentUser.email ? currentUser.email.split("@")[0] : "").toLowerCase();
              const myEmail = (currentUser && currentUser.email ? currentUser.email : "").toLowerCase();
              if (curRef && (curRef === mem.referredBy.toLowerCase() || myEmail === mem.referredBy.toLowerCase())) {
                let uList = getRegisteredUsers();
                if (!uList.some(u => (u.email || "").toLowerCase().trim() === mem.email.toLowerCase().trim())) {
                  uList.push(mem);
                  saveRegisteredUsers(uList);
                  if (typeof renderAffiliateDashboard === "function") {
                    renderAffiliateDashboard();
                  }
                }
              }
            }
          }
        };
      }
    } catch(e) {}

    function saveProductsToStorage() {
      // Dùng setTimeout(0) để nhả main thread, tránh đơ trang khi data lớn
      setTimeout(function() {
        try {
          if (MOCK_DATA && MOCK_DATA.products) {
            // [BẢO TỒN 100% ẢNH SẢN PHẨM]: Tuyệt đối không cắt lát base64 làm hỏng ảnh
            const prodsJson = JSON.stringify(MOCK_DATA.products);
            localStorage.setItem("mmo_admin_products", prodsJson);
            localStorage.setItem("mmo_products", prodsJson);
          }
        } catch(e) {
          console.warn("Storage quota warning when saving products:", e);
          try {
            // Nếu vượt quota localStorage, chỉ giảm bớt danh sách accounts tồn kho, bảo toàn 100% ảnh
            const safeProds = (MOCK_DATA.products || []).map(function(p) {
              const cp = Object.assign({}, p);
              if (cp.variants && Array.isArray(cp.variants)) {
                cp.variants = cp.variants.map(function(v) {
                  const vc = Object.assign({}, v);
                  if (vc.accounts && vc.accounts.length > 50) vc.accounts = vc.accounts.slice(0, 50);
                  return vc;
                });
              }
              return cp;
            });
            const safeJson = JSON.stringify(safeProds);
            localStorage.setItem("mmo_admin_products", safeJson);
            localStorage.setItem("mmo_products", safeJson);
          } catch(e2) {
            console.error("Critical: Could not save products to storage:", e2);
          }
        }
      }, 0);
    }
    window.saveProductsToStorage = saveProductsToStorage;

    // ==========================================
    // ĐỒNG BỘ SẢN PHẨM TỪ MÁY CHỦ / GOOGLE SHEETS
    // Đảm bảo khi admin đăng sản phẩm mới, mọi người khác đều xem được ngay lập tức
    // ==========================================
    var _isSyncingProductsFromBackend = false;
    async function syncProductsFromBackend() {
      if (_isSyncingProductsFromBackend) return;
      if (typeof document !== "undefined" && document.hidden) return; // Bỏ qua nếu tab đang ẩn
      try {
        _isSyncingProductsFromBackend = true;
        if (typeof callGasApi !== "function") return;
        const res = await callGasApi("getProducts");
        if (res && res.success && Array.isArray(res.products) && res.products.length > 0) {
          if (res.apiProductMappings && typeof res.apiProductMappings === 'object') {
            try {
              const curMappings = (typeof getApiProductMappings === "function") ? getApiProductMappings() : {};
              // Merge: server cung cấp sourceStock mới nhất, local giữ apiKey/baseUrl/config do admin setup
              // Với mỗi key, server.sourceStock > local.sourceStock (để tránh stale 0 overwrite)
              const mergedMappings = Object.assign({}, curMappings, res.apiProductMappings);
              // Nhưng giữ lại apiKey và baseUrl từ local nếu server không có
              Object.keys(curMappings).forEach(function(k) {
                if (mergedMappings[k] && curMappings[k]) {
                  if (!mergedMappings[k].apiKey && curMappings[k].apiKey) mergedMappings[k].apiKey = curMappings[k].apiKey;
                  if (!mergedMappings[k].baseUrl && curMappings[k].baseUrl) mergedMappings[k].baseUrl = curMappings[k].baseUrl;
                }
              });
              localStorage.setItem("mmo_api_product_mappings", JSON.stringify(mergedMappings));
            } catch(e) {}
          }
          let hasNewOrUpdated = false;
          const deletedIds = (typeof getDeletedProductIds === "function") ? getDeletedProductIds() : [];
          res.products.forEach(function(serverProd) {
            if (!serverProd || !serverProd.id) return;
            // CHẶN TUYỆT ĐỐI NẾU SẢN PHẨM NẰM TRONG DANH SÁCH ĐÃ XÓA HOẶC DUMMY
            if (typeof isProductDeleted === "function" && isProductDeleted(serverProd)) return;
            if (deletedIds.includes(serverProd.id)) return;
            if (serverProd.sold === 100 || serverProd.buffSold === 100) {
              serverProd.sold = 0;
              serverProd.buffSold = 0;
            }
            if (serverProd.category) serverProd.category = String(serverProd.category).replace(/&amp;/g, '&');
            // Chuẩn hóa biến thể từ server
            if (typeof serverProd.variants === "string") {
              try { serverProd.variants = JSON.parse(serverProd.variants); } catch(e) {}
            }
            // Khôi phục biến thể Paypal và bảo toàn tồn kho chính xác
            const isPaypalSync = (serverProd.id === "PROD_MTU9F5HN" || (serverProd.name && serverProd.name.toUpperCase().includes("PAYPAL") && serverProd.name.toUpperCase().includes("NGÂM")));
            if (isPaypalSync) {
              serverProd.name = "Paypal 2025 - 2016 Đã ngâm lâu cực kỳ Trâu";
              const s0 = (typeof getVariantStockCount === "function") ? getVariantStockCount(serverProd, 0) : 0;
              const s1 = (typeof getVariantStockCount === "function") ? getVariantStockCount(serverProd, 1) : 0;
              if (!serverProd.variants || serverProd.variants.length <= 1) {
                serverProd.variants = [
                  { name: "paypal đã ngâm lâu", price: 50000, stock: s0 },
                  { name: "paypal Đã Nhận Tiền", price: 100000, stock: s1 }
                ];
              } else {
                if (serverProd.variants[0]) {
                  serverProd.variants[0].name = "paypal đã ngâm lâu";
                  serverProd.variants[0].price = 50000;
                  serverProd.variants[0].stock = s0;
                }
                if (serverProd.variants[1]) {
                  serverProd.variants[1].name = "paypal Đã Nhận Tiền";
                  serverProd.variants[1].price = 100000;
                  serverProd.variants[1].stock = s1;
                }
              }
            }
            if (serverProd.variants && Array.isArray(serverProd.variants) && serverProd.variants.length > 0) {
              let varSum = 0;
              serverProd.variants.forEach((v, vidx) => {
                let vs = (typeof v.stock === "number") ? Math.max(0, v.stock) : 0;
                v.stock = vs;
                varSum += vs;
              });
              serverProd.stock = varSum;
            }
            if (serverProd.name && serverProd.name.toUpperCase().includes("TIKTOK") && (!serverProd.category || !serverProd.category.toUpperCase().includes("TIKTOK"))) {
              serverProd.category = "TikTok";
            }
            const existingIdx = MOCK_DATA.products.findIndex(function(p) { 
              return p && p.id === serverProd.id;
            });
            // [LOCAL-FIRST MASTER]: Kho tài khoản nội bộ là Nguồn Chân Lý Duy Nhất, không bị xóa bởi server
            const localStockMap = (typeof getProductStocksMap === "function") ? getProductStocksMap() : {};

            let isManuallyCleared = false;
            try {
              const clMap = JSON.parse(localStorage.getItem("mmo_manually_cleared_products") || "{}");
              if (clMap[serverProd.id] || (typeof isSameOrAliasProduct === "function" && isSameOrAliasProduct(serverProd.id, "PROD_MTPIJ9XV") && (clMap["PROD_MTPIJ9XV"] || clMap["PROD_MTPG0PUD"] || clMap["SP_TIKTOK_BRAZIL"]))) {
                isManuallyCleared = true;
              }
            } catch(e) {}

            const realLocalAccounts = Array.isArray(localStockMap[serverProd.id]) ? localStockMap[serverProd.id].length : 0;

            if (serverProd.variants && Array.isArray(serverProd.variants) && serverProd.variants.length > 0) {
              let varSum = 0;
              serverProd.variants.forEach((v, vidx) => {
                const vk = getVariantStockKey(serverProd.id, vidx);
                if (Array.isArray(localStockMap[vk]) && localStockMap[vk].length > 0) {
                  v.stock = localStockMap[vk].length;
                } else {
                  v.stock = (typeof v.stock === "number") ? Math.max(0, v.stock) : 0;
                }
                varSum += v.stock;
              });
              serverProd.stock = varSum;
            } else if (realLocalAccounts > 0) {
              // Kho cục bộ thực sự đang có tài khoản (> 0): Cập nhật theo số lượng thực tế và gỡ bỏ cờ cleared
              serverProd.stock = realLocalAccounts;
              try {
                const clMap = JSON.parse(localStorage.getItem("mmo_manually_cleared_products") || "{}");
                delete clMap[serverProd.id];
                delete clMap["PROD_MTPIJ9XV"];
                delete clMap["PROD_MTPG0PUD"];
                delete clMap["SP_TIKTOK_BRAZIL"];
                delete clMap["PROD_MTU9F5HN"];
                delete clMap["PROD_MTU9F5HN__VAR__0"];
                delete clMap["PROD_MTU9F5HN__VAR__1"];
                localStorage.setItem("mmo_manually_cleared_products", JSON.stringify(clMap));
              } catch(e) {}
            } else if (isManuallyCleared) {
              // Đã xóa kho thủ công và chưa nạp hàng mới: Ép tồn kho tổng và toàn bộ biến thể về 0
              serverProd.stock = 0;
              if (Array.isArray(serverProd.variants)) {
                serverProd.variants.forEach(v => v.stock = 0);
              }
            } else {
              // Kế thừa tồn kho từ Google Sheets nếu không bị xóa thủ công
              serverProd.stock = Number(serverProd.stock) || 0;
            }
            if (existingIdx !== -1) {
              const currentProd = MOCK_DATA.products[existingIdx];
              // [LOCAL-FIRST EDIT MASTER]: Nếu sản phẩm vừa được sửa gần đây (< 15 phút), ưu tiên dữ liệu admin đã sửa
              const isLocallyFresh = !!(currentProd._lastEditedAt && (Date.now() - currentProd._lastEditedAt < 900000));

              // Bảo vệ tồn kho nếu sản phẩm đang bật On-Demand API
              // QUAN TRỌNG: Không check balance ở đây — balance chỉ cần check khi mua hàng
              // Non-admin không có balance thật → không được dùng balance để ẩn tồn kho
              const isApiTypeGas = (serverProd.deliveryType === 'api' || serverProd.delivery_type === 'api' || currentProd.deliveryType === 'api' || currentProd.delivery_type === 'api' || (typeof isProductApi === 'function' && isProductApi(currentProd)));
              const existingApiMap = (typeof getApiProductMapping === "function") ? getApiProductMapping(currentProd.id) : (currentProd.apiMapping || null);
              if (isApiTypeGas || (existingApiMap && existingApiMap.enabled && existingApiMap.sourceProdId)) {
                currentProd.deliveryType = 'api';
                serverProd.deliveryType = 'api';
                currentProd.delivery_type = 'api';
                serverProd.delivery_type = 'api';
                let apiStock = 0;
                if (existingApiMap && existingApiMap.sourceStock !== undefined && Number(existingApiMap.sourceStock) >= 0) {
                  apiStock = Number(existingApiMap.sourceStock);
                } else if (typeof getShopVariantStock === 'function') {
                  apiStock = getShopVariantStock(currentProd, 0);
                } else {
                  apiStock = Number(currentProd.stock) || 0;
                }
                serverProd.stock = apiStock;
                currentProd.stock = apiStock;
                if (Array.isArray(serverProd.variants)) {
                  serverProd.variants.forEach(v => { v.stock = apiStock; });
                }
                if (Array.isArray(currentProd.variants)) {
                  currentProd.variants.forEach(v => { v.stock = apiStock; });
                }
              }

              // [UNIFIED MASTER]: Hợp nhất biến thể từ Google Sheets với kho nội bộ (Bảo toàn tài khoản kho)
              let finalVariants = [];
              if (isLocallyFresh && currentProd.variants && Array.isArray(currentProd.variants) && currentProd.variants.length > 0) {
                finalVariants = currentProd.variants;
              } else if (serverProd.variants && Array.isArray(serverProd.variants) && serverProd.variants.length > 0) {
                finalVariants = serverProd.variants.map((sv, svIdx) => {
                  const matchedLocalV = (currentProd.variants && (currentProd.variants[svIdx] || currentProd.variants.find(lv => lv && lv.name && lv.name.trim().toLowerCase() === String(sv.name || '').trim().toLowerCase()))) || null;
                  const accs = (matchedLocalV && Array.isArray(matchedLocalV.accounts) && matchedLocalV.accounts.length > 0) ? matchedLocalV.accounts : (Array.isArray(sv.accounts) ? sv.accounts : []);
                  const soldAccs = (matchedLocalV && Array.isArray(matchedLocalV.soldAccounts) && matchedLocalV.soldAccounts.length > 0) ? matchedLocalV.soldAccounts : (Array.isArray(sv.soldAccounts) ? sv.soldAccounts : []);
                  return Object.assign({}, sv, {
                    name: sv.name || (matchedLocalV ? matchedLocalV.name : ("Gói " + (svIdx + 1))),
                    price: sv.price !== undefined ? Number(sv.price) : (matchedLocalV ? Number(matchedLocalV.price) : Number(currentProd.price || 0)),
                    accounts: accs,
                    soldAccounts: soldAccs
                  });
                });
              } else if (currentProd.variants && Array.isArray(currentProd.variants) && currentProd.variants.length > 0) {
                finalVariants = currentProd.variants;
              }

              const updatedName = isLocallyFresh ? (currentProd.name || serverProd.name) : (serverProd.name || currentProd.name);
              const updatedCategory = isLocallyFresh ? (currentProd.category || serverProd.category) : (serverProd.category || currentProd.category);
              const isCurValidImg = typeof currentProd.image === "string" && currentProd.image.trim() !== "" && !currentProd.image.includes("placeholder") && !currentProd.image.includes("undefined");
              const isServerValidImg = typeof serverProd.image === "string" && serverProd.image.trim() !== "" && !serverProd.image.includes("placeholder") && !serverProd.image.includes("undefined");
              const updatedImage = (isLocallyFresh || isCurValidImg) ? currentProd.image : (isServerValidImg ? serverProd.image : currentProd.image);
              const updatedDesc = isLocallyFresh ? (currentProd.description || serverProd.description) : (serverProd.description || currentProd.description);
              const updatedWarranty = isLocallyFresh ? (currentProd.warranty || serverProd.warranty) : (serverProd.warranty || currentProd.warranty);
              const updatedCommission = isLocallyFresh ? (currentProd.commission || serverProd.commission) : (serverProd.commission || currentProd.commission);

              // Tính toán tồn kho từng biến thể: Kho nội bộ ưu tiên hàng đầu, nếu chưa có thì kế thừa từ Google Sheets
              let totalCalculatedStock = 0;
              finalVariants.forEach((v, vidx) => {
                const vk = (typeof getVariantStockKey === "function") ? getVariantStockKey(currentProd.id, vidx) : (currentProd.id + "__VAR__" + vidx);
                const localCount = (typeof getStockCountByVariant === "function") ? getStockCountByVariant(currentProd.id, vidx, currentProd.name) : 0;
                const svStock = (serverProd && serverProd.variants && serverProd.variants[vidx] && typeof serverProd.variants[vidx].stock === "number") ? Math.max(0, serverProd.variants[vidx].stock) : 0;
                const accsCount = Array.isArray(v.accounts) ? v.accounts.length : 0;

                if (accsCount > 0) {
                  v.stock = accsCount;
                } else if (localCount > 0) {
                  v.stock = localCount;
                } else if (Array.isArray(localStockMap[vk]) && localStockMap[vk].length > 0) {
                  v.stock = localStockMap[vk].length;
                } else if (!isManuallyCleared && svStock > 0) {
                  v.stock = svStock;
                } else if (typeof v.stock === "number" && v.stock > 0) {
                  // Giữ nguyên tồn kho nếu đã có giá trị hợp lệ
                } else {
                  v.stock = (!isManuallyCleared && serverProd && typeof serverProd.stock === "number" && finalVariants.length === 1) ? serverProd.stock : 0;
                }
                totalCalculatedStock += (Number(v.stock) || 0);
              });

              if (finalVariants.length === 0) {
                if (realLocalAccounts > 0) totalCalculatedStock = realLocalAccounts;
                else if (!isManuallyCleared && serverProd && typeof serverProd.stock === "number") totalCalculatedStock = serverProd.stock;
                else totalCalculatedStock = isManuallyCleared ? 0 : (Number(currentProd.stock) || 0);
              }

              const newPrice = isLocallyFresh 
                ? (currentProd.price || (finalVariants[0] && Number(finalVariants[0].price)) || serverProd.price)
                : (finalVariants[0] ? (Number(finalVariants[0].price) || currentProd.price || serverProd.price) : (currentProd.price || serverProd.price));

              let changed = (currentProd.stock !== totalCalculatedStock || currentProd.price !== newPrice || currentProd.name !== updatedName);
              if (!changed && Array.isArray(currentProd.variants)) {
                if (currentProd.variants.length !== finalVariants.length) {
                  changed = true;
                } else {
                  for (let vi = 0; vi < finalVariants.length; vi++) {
                    if (!currentProd.variants[vi] || currentProd.variants[vi].name !== finalVariants[vi].name || currentProd.variants[vi].price !== finalVariants[vi].price || currentProd.variants[vi].stock !== finalVariants[vi].stock) {
                      changed = true;
                      break;
                    }
                  }
                }
              }

              // [UNIFIED WAREHOUSE CORE]: Đảm bảo Google Sheets không bao giờ đè kho
              if (typeof MMO_WAREHOUSE !== "undefined" && MMO_WAREHOUSE.getStock) {
                if (Array.isArray(finalVariants)) {
                  finalVariants.forEach((v, vi) => {
                    const ws = MMO_WAREHOUSE.getStock(currentProd.id, vi);
                    if (ws > 0) v.stock = ws;
                  });
                }
                const totalWs = MMO_WAREHOUSE.getStock(currentProd.id, null);
                if (totalWs > 0) totalCalculatedStock = totalWs;
              }

              // Cập nhật MOCK_DATA với biến thể và thông tin mới nhất từ máy chủ
              const baseMerge = isLocallyFresh ? Object.assign({}, serverProd, currentProd) : Object.assign({}, currentProd, serverProd);
              MOCK_DATA.products[existingIdx] = Object.assign(baseMerge, {
                id: currentProd.id || serverProd.id,
                name: updatedName,
                category: updatedCategory,
                image: updatedImage,
                description: updatedDesc,
                warranty: updatedWarranty,
                commission: updatedCommission,
                price: newPrice,
                stock: totalCalculatedStock,
                variants: finalVariants,
                _lastEditedAt: currentProd._lastEditedAt || 0
              });

              // [FRESH API MAPPING]: Luôn dùng sourceStock từ mmo_api_product_mappings (fresh) sau merge
              // Tránh serverProd.apiMapping (stale, sourceStock=0) ghi đè apiMapping đã cập nhật của admin
              try {
                const freshMaps = (typeof getApiProductMappings === "function") ? getApiProductMappings() : {};
                const mergedProdId = MOCK_DATA.products[existingIdx].id;
                if (freshMaps[mergedProdId] && freshMaps[mergedProdId].enabled && freshMaps[mergedProdId].sourceProdId) {
                  // Admin: dùng fresh local maps
                  MOCK_DATA.products[existingIdx].apiMapping = freshMaps[mergedProdId];
                } else if (serverProd && serverProd.apiMapping && serverProd.apiMapping.enabled && serverProd.apiMapping.sourceProdId) {
                  // Non-admin: fallback về apiMapping từ GAS (admin đã save có sourceStock)
                  MOCK_DATA.products[existingIdx].apiMapping = serverProd.apiMapping;
                  // Cache vào localStorage để getApiProductMapping() dùng được
                  try {
                    freshMaps[mergedProdId] = serverProd.apiMapping;
                    localStorage.setItem("mmo_api_product_mappings", JSON.stringify(freshMaps));
                  } catch(e2) {}
                }
              } catch(e) {}

              if (typeof recordProductVariants === "function" && finalVariants.length > 0) {
                recordProductVariants(currentProd.id, finalVariants, updatedName);
              }
              if (changed) {
                hasNewOrUpdated = true;
              }
            } else {
              if (!deletedIds.includes(serverProd.id) && !(typeof isProductDeleted === "function" && isProductDeleted(serverProd))) {
                MOCK_DATA.products.push(serverProd);
                hasNewOrUpdated = true;
              }
            }
          });

          if (Array.isArray(res.categories) && res.categories.length > 0) {
            res.categories.forEach(function(cat) {
              if (cat && !MOCK_DATA.categories.includes(cat)) {
                MOCK_DATA.categories.push(cat);
              }
            });
          }

          if (hasNewOrUpdated) {
            if (MOCK_DATA && Array.isArray(MOCK_DATA.products) && typeof isProductDeleted === "function") {
              MOCK_DATA.products = MOCK_DATA.products.filter(function(p) { return !isProductDeleted(p); });
            }
            saveProductsToStorage();
            if (typeof _viewDirty !== "undefined") {
              _viewDirty["viewStore"] = true;
              _viewDirty["viewAllProducts"] = true;
              _viewDirty["viewAdmin"] = true;
            }
            if (typeof renderProductGrid === "function") renderProductGrid();
            if (typeof renderBestSellers === "function") renderBestSellers();
            if (typeof renderRecommended === "function") renderRecommended();
            if (typeof renderDynamicFlankingProducts === "function") renderDynamicFlankingProducts();
            if (typeof renderAllProductsPage === "function") renderAllProductsPage();
            if (typeof renderAdminDashboard === "function") renderAdminDashboard();
            if (typeof initStockManagementUI === "function") initStockManagementUI();
            if (typeof applyBrandCustomizations === "function") applyBrandCustomizations();
            if (typeof syncZaloLinks === "function") syncZaloLinks();
            if (typeof syncTelegramLinks === "function") syncTelegramLinks();
            if (typeof syncMarqueeNotice === "function") syncMarqueeNotice();
            if (typeof renderCategories === "function") renderCategories();

            // Cập nhật ngay lập tức giao diện chi tiết sản phẩm nếu đang mở (giá, biến thể, tồn kho)
            if (currentSelectedProduct) {
              const curP = MOCK_DATA.products.find(p => p.id === currentSelectedProduct.id || (typeof isSameOrAliasProduct === "function" && isSameOrAliasProduct(p.id, currentSelectedProduct.id)));
              if (curP) {
                currentSelectedProduct = curP;
                if (typeof syncAllOpenViewsStock === "function") syncAllOpenViewsStock(curP.id, curP.stock, null, true);

                let activeVarIdx = (typeof currentSelectedVariantIndex !== "undefined") ? currentSelectedVariantIndex : 0;
                if (curP.variants && Array.isArray(curP.variants) && curP.variants.length > 0) {
                  const curStock = (typeof getVariantStockCount === "function") ? getVariantStockCount(curP, activeVarIdx) : 0;
                  if (curStock <= 0) {
                    const firstInStock = curP.variants.findIndex((v, i) => (typeof getVariantStockCount === "function" ? getVariantStockCount(curP, i) : 0) > 0);
                    if (firstInStock !== -1) activeVarIdx = firstInStock;
                  }
                }
                currentSelectedVariantIndex = activeVarIdx;

                const curVar = (curP.variants && curP.variants[activeVarIdx]) ? curP.variants[activeVarIdx] : (curP.variants && curP.variants[0]) ? curP.variants[0] : curP;
                const dtlPrice = document.getElementById("dtlPrice");
                if (dtlPrice && curVar) dtlPrice.innerText = formatVND(curVar.price !== undefined ? curVar.price : curP.price);

                const dtlTitle = document.getElementById("dtlTitle");
                if (dtlTitle && curP.name) dtlTitle.innerText = curP.name;
                const dtlImg = document.getElementById("dtlImage");
                if (dtlImg && curP.image) dtlImg.src = curP.image;
                const dtlDesc = document.getElementById("dtlFullDesc");
                if (dtlDesc && curP.description) dtlDesc.innerText = curP.description;
                const dtlWarranty = document.getElementById("dtlWarranty");
                if (dtlWarranty && curP.warranty) dtlWarranty.innerText = "🛡 " + curP.warranty;

                const pillsContainer = document.getElementById("dtlVariantPills");
                if (pillsContainer && Array.isArray(curP.variants) && curP.variants.length > 0) {
                  pillsContainer.innerHTML = curP.variants.map((v, idx) => {
                    let vStock = (typeof getVariantStockCount === "function") ? getVariantStockCount(curP, idx) : (Number(v.stock) || 0);
                    v.stock = vStock;
                    const stockBadge = vStock > 0 
                      ? '<small style="color:#10b981; font-weight:700; margin-left:6px; font-size:0.75rem;">(' + Number(vStock).toLocaleString("vi-VN") + ' acc)</small>' 
                      : '<small style="color:#ef4444; font-weight:700; margin-left:6px; font-size:0.75rem;">(0 acc)</small>';
                    return '<div class="variant-pill-option ' + (idx === activeVarIdx ? 'active' : '') + '" onclick="selectVariant(' + idx + ', ' + (v.price || 0) + ')">' +
                      '<span>' + escapeHtml(v.name || ("Gói " + (idx + 1))) + stockBadge + '</span>' +
                      '<span style="font-weight:700;">' + formatVND(v.price || 0) + '</span>' +
                    '</div>';
                  }).join("");
                }
                const curVarStock = (typeof getVariantStockCount === "function") ? getVariantStockCount(curP, activeVarIdx) : (curP.stock || 0);
                syncDetailStockUI(curVarStock);
              }
            }
          }
        }
      } catch(e) {
        console.warn("syncProductsFromBackend error:", e);
      } finally {
        _isSyncingProductsFromBackend = false;
      }
    }
    window.syncProductsFromBackend = syncProductsFromBackend;


