    function updateCommissionEstimate() {
      const comm = parseInt(document.getElementById("admProdCommission")?.value) || 10;
      const container = document.getElementById("admVariantsContainer") || document.getElementById("admVariantRowsContainer");
      const firstPriceInput = container ? container.querySelector(".adm-variant-price") : null;
      const price = parseInt(firstPriceInput?.value) || parseInt(document.getElementById("admProdPrice")?.value) || 0;
      const priceHidden = document.getElementById("admProdPrice");
      if (priceHidden) priceHidden.value = price;
      const est = Math.round(price * comm / 100);
      const preview = document.getElementById("admCommissionPreview");
      if (preview) {
        preview.innerText = "(~" + formatVND(est) + " / đơn hàng)";
      }
    }
    window.updateCommissionEstimate = updateCommissionEstimate;

    function handleSaveProduct(event) {
      if (event) event.preventDefault();
      const id = document.getElementById("admProdId")?.value.trim();
      const isEditing = !!id;
      const prodId = id || ("PROD_" + Date.now().toString(36).toUpperCase() + Math.floor(100 + Math.random() * 900).toString(36).toUpperCase());
      const name = document.getElementById("admProdName")?.value.trim();
      let category = (document.getElementById("admProdCategory")?.value || "Tài Khoản Khác").replace(/&amp;/g, '&');
      if (name.toUpperCase().includes("TIKTOK") && !category.toUpperCase().includes("TIKTOK")) {
        category = "TikTok";
      }
      const commissionVal = parseInt(document.getElementById("admProdCommission")?.value) || 10;
      const buffSold = parseInt(document.getElementById("admProdBuffSold")?.value) || 0;
      const rating = parseFloat(document.getElementById("admProdBuffRating")?.value) || 4.9;
      const reviewsCount = parseInt(document.getElementById("admProdBuffReviews")?.value) || 15;
      if (!name) {
        showToast("Vui lòng nhập tên sản phẩm!", "warning");
        return;
      }

      if (!MOCK_DATA.products) MOCK_DATA.products = [];
      const oldProd = isEditing ? MOCK_DATA.products.find(p => p && p.id === prodId) : null;
      const actualTargetId = (oldProd && oldProd.id) ? oldProd.id : prodId;
      const inputImg = document.getElementById("admProdImage")?.value.trim();
      const image = inputImg || (oldProd && oldProd.image) || (oldProd && oldProd.image_url) || (oldProd && oldProd.imageUrl) || "https://iili.io/nFV4Rln.png";
      const warranty = document.getElementById("admProdWarranty")?.value.trim() || "Bảo Hành 1 Đổi 1";
      const description = document.getElementById("admProdDesc")?.value.trim() || "";

      const container = document.getElementById("admVariantsContainer") || document.getElementById("admVariantRowsContainer");
      const varRows = container ? container.querySelectorAll(".adm-variant-row") : [];
      let variants = [];
      varRows.forEach((row, idx) => {
        const vName = row.querySelector(".adm-variant-name, input[type='text']")?.value.trim();
        const vPrice = parseInt(row.querySelector(".adm-variant-price, input[type='number']")?.value) || 0;
        if (vName) {
          let oldAccounts = [];
          let oldSold = [];
          if (oldProd && Array.isArray(oldProd.variants)) {
            const matchedOld = oldProd.variants.find(ov => ov && ov.name && ov.name.trim().toLowerCase() === vName.toLowerCase()) || oldProd.variants[idx];
            if (matchedOld) {
              oldAccounts = Array.isArray(matchedOld.accounts) ? matchedOld.accounts.slice() : [];
              oldSold = Array.isArray(matchedOld.soldAccounts) ? matchedOld.soldAccounts.slice() : [];
            }
          }
          let vStock = oldAccounts.length > 0 ? oldAccounts.length : ((typeof getVariantStockCount === "function") ? getVariantStockCount(actualTargetId, idx) : 0);
          variants.push({
            name: vName,
            price: vPrice,
            stock: vStock,
            accounts: oldAccounts,
            soldAccounts: oldSold
          });
        }
      });

      if (variants.length === 0) {
        showToast("Vui lòng thêm ít nhất 1 biến thể với tên và giá bán!", "warning");
        return;
      }

      const effectivePrice = variants[0] ? (Number(variants[0].price) || 0) : 0;
      const priceHiddenInput = document.getElementById("admProdPrice");
      if (priceHiddenInput) priceHiddenInput.value = effectivePrice;

      const isApiSelected = document.getElementById("admProdTypeApi")?.checked;
      const apiProviderVal = document.getElementById("admProdApiProvider")?.value || "shop1989nd";
      const apiSourceProdIdVal = document.getElementById("admProdApiSourceSelect")?.value || "";

      let totalCalculatedStock = 0;
      variants.forEach(v => totalCalculatedStock += (Number(v.stock) || 0));
      if (oldProd && totalCalculatedStock === 0 && typeof getProductStockCount === "function") {
        const s = getProductStockCount(actualTargetId);
        if (s > 0) totalCalculatedStock = s;
      }

      let liveSourceStock = 0;
      let liveSourcePrice = 0;
      let liveSourceName = "";
      if (isApiSelected && apiSourceProdIdVal) {
        const prodsSrc = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
          ? window.cachedSourceProducts
          : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);
        const foundSrc = prodsSrc.find(s => String(s.id) === String(apiSourceProdIdVal) && (!apiProviderVal || s.provider === apiProviderVal))
          || prodsSrc.find(s => String(s.id) === String(apiSourceProdIdVal));
        if (foundSrc) {
          liveSourceStock = (typeof foundSrc.amount === "number") ? foundSrc.amount : (parseInt(foundSrc.amount) || 0);
          liveSourcePrice = (typeof foundSrc.price === "number") ? foundSrc.price : (parseInt(foundSrc.price) || 0);
          liveSourceName = foundSrc.name || "";
        } else {
          liveSourceStock = (oldProd && typeof oldProd.stock === "number") ? oldProd.stock : 0;
        }
        variants.forEach(v => { v.stock = liveSourceStock; });
      }

      const prodData = {
        id: actualTargetId,
        name: name,
        category: category,
        price: effectivePrice,
        commission: commissionVal + "% (~" + formatVND(Math.round(effectivePrice * commissionVal / 100)) + ")",
        buffSold: buffSold,
        sold: (oldProd && oldProd.sold !== undefined) ? oldProd.sold : buffSold,
        stock: isApiSelected ? liveSourceStock : totalCalculatedStock,
        rating: rating,
        reviewCount: reviewsCount,
        image: image,
        image_url: image,
        imageUrl: image,
        warranty: warranty,
        description: description,
        variants: variants,
        deliveryType: isApiSelected ? "api" : "local",
        delivery_type: isApiSelected ? "api" : "local",
        _lastEditedAt: Date.now()
      };

      // Cập nhật bảng API Mappings ngay lập tức
      try {
        const maps = (typeof getApiProductMappings === "function") ? getApiProductMappings() : {};
        if (isApiSelected && apiSourceProdIdVal) {
          const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[apiProviderVal]) ? API_SOURCES[apiProviderVal] : { baseUrl: "https://sellmmo.vn", apiKey: "" };
          const mapItem = {
            enabled: true,
            provider: apiProviderVal,
            baseUrl: pCfg.baseUrl,
            apiKey: pCfg.apiKey,
            sourceProdId: String(apiSourceProdIdVal),
            sourceProdName: liveSourceName || ("Sản phẩm #" + apiSourceProdIdVal),
            sourcePrice: liveSourcePrice,
            sourceStock: liveSourceStock,
            targetProdId: actualTargetId,
            targetProdName: name
          };
          maps[actualTargetId] = mapItem;
          // Map toàn bộ biến thể
          variants.forEach((v, vIdx) => {
            maps[actualTargetId + '__VAR__' + vIdx] = mapItem;
            if (v.name) maps[v.name] = mapItem;
          });
          prodData.apiMapping = mapItem;
          prodData.stock = liveSourceStock;
          if (Array.isArray(prodData.variants)) {
            prodData.variants.forEach(v => { if (v) v.stock = liveSourceStock; });
          }
        } else {
          delete maps[actualTargetId];
          variants.forEach((v, vIdx) => {
            delete maps[actualTargetId + '__VAR__' + vIdx];
            if (v.name) delete maps[v.name];
          });
        }
        if (typeof saveApiProductMappings === "function") {
          saveApiProductMappings(maps);
        } else {
          localStorage.setItem("mmo_api_product_mappings", JSON.stringify(maps));
        }
      } catch(e) {}

      // Nếu sản phẩm này từng nằm trong danh sách đã xóa, gỡ bỏ khỏi blacklist
      try {
        let deletedIds = JSON.parse(localStorage.getItem("mmo_deleted_product_ids") || "[]");
        if (Array.isArray(deletedIds)) {
          deletedIds = deletedIds.filter(d => d !== prodId && d !== actualTargetId);
          localStorage.setItem("mmo_deleted_product_ids", JSON.stringify(deletedIds));
        }
      } catch(e) {}

      const existingIdx = isEditing ? MOCK_DATA.products.findIndex(p => p && p.id === actualTargetId) : -1;
      if (existingIdx !== -1) {
        MOCK_DATA.products[existingIdx] = Object.assign({}, MOCK_DATA.products[existingIdx], prodData);
        showToast("Cập nhật sản phẩm thành công!", "success");
      } else {
        MOCK_DATA.products.unshift(prodData);
        showToast("Thêm sản phẩm mới thành công!", "success");
      }

      if (typeof recordProductVariants === "function") recordProductVariants(actualTargetId, variants, name);
      
      // Dọn dẹp kho của các biến thể đã bị admin xóa
      if (oldProd && Array.isArray(oldProd.variants) && oldProd.variants.length > variants.length) {
        const stockMap = (typeof getProductStocksMap === "function") ? getProductStocksMap() : {};
        for (let delIdx = variants.length; delIdx < oldProd.variants.length; delIdx++) {
          const delKey = getVariantStockKey(actualTargetId, delIdx);
          delete stockMap[delKey];
          if (typeof callGasApi === "function") {
            callGasApi("adminImportStock", {
              prodId: actualTargetId,
              variantIdx: delIdx,
              targetKey: delKey,
              accounts: "",
              overwrite: true
            }).catch(function() {});
          }
        }
        if (typeof saveProductStocksMap === "function") saveProductStocksMap(stockMap);
      }

      try {
        if (typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured() && typeof TURSO_CLIENT.saveProduct === "function") {
          TURSO_CLIENT.saveProduct(prodData).catch(e => console.warn("Turso save product error:", e));
        }
      } catch(e) {}
      // [LƯU ẢNH AN TOÀN TUYỆT ĐỐI CHỐNG LỖI QUOTA]: Lưu riêng lẻ vào mmo_custom_img_
      if (image && image.trim() !== "") {
        try {
          localStorage.setItem("mmo_custom_img_" + actualTargetId, image.trim());
        } catch(eImg) {}
      }

      saveProductsToStorage();
      closeModal("adminProductModal");

      // Đồng bộ tên mới vào bảng API mappings nếu sản phẩm này có liên kết API
      try {
        const maps = (typeof getApiProductMappings === "function") ? getApiProductMappings() : {};
        if (maps[actualTargetId]) {
          maps[actualTargetId].targetProdName = name;
          if (typeof saveApiProductMappings === "function") saveApiProductMappings(maps);
        }
      } catch(e) {}

      // Cập nhật ngay modal / trang chi tiết nếu đang xem sản phẩm này
      if (typeof currentSelectedProduct !== "undefined" && currentSelectedProduct) {
        const isSame = (String(currentSelectedProduct.id) === String(actualTargetId)) || 
                       (currentSelectedProduct.name && currentSelectedProduct.name.trim().toLowerCase() === name.toLowerCase()) ||
                       (typeof isSameOrAliasProduct === "function" && isSameOrAliasProduct(currentSelectedProduct.id, actualTargetId));
        if (isSame) {
          currentSelectedProduct = Object.assign({}, currentSelectedProduct, prodData);
          currentSelectedProduct.variants = variants;
          currentSelectedProduct.price = effectivePrice;
          if (currentSelectedVariantIndex >= variants.length) currentSelectedVariantIndex = 0;
        }
      }

      // TỰ ĐỘNG LÀM MỚI TOÀN BỘ GIAO DIỆN TRANG XEM CHI TIẾT SẢN PHẨM (viewProductDetail)
      const dtlView = document.getElementById("viewProductDetail");
      const isDtlActive = dtlView && (dtlView.style.display !== "none" && !dtlView.classList.contains("hidden"));
      if (isDtlActive || (currentSelectedProduct && (String(currentSelectedProduct.id) === String(actualTargetId) || (typeof isSameOrAliasProduct === "function" && isSameOrAliasProduct(currentSelectedProduct.id, actualTargetId))))) {
        const dtlImg = document.getElementById("dtlImage");
        if (dtlImg && prodData.image) dtlImg.src = prodData.image;
        const dtlTitle = document.getElementById("dtlTitle");
        if (dtlTitle) dtlTitle.innerText = prodData.name;
        if (typeof openProductDetailById === "function") {
          openProductDetailById(actualTargetId);
        }
      }

      // Phát tín hiệu BroadcastChannel tức thì sang tất cả các tab / cửa sổ trình duyệt khác (<10ms)
      try {
        if (typeof BroadcastChannel !== "undefined") {
          const payload = {
            type: "PRODUCT_UPDATED",
            prodId: actualTargetId,
            prodData: prodData,
            variants: variants,
            stock: prodData.stock
          };
          const bc = new BroadcastChannel("mmo_channel");
          bc.postMessage(payload);
          setTimeout(() => bc.close(), 1000);

          const bc2 = new BroadcastChannel("mmo_realtime_sync");
          bc2.postMessage(payload);
          setTimeout(() => bc2.close(), 1000);
        }
      } catch(e) {}

      // Defer tất cả render để nhả main thread (tránh đơ/jank sau khi lưu)
      setTimeout(function() {
        if (typeof renderAdminProductsTable === "function") renderAdminProductsTable();
        if (typeof renderProductGrid === "function") renderProductGrid();
        if (typeof renderBestSellers === "function") renderBestSellers();
        if (typeof renderRecommended === "function") renderRecommended();
        if (typeof renderDynamicFlankingProducts === "function") renderDynamicFlankingProducts();
        if (typeof renderAdminDashboard === "function") renderAdminDashboard();
        if (typeof initStockManagementUI === "function") initStockManagementUI();
        if (typeof renderAllProductsPage === "function") renderAllProductsPage();
        if (typeof renderApiProductMappingsTable === "function") renderApiProductMappingsTable();
        if (typeof renderDetailRelatedProducts === "function" && currentSelectedProduct) {
          renderDetailRelatedProducts(currentSelectedProduct);
        }
      }, 10);

      // Đồng bộ trực tiếp lên Google Apps Script / Google Sheets
      if (typeof callGasApi === "function") {
        showToast("Đang đồng bộ sản phẩm lên hệ thống...", "info");
        callGasApi("adminSaveProduct", {
          ...prodData,
          product: prodData
        }).then(function(res) {
          if (res && res.success) {
            showToast("🎉 Đã lưu và đồng bộ sản phẩm thành công!", "success");
          } else {
            console.warn("adminSaveProduct response:", res);
          }
        }).catch(function(err) {
          console.warn("Lỗi đồng bộ sản phẩm:", err);
        });
      }
    }
    window.handleSaveProduct = handleSaveProduct;

    function handleAdminAddUserSubmit() {
      const email = document.getElementById("admNewUserEmail")?.value.trim().toLowerCase();
      const name = document.getElementById("admNewUserName")?.value.trim();
      const bal = parseInt(document.getElementById("admNewUserBal")?.value) || 0;
      const role = document.getElementById("admNewUserRole")?.value || "MEMBER";

      if (!email || !email.includes("@")) {
        showToast("Vui lòng nhập email hợp lệ!", "warning");
        return;
      }

      let users = getRegisteredUsers();
      if (users.some(u => (u.email || "").toLowerCase() === email)) {
        showToast("Email này đã tồn tại trong hệ thống!", "warning");
        return;
      }

      const newUser = {
        userId: "USR_" + Math.floor(100000 + Math.random() * 900000),
        name: name || email.split("@")[0],
        email: email,
        role: role,
        balance: bal,
        avatar: "https://api.dicebear.com/7.x/bottts/svg?seed=" + encodeURIComponent(email)
      };

      users.unshift(newUser);
      saveRegisteredUsers(users);
      closeModal("adminAddUserModal");
      if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
      showToast("Đã thêm thành viên mới: " + email, "success");
    }
    window.handleAdminAddUserSubmit = handleAdminAddUserSubmit;

    function handleBalTypeChange() {
      const type = document.querySelector("input[name='balActionType']:checked")?.value || "add";
      const noteInp = document.getElementById("balModalNoteInput");
      const amtInp = document.getElementById("balModalAmountInput");
      if (amtInp) {
        amtInp.style.color = type === "sub" ? "#ef4444" : "#10b981";
      }
      if (noteInp && (!noteInp.value || noteInp.value.includes("Nạp tiền thủ công") || noteInp.value.includes("Trừ tiền thủ công"))) {
        noteInp.value = type === "sub" ? "Trừ tiền thủ công bởi Quản trị viên" : "Nạp tiền thủ công qua ngân hàng";
      }
    }
    window.handleBalTypeChange = handleBalTypeChange;

    function submitUserBalanceAdjustment() {
      const emailInp = document.getElementById("balModalUserEmail") || document.getElementById("adjBalUserEmail");
      const email = (emailInp?.value || document.getElementById("balModalUserEmailText")?.innerText || "").trim().toLowerCase();
      
      const amtInp = document.getElementById("balModalAmountInput") || document.getElementById("adjBalAmount");
      const rawAmt = Math.abs(parseInt(amtInp?.value, 10)) || 0;
      
      const actionType = document.querySelector("input[name='balActionType']:checked")?.value || "add";
      const amt = actionType === "sub" ? -rawAmt : rawAmt;
      
      const noteInp = document.getElementById("balModalNoteInput") || document.getElementById("adjBalReason");
      const reason = noteInp?.value?.trim() || (amt >= 0 ? "Nạp tiền thủ công qua ngân hàng" : "Trừ tiền thủ công bởi Quản trị viên");

      if (!email || rawAmt <= 0) {
        showToast("Vui lòng điền đúng thông tin số tiền!", "warning");
        return;
      }

      let users = getRegisteredUsers();
      let idx = users.findIndex(u => (u.email || "").toLowerCase().trim() === email);
      if (idx === -1) {
        const uName = document.getElementById("balModalUserName")?.innerText || email.split("@")[0];
        users.push({
          id: "USR_" + Date.now(),
          email: email,
          name: uName,
          balance: Math.max(0, amt),
          role: "USER"
        });
        idx = users.length - 1;
      } else {
        let baseBal = (users[idx].balance !== undefined) ? Number(users[idx].balance) : 0;
        if (typeof currentUser !== "undefined" && currentUser && (currentUser.email || "").toLowerCase().trim() === email && currentUser.balance !== undefined) {
          baseBal = Number(currentUser.balance);
        }
        users[idx].balance = Math.max(0, baseBal + amt);
      }
      saveRegisteredUsers(users);

      if (typeof currentUser !== "undefined" && currentUser && (currentUser.email || "").toLowerCase().trim() === email) {
        currentUser.balance = users[idx].balance;
        localStorage.setItem("mmo_user", JSON.stringify(currentUser));
        if (typeof updateUserUI === "function") updateUserUI();
      }

      if (typeof recordTransaction === "function") {
        const transType = amt >= 0 ? "Nạp tiền thủ công Admin" : "Trừ tiền thủ công Admin";
        recordTransaction(email, users[idx].name || email, transType, amt, users[idx].balance, reason);
      }

      closeModal("userBalanceModal");
      if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
      if (typeof openAdminUserDetailModal === "function") {
        const dtlModal = document.getElementById("adminUserDetailModal");
        if (dtlModal && dtlModal.style.display === "flex") {
          openAdminUserDetailModal(email);
        }
      }
      showToast("Đã " + (amt >= 0 ? "cộng " : "trừ ") + formatVND(Math.abs(amt)) + " cho " + email + " thành công!", "success");

      // Bắn tín hiệu sang tất cả các tab/cửa sổ đang mở để cập nhật số dư tức thì
      try {
        localStorage.setItem("mmo_balance_sync_trigger", JSON.stringify({ email: email, balance: users[idx].balance, time: Date.now() }));
        if (typeof BroadcastChannel !== "undefined") {
          const bc = new BroadcastChannel("mmo_channel");
          bc.postMessage({ type: "BALANCE_UPDATED", email: email, balance: users[idx].balance });
        }
      } catch(e) {}

      // Đồng bộ ngầm lên Google Apps Script backend: Dual-path sync
      const targetUser = users[idx];
      const adminEmail = (currentUser && currentUser.email) ? currentUser.email : "manhdongvtc@gmail.com";
      const apiUrl = typeof getBackendApiUrl === "function" ? getBackendApiUrl() : "";

      function applyNewBalance(em, nBal) {
        let uList = getRegisteredUsers();
        let uIdx = uList.findIndex(u => (u.email || "").toLowerCase().trim() === em);
        if (uIdx !== -1) {
          uList[uIdx].balance = nBal;
          saveRegisteredUsers(uList);
          if (currentUser && (currentUser.email || "").toLowerCase().trim() === em) {
            currentUser.balance = nBal;
            localStorage.setItem("mmo_user", JSON.stringify(currentUser));
            if (typeof updateUserUI === "function") updateUserUI();
          }
          if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
        }
      }

      if (typeof callGasApi === "function") {
        callGasApi("adminUpdateBalance", {
          adminEmail: adminEmail,
          targetEmail: email,
          amount: amt,
          reason: reason
        }).then(res => {
          if (res && res.success && res.newBalance !== undefined) {
            applyNewBalance(email, Number(res.newBalance));
          } else if (amt > 0 && apiUrl) {
            // Fallback: Gọi endpoint webhook nạp tiền trực tiếp tương thích 100% mọi phiên bản Apps Script
            const cleanPrefix = email.split("@")[0].toUpperCase().replace(/[^A-Z0-9]/g, '');
            const cleanUId = (targetUser.userId || targetUser.id || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
            const topupContent = "HOAN_TIEN " + (cleanUId || cleanPrefix) + " DON_" + orderId;
            
            fetch(apiUrl, {
              method: "POST",
              headers: { "Content-Type": "text/plain;charset=utf-8" },
              body: JSON.stringify({
                transferAmount: amt,
                transferContent: topupContent,
                gateway: "MBBank",
                referenceCode: "ADMIN_TOPUP_" + Date.now()
              })
            }).then(r => r.json()).then(webRes => {
              if (webRes && webRes.success && webRes.newBalance !== undefined) {
                applyNewBalance(email, Number(webRes.newBalance));
              }
            }).catch(() => {});
          }
        }).catch(() => {
          if (amt > 0 && apiUrl) {
            const cleanPrefix = email.split("@")[0].toUpperCase().replace(/[^A-Z0-9]/g, '');
            const cleanUId = (targetUser.userId || targetUser.id || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
            const topupContent = "NAP " + (cleanUId || cleanPrefix) + " " + cleanPrefix;
            fetch(apiUrl, {
              method: "POST",
              headers: { "Content-Type": "text/plain;charset=utf-8" },
              body: JSON.stringify({
                transferAmount: amt,
                transferContent: topupContent,
                gateway: "MBBank",
                referenceCode: "ADMIN_TOPUP_" + Date.now()
              })
            }).then(r => r.json()).then(webRes => {
              if (webRes && webRes.success && webRes.newBalance !== undefined) {
                applyNewBalance(email, Number(webRes.newBalance));
              }
            }).catch(() => {});
          }
        });
      }
    }
    window.submitUserBalanceAdjustment = submitUserBalanceAdjustment;

    // =========================================================================
    // 2FA LIVE AUTHENTICATOR & RFC 6238 TOTP ENGINE (100% GOOGLE AUTH COMPLIANT)
    // =========================================================================
    function sha1_2fa(bytes) {
      const len = bytes.length;
      const bitLen = len * 8;
      const newLen = (((len + 8) >> 6) + 1) << 6;
      const u8 = new Uint8Array(newLen);
      u8.set(bytes);
      u8[len] = 0x80;
      const view = new DataView(u8.buffer);
      view.setUint32(newLen - 8, Math.floor(bitLen / 0x100000000), false);
      view.setUint32(newLen - 4, bitLen & 0xffffffff, false);
      
      let h0 = 0x67452301, h1 = 0xEFCDAB89, h2 = 0x98BADCFE, h3 = 0x10325476, h4 = 0xC3D2E1F0;
      const w = new Uint32Array(80);

      for (let i = 0; i < newLen; i += 64) {
        for (let t = 0; t < 16; t++) {
          w[t] = view.getUint32(i + t * 4, false);
        }
        for (let t = 16; t < 80; t++) {
          const v = w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16];
          w[t] = (v << 1) | (v >>> 31);
        }

        let a = h0, b = h1, c = h2, d = h3, e = h4;
        for (let t = 0; t < 80; t++) {
          let f, k;
          if (t < 20) {
            f = (b & c) | ((~b) & d);
            k = 0x5A827999;
          } else if (t < 40) {
            f = b ^ c ^ d;
            k = 0x6ED9EBA1;
          } else if (t < 60) {
            f = (b & c) | (b & d) | (c & d);
            k = 0x8F1BBCDC;
          } else {
            f = b ^ c ^ d;
            k = 0xCA62C1D6;
          }
          const temp = (((a << 5) | (a >>> 27)) + f + e + k + w[t]) | 0;
          e = d; d = c; c = ((b << 30) | (b >>> 2)) | 0; b = a; a = temp;
        }

        h0 = (h0 + a) | 0;
        h1 = (h1 + b) | 0;
        h2 = (h2 + c) | 0;
        h3 = (h3 + d) | 0;
        h4 = (h4 + e) | 0;
      }

      const res = new Uint8Array(20);
      const resView = new DataView(res.buffer);
      resView.setUint32(0, h0, false);
      resView.setUint32(4, h1, false);
      resView.setUint32(8, h2, false);
      resView.setUint32(12, h3, false);
      resView.setUint32(16, h4, false);
      return res;
    }

    function hmacSha1_2fa(keyBytes, msgBytes) {
      const blockSize = 64;
      let key = keyBytes;
      if (key.length > blockSize) {
        key = sha1_2fa(key);
      }
      const paddedKey = new Uint8Array(blockSize);
      paddedKey.set(key);

      const oKeyPad = new Uint8Array(blockSize);
      const iKeyPad = new Uint8Array(blockSize);
      for (let i = 0; i < blockSize; i++) {
        oKeyPad[i] = paddedKey[i] ^ 0x5c;
        iKeyPad[i] = paddedKey[i] ^ 0x36;
      }

      const innerMsg = new Uint8Array(blockSize + msgBytes.length);
      innerMsg.set(iKeyPad);
      innerMsg.set(msgBytes, blockSize);
      const innerHash = sha1_2fa(innerMsg);

      const outerMsg = new Uint8Array(blockSize + 20);
      outerMsg.set(oKeyPad);
      outerMsg.set(innerHash, blockSize);
      return sha1_2fa(outerMsg);
    }

    function base32ToBytes_2fa(base32) {
      const base32chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
      let clean = (base32 || "").toString().toUpperCase().replace(/[s-]+/g, "").replace(/=+$/, "");
      let bits = "";
      for (let i = 0; i < clean.length; i++) {
        const val = base32chars.indexOf(clean[i]);
        if (val === -1) continue;
        bits += val.toString(2).padStart(5, "0");
      }
      const bytes = new Uint8Array(Math.floor(bits.length / 8));
      for (let i = 0; i < bytes.length; i++) {
        bytes[i] = parseInt(bits.substr(i * 8, 8), 2);
      }
      return bytes;
    }

    function extract2FaSecret(raw) {
      if (!raw) return "";
      let str = String(raw).trim();
      if (str.includes("otpauth://") && str.includes("secret=")) {
        const match = str.match(/secret=([A-Za-z0-9]+)/);
        if (match) return match[1].toUpperCase();
      }
      if (str.includes("|")) {
        const parts = str.split("|").map(p => p.trim());
        for (let i = parts.length - 1; i >= 0; i--) {
          const clean = parts[i].replace(/[s-]+/g, "").toUpperCase();
          if (/^[A-Z2-7]{16,64}$/.test(clean)) {
            return clean;
          }
        }
        return parts[parts.length - 1].replace(/[s-]+/g, "").toUpperCase();
      }
      return str.replace(/[s-]+/g, "").toUpperCase();
    }
    window.extract2FaSecret = extract2FaSecret;

    function generateTOTP(secret, epoch) {
      if (!secret) return "------";
      const cleanSecret = extract2FaSecret(secret);
      const keyBytes = base32ToBytes_2fa(cleanSecret);
      if (!keyBytes || keyBytes.length === 0) return "ERROR";

      const timeStep = Math.floor((epoch !== undefined ? epoch : (Date.now() / 1000)) / 30);
      const timeBytes = new Uint8Array(8);
      const view = new DataView(timeBytes.buffer);
      view.setUint32(0, Math.floor(timeStep / 0x100000000), false);
      view.setUint32(4, timeStep & 0xffffffff, false);

      const hmac = hmacSha1_2fa(keyBytes, timeBytes);
      const offset = hmac[hmac.length - 1] & 0x0f;
      const code = ((hmac[offset] & 0x7f) << 24) |
                   ((hmac[offset + 1] & 0xff) << 16) |
                   ((hmac[offset + 2] & 0xff) << 8) |
                   (hmac[offset + 3] & 0xff);
      return (code % 1000000).toString().padStart(6, "0");
    }
    window.generateTOTP = generateTOTP;

