    function switchStockImportSubTab(mode) {
      const tabManual = document.getElementById("stockSubTabManual");
      const tabApi = document.getElementById("stockSubTabApi");
      const tabTurso = document.getElementById("stockSubTabTurso");
      const btnManual = document.getElementById("subTabBtnStockManual");
      const btnApi = document.getElementById("subTabBtnStockApi");
      const btnTurso = document.getElementById("subTabBtnStockTurso");

      if (mode === "turso") {
        if (tabManual) tabManual.style.display = "none";
        if (tabApi) tabApi.style.display = "none";
        if (tabTurso) tabTurso.style.display = "block";
        if (btnManual) { btnManual.classList.remove("active"); btnManual.style.background = ""; btnManual.style.color = ""; }
        if (btnApi) { btnApi.classList.remove("active"); btnApi.style.background = ""; btnApi.style.color = ""; }
        if (btnTurso) { btnTurso.classList.add("active"); btnTurso.style.background = "#3b82f6"; btnTurso.style.color = "#fff"; }
        if (typeof initTursoUI === "function") initTursoUI();
      } else if (mode === "api") {
        if (tabManual) tabManual.style.display = "none";
        if (tabApi) tabApi.style.display = "block";
        if (tabTurso) tabTurso.style.display = "none";
        if (btnManual) { btnManual.classList.remove("active"); btnManual.style.background = ""; btnManual.style.color = ""; }
        if (btnApi) { btnApi.classList.add("active"); btnApi.style.background = "#10b981"; btnApi.style.color = "#fff"; }
        if (btnTurso) { btnTurso.classList.remove("active"); btnTurso.style.background = ""; btnTurso.style.color = ""; }
        if (typeof initApiSourceStockUI === "function") initApiSourceStockUI();
        else if (typeof fetchBothSourceBalances === "function") fetchBothSourceBalances(false);
      } else {
        if (tabManual) tabManual.style.display = "block";
        if (tabApi) tabApi.style.display = "none";
        if (tabTurso) tabTurso.style.display = "none";
        if (btnManual) { btnManual.classList.add("active"); btnManual.style.background = ""; btnManual.style.color = ""; }
        if (btnApi) { btnApi.classList.remove("active"); btnApi.style.background = ""; btnApi.style.color = ""; }
        if (btnTurso) { btnTurso.classList.remove("active"); btnTurso.style.background = ""; btnTurso.style.color = ""; }
        if (typeof TURSO_CLIENT !== "undefined" && typeof TURSO_CLIENT.isConfigured === "function" && TURSO_CLIENT.isConfigured()) {
          if (typeof syncTursoStockToLocalUI === "function") {
            syncTursoStockToLocalUI().then(() => {
              if (typeof handleStockVariantChange === "function") handleStockVariantChange();
            }).catch(e => console.error(e));
          }
        }
      }
    }
