    function normApiText(str) {
      return String(str || '').toLowerCase()
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .replace(/[đĐ]/g, 'd')
        .replace(/[^a-z0-9]/g, ' ')
        .replace(/\s+/g, ' ').trim();
    }
    window.normApiText = normApiText;

    function isProductApi(productOrId) {
      if (!productOrId) return false;
      const prod = (typeof productOrId === "object") ? productOrId : (typeof findShopProduct === "function" ? findShopProduct(productOrId) : null);
      if (prod && (prod.deliveryType === "api" || prod.delivery_type === "api")) return true;
      if (prod && prod.apiMapping && prod.apiMapping.enabled && prod.apiMapping.sourceProdId) return true;
      const pId = typeof productOrId === "string" ? productOrId : (prod ? prod.id : "");
      if (typeof getApiProductMapping === "function") {
        const map = getApiProductMapping(pId || prod);
        if (map && map.enabled && map.sourceProdId) return true;
      }
      return false;
    }
    window.isProductApi = isProductApi;

    function getApiProductMapping(productOrId) {
      if (!productOrId) return null;
      const prodId = typeof productOrId === "string" ? productOrId.trim() : (productOrId.id || "").trim();
      const prodObj = typeof productOrId === "object" ? productOrId : ((typeof MOCK_DATA !== "undefined" && MOCK_DATA.products) ? MOCK_DATA.products.find(p => p && (String(p.id) === String(prodId) || (p.name && typeof normApiText === "function" && normApiText(p.name) === normApiText(prodId)))) : null);
      const prodName = prodObj ? (prodObj.name || "") : (typeof productOrId === "string" ? productOrId.trim() : "");

      const maps = getApiProductMappings();

      function enrichMapping(m) {
        if (!m || !m.enabled || !m.sourceProdId) return null;
        const res = Object.assign({}, m);
        let stock = (res.sourceStock !== undefined && res.sourceStock !== null) ? Number(res.sourceStock) : 0;
        const prods = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
          ? window.cachedSourceProducts
          : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);
        if (prods && prods.length > 0) {
          const inSrc = prods.find(s => String(s.id) === String(res.sourceProdId) && (!res.provider || s.provider === res.provider))
            || prods.find(s => String(s.id) === String(res.sourceProdId));
          if (inSrc && typeof inSrc.amount === "number" && inSrc.amount > 0) {
            stock = inSrc.amount;
            res.sourceStock = stock;
            if (inSrc.price) res.sourcePrice = inSrc.price;
            if (inSrc.name) res.sourceProdName = inSrc.name;
          }
        }
        res.sourceStock = Math.max(0, stock);
        return res;
      }

      // [BUILT-IN DEFAULT MAPPINGS FOR ON-DEMAND PRODUCTS]
      const defaultMappings = {
        "PROD_MTQQXO2E": { enabled: true, provider: "mail72h", sourceProdId: "712", sourcePrice: 259, sourceProdName: "24h [ ID 712 ]" },
        "PROD_MTQWMPL5": { enabled: true, provider: "mail72h", sourceProdId: "818", sourcePrice: 979, sourceProdName: "7  [ ID 9 ]" },
        "PROD_MTQWQFZD": { enabled: true, provider: "mail72h", sourceProdId: "817", sourcePrice: 3879, sourceProdName: "30 ngày [ ID 817 ]" },
        "PROD_MTQX1C7X": { enabled: true, provider: "shop1989nd", sourceProdId: "19745", sourcePrice: 138.6, sourceProdName: "Gmail Domain Cho Thuê live 12h+" },
        "PROD_MTQX465U": { enabled: true, provider: "shop1989nd", sourceProdId: "19768", sourcePrice: 53.2, sourceProdName: "Gmail Domain Cho Thuê .live 10 phút" },
        "PROD_MU5PWT7PP7": { enabled: true, provider: "nguyenlieummo", sourceProdId: "119284", sourcePrice: 3220, sourceProdName: "TÀI KHOẢN KLING AI 65 CREDIT" },
        "PROD_MTQZT2Y1": { enabled: true, provider: "nguyenlieummo", sourceProdId: "121063", sourcePrice: 656, sourceProdName: "Hotmail Trusted - OAuth2 [ Graph ] Live 12 - 36 Months", sourceStock: 88181 }
      };

      // Tự động chuyển tiếp mã cũ 13840 sang 121063 nếu có trong maps
      if (prodId && maps[prodId] && (maps[prodId].sourceProdId === "13840" || maps[prodId].sourceProdId === "138400")) {
        maps[prodId].sourceProdId = "121063";
        maps[prodId].sourcePrice = 656;
        maps[prodId].sourceStock = 88181;
      }

      // Bảo vệ tuyệt đối: nếu sản phẩm cốt lõi bị lưu sai provider hoặc ID chết trong localStorage, tự động sửa về đúng chuẩn
      if (prodId && defaultMappings[prodId]) {
        if (!maps[prodId] || maps[prodId].provider !== defaultMappings[prodId].provider || !maps[prodId].sourceProdId || maps[prodId].sourceProdId === "13840") {
          return enrichMapping(defaultMappings[prodId]);
        }
      }
      if (prodObj && prodObj.id && defaultMappings[prodObj.id]) {
        if (!maps[prodObj.id] || maps[prodObj.id].provider !== defaultMappings[prodObj.id].provider || !maps[prodObj.id].sourceProdId || maps[prodObj.id].sourceProdId === "13840") {
          return enrichMapping(defaultMappings[prodObj.id]);
        }
      }

      // 1. Kiểm tra cấu hình explicitly bị tắt
      if (prodId && maps[prodId] && maps[prodId].enabled === false) {
        return null;
      }

      // 2. Tra cứu trực tiếp theo ID sản phẩm trong bảng maps (ưu tiên cao nhất)
      if (prodId && maps[prodId] && maps[prodId].enabled && maps[prodId].sourceProdId) {
        return enrichMapping(maps[prodId]);
      }
      if (prodObj && prodObj.id && maps[prodObj.id] && maps[prodObj.id].enabled && maps[prodObj.id].sourceProdId) {
        return enrichMapping(maps[prodObj.id]);
      }

      // 3. Tra cứu theo apiMapping gắn trực tiếp trên đối tượng sản phẩm
      if (prodObj && prodObj.apiMapping && prodObj.apiMapping.enabled && prodObj.apiMapping.sourceProdId) {
        return enrichMapping(prodObj.apiMapping);
      }

      // 4. Tra cứu theo tên biến thể hoặc tên sản phẩm (loại bỏ tên generic để tránh xung đột chéo giữa các sản phẩm)
      if (prodName) {
        const lowerPN = prodName.toLowerCase().trim();
        const isGenericName = ["default", "gói 1", "gói 2", "gói 3", "gói 4", "hotmail live", "mail 24h", "mặc định"].includes(lowerPN);
        if (!isGenericName) {
          if (maps[prodName] && maps[prodName].enabled && maps[prodName].sourceProdId) {
            return enrichMapping(maps[prodName]);
          }
          const normN = normApiText(prodName);
          for (const k of Object.keys(maps)) {
            const m = maps[k];
            if (m && m.enabled && m.sourceProdId) {
              if (normApiText(k) === normN) return enrichMapping(m);
              if (m.targetProdName && normApiText(m.targetProdName) === normN) return enrichMapping(m);
            }
          }
        }
      }

      // 5. Nếu đối tượng có deliveryType === 'api', tra cứu alias hoặc key con
      if (prodObj && (prodObj.deliveryType === 'api' || prodObj.delivery_type === 'api')) {
        for (const k of Object.keys(maps)) {
          const m = maps[k];
          if (m && m.enabled && m.sourceProdId) {
            if (k.startsWith(prodObj.id)) return enrichMapping(m);
          }
        }
      }

      // 6. Tra cứu trong defaultMappings built-in nếu chưa được cấu hình thủ công
      if (prodId && defaultMappings[prodId]) {
        return enrichMapping(defaultMappings[prodId]);
      }
      if (prodObj && prodObj.id && defaultMappings[prodObj.id]) {
        return enrichMapping(defaultMappings[prodObj.id]);
      }

      return null;
    }
    window.getApiProductMapping = getApiProductMapping;

    function renderApiProductMappingsTable() {
      const tbody = document.getElementById("apiProductMappingsTableBody");
      if (!tbody) return;

      let prods = [];
      if (typeof getVisibleProducts === "function") {
        prods = getVisibleProducts();
      }
      if ((!prods || prods.length === 0) && MOCK_DATA && Array.isArray(MOCK_DATA.products)) {
        prods = MOCK_DATA.products;
      }
      if (!Array.isArray(prods)) prods = [];

      const mappings = (typeof getApiProductMappings === "function") ? getApiProductMappings() : {};
      const sourceProds = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
        ? window.cachedSourceProducts
        : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);

      if (prods.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align:center; padding:20px; color:#64748b;">Chưa có sản phẩm nào trên website.</td></tr>';
        const pag = document.getElementById("apiProductMappingsPagination");
        if (pag) pag.innerHTML = "";
        return;
      }

      // Lọc theo từ khóa tìm kiếm nếu có
      let filteredProds = prods;
      const searchInput = document.getElementById("apiMappingsSearchInput");
      if (searchInput && searchInput.value.trim()) {
        const q = (typeof normApiText === "function") ? normApiText(searchInput.value) : searchInput.value.toLowerCase().trim();
        filteredProds = prods.filter(function(p) {
          const n = (p && p.name) ? p.name.toLowerCase() : "";
          const id = (p && p.id) ? p.id.toLowerCase() : "";
          const cat = (p && p.category) ? p.category.toLowerCase() : "";
          return n.includes(q) || id.includes(q) || cat.includes(q);
        });
      }

      if (filteredProds.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align:center; padding:20px; color:#64748b;">Không tìm thấy sản phẩm nào phù hợp với từ khóa.</td></tr>';
        const pag = document.getElementById("apiProductMappingsPagination");
        if (pag) pag.innerHTML = "";
        return;
      }

      // Phân trang 10 sản phẩm 1 trang
      const PAGE_SIZE = 10;
      let curPage = (typeof paginationState !== "undefined" && paginationState.admApiMappings) ? paginationState.admApiMappings : 1;
      const totalPages = Math.ceil(filteredProds.length / PAGE_SIZE) || 1;
      if (curPage > totalPages) curPage = totalPages;
      if (curPage < 1) curPage = 1;
      if (typeof paginationState !== "undefined") paginationState.admApiMappings = curPage;

      const startIndex = (curPage - 1) * PAGE_SIZE;
      const pageProds = filteredProds.slice(startIndex, startIndex + PAGE_SIZE);

      tbody.innerHTML = pageProds.map(function(p) {
        const map = mappings[p.id] || { enabled: false, provider: "shop1989nd", sourceProdId: "" };
        const isEnabled = !!map.enabled;
        const curProvider = map.provider || "shop1989nd";

        // Dropdown Nguồn Hàng (Cột 2) - ĐỦ 5 NGUỒN
        let providerSelectHtml = '<select id="mapProvider_' + p.id + '" onchange="handleProviderChange(\'' + p.id + '\')" style="width:100%; background:#0d121f; border:1px solid #1e293b; padding:6px 8px; border-radius:6px; color:#fff; font-size:0.78rem;">';
        providerSelectHtml += '<option value="shop1989nd"' + (curProvider === 'shop1989nd' ? ' selected="selected"' : '') + '>shop1989nd.com</option>';
        providerSelectHtml += '<option value="selltainguyenmmo"' + (curProvider === 'selltainguyenmmo' ? ' selected="selected"' : '') + '>selltainguyenmmo.com</option>';
        providerSelectHtml += '<option value="mail72h"' + (curProvider === 'mail72h' ? ' selected="selected"' : '') + '>mail72h.com</option>';
        providerSelectHtml += '<option value="sellmmo"' + (curProvider === 'sellmmo' ? ' selected="selected"' : '') + '>sellmmo.vn</option>';
        providerSelectHtml += '<option value="nguyenlieummo"' + (curProvider === 'nguyenlieummo' ? ' selected="selected"' : '') + '>nguyenlieummo.com.vn</option>';
        providerSelectHtml += '</select>';

        // Dropdown Sản Phẩm Nguồn (Cột 3)
        let sourceStockDisplay = "--";
        let sourcePriceDisplay = "";
        if (map.sourceProdId) {
          const src = sourceProds.find(s => String(s.id) === String(map.sourceProdId));
          if (src) {
            sourceStockDisplay = '<span style="color:#10b981; font-weight:800;">' + (Number(src.amount) || 0).toLocaleString() + ' acc</span>';
            sourcePriceDisplay = '<span style="font-size:0.75rem; color:#f59e0b;">(Giá nhập: ' + (typeof formatVND === "function" ? formatVND(src.price) : src.price) + ')</span>';
          }
        }

        let selectHtml = '<select id="mapSelect_' + p.id + '" onchange="handleMappingChange(\'' + p.id + '\')" style="width:100%; background:#0d121f; border:1px solid #1e293b; padding:6px 10px; border-radius:6px; color:#fff; font-size:0.78rem;">';
        selectHtml += '<option value="">-- Không liên kết (Bán từ kho thủ công) --</option>';
        
        const filtered = sourceProds.filter(s => !s.provider || s.provider === curProvider);
        filtered.forEach(function(src) {
          const isSelected = String(src.id) === String(map.sourceProdId) ? ' selected="selected"' : '';
          const pName = (typeof escapeHtml === "function") ? escapeHtml(src.name) : src.name;
          const pCat = (typeof escapeHtml === "function") ? escapeHtml(src.category || curProvider) : (src.category || curProvider);
          const pPrice = (typeof formatVND === "function") ? formatVND(src.price) : src.price;
          const pStock = (Number(src.amount) || 0).toLocaleString();
          selectHtml += '<option value="' + src.id + '" data-price="' + src.price + '" data-stock="' + src.amount + '" data-provider="' + (src.provider || curProvider) + '"' + isSelected + '>' +
            '[' + pCat + '] ' + pName + ' - ' + pPrice + ' (Tồn: ' + pStock + ')' +
          '</option>';
        });
        selectHtml += '</select>';

        return '<tr style="border-bottom:1px solid #162035;">' +
          '<td style="padding:10px 12px;">' +
            '<div style="display:flex; align-items:center; gap:8px;">' +
              '<img src="' + (p.image || '') + '" style="width:32px; height:32px; border-radius:4px; object-fit:cover;" onerror="this.style.display=\'none\'" />' +
              '<div>' +
                '<a href="?prod=' + encodeURIComponent(p.id) + '&view=viewProductDetail" target="_blank" style="color:#fff; font-weight:700; text-decoration:none; font-size:0.82rem;">' + (typeof escapeHtml === "function" ? escapeHtml(p.name) : p.name) + '</a>' +
                '<div style="font-size:0.72rem; color:#64748b;">Mã SP: ' + p.id + ' | Giá bán: ' + (typeof formatVND === "function" ? formatVND(p.price) : p.price) + '</div>' +
              '</div>' +
            '</div>' +
          '</td>' +
          '<td style="padding:10px 12px; width:160px;">' + providerSelectHtml + '</td>' +
          '<td style="padding:10px 12px; min-width:280px;">' + selectHtml + '</td>' +
          '<td style="padding:10px 12px; text-align:center; width:110px;">' +
            '<label class="switch" style="margin:0 auto;">' +
              '<input type="checkbox" id="mapToggle_' + p.id + '" onchange="handleMappingToggle(\'' + p.id + '\')"' + (isEnabled ? ' checked="checked"' : '') + '>' +
              '<span class="slider round"></span>' +
            '</label>' +
            '<div id="mapStatusText_' + p.id + '" style="font-size:0.7rem; margin-top:4px; font-weight:700; color:' + (isEnabled ? '#10b981' : '#64748b') + ';">' +
              (isEnabled ? 'BẬT (API)' : 'TẮT') +
            '</div>' +
          '</td>' +
          '<td style="padding:10px 12px; text-align:center; width:110px;" id="mapStockDisplay_' + p.id + '">' +
            sourceStockDisplay +
            (sourcePriceDisplay ? '<br/>' + sourcePriceDisplay : '') +
          '</td>' +
          '<td style="padding:10px 12px; text-align:center; width:90px;">' +
            '<button type="button" class="btn-auth" onclick="saveSingleApiMapping(\'' + p.id + '\')" style="font-size:0.72rem; padding:5px 10px; background:#3b82f6; border:none; border-radius:4px; color:#fff;" title="Lưu liên kết sản phẩm này"><i class="fa-solid fa-floppy-disk"></i> Lưu</button>' +
          '</td>' +
        '</tr>';
      }).join("");

      // Render Pagination
      const pag = document.getElementById("apiProductMappingsPagination");
      if (pag) {
        let pagHtml = '<span style="font-size:0.75rem; color:#94a3b8; margin-right:12px;">Trang ' + curPage + ' / ' + totalPages + ' (' + filteredProds.length + ' sản phẩm)</span>';
        if (totalPages > 1) {
          pagHtml += '<div style="display:inline-flex; gap:4px;">';
          if (curPage > 1) {
            pagHtml += '<button type="button" class="btn-tool-secondary" onclick="changeApiMappingsPage(' + (curPage - 1) + ')" style="padding:4px 8px; font-size:0.75rem;"><i class="fa-solid fa-chevron-left"></i></button>';
          }
          for (let i = 1; i <= totalPages; i++) {
            if (i === curPage) {
              pagHtml += '<span style="background:#3b82f6; color:#fff; padding:4px 8px; border-radius:4px; font-size:0.75rem; font-weight:700;">' + i + '</span>';
            } else if (i === 1 || i === totalPages || (i >= curPage - 1 && i <= curPage + 1)) {
              pagHtml += '<button type="button" class="btn-tool-secondary" onclick="changeApiMappingsPage(' + i + ')" style="padding:4px 8px; font-size:0.75rem;">' + i + '</button>';
            } else if (i === curPage - 2 || i === curPage + 2) {
              pagHtml += '<span style="color:#64748b; padding:4px 2px; font-size:0.75rem;">...</span>';
            }
          }
          if (curPage < totalPages) {
            pagHtml += '<button type="button" class="btn-tool-secondary" onclick="changeApiMappingsPage(' + (curPage + 1) + ')" style="padding:4px 8px; font-size:0.75rem;"><i class="fa-solid fa-chevron-right"></i></button>';
          }
          pagHtml += '</div>';
        }
        pag.innerHTML = pagHtml;
      }
    }
    window.renderApiProductMappingsTable = renderApiProductMappingsTable;

    // ĐỒNG BỘ VÀ LƯU LIÊN KẾT SẢN PHẨM API ON-DEMAND
    function handleProviderChange(prodId) {
      const pSel = document.getElementById("mapProvider_" + prodId);
      const sel = document.getElementById("mapSelect_" + prodId);
      if (!pSel || !sel) return;
      const provider = pSel.value;
      const prods = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
        ? window.cachedSourceProducts
        : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);
      
      const filtered = prods.filter(s => !s.provider || s.provider === provider);

      let selectHtml = '<option value="">-- Không liên kết (Bán từ kho thủ công) --</option>';
      filtered.forEach(function(src) {
        selectHtml += '<option value="' + src.id + '" data-price="' + src.price + '" data-stock="' + src.amount + '" data-provider="' + provider + '">' +
          '[' + (src.category || provider) + '] ' + src.name + ' - ' + (typeof formatVND === "function" ? formatVND(src.price) : src.price) + ' (Tồn: ' + (Number(src.amount) || 0).toLocaleString() + ')' +
        '</option>';
      });
      sel.innerHTML = selectHtml;
      handleMappingChange(prodId);
    }
    window.handleProviderChange = handleProviderChange;

    function handleMappingChange(prodId) {
      const select = document.getElementById("mapSelect_" + prodId);
      const chk = document.getElementById("mapToggle_" + prodId) || document.getElementById("mapEnable_" + prodId);
      const stockCell = document.getElementById("mapStockDisplay_" + prodId) || document.getElementById("mapStockCell_" + prodId);
      const statusText = document.getElementById("mapStatusText_" + prodId) || document.getElementById("mapEnableLabel_" + prodId);

      if (!select) return;
      const srcId = select.value;
      if (srcId && chk) {
        chk.checked = true;
        if (statusText) { statusText.style.color = "#10b981"; statusText.innerText = "BẬT (API)"; }
      } else if (!srcId && chk) {
        chk.checked = false;
        if (statusText) { statusText.style.color = "#64748b"; statusText.innerText = "TẮT"; }
      }

      if (stockCell) {
        if (srcId) {
          const prods = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts)) ? window.cachedSourceProducts : [];
          const src = prods.find(s => String(s.id) === String(srcId));
          if (src) {
            stockCell.innerHTML = '<span style="color:#10b981; font-weight:800;">' + (Number(src.amount) || 0).toLocaleString() + ' acc</span>' +
              '<br/><span style="font-size:0.75rem; color:#f59e0b;">(Giá nhập: ' + (typeof formatVND === "function" ? formatVND(src.price) : src.price) + ')</span>';
          }
        } else {
          stockCell.innerHTML = '--';
        }
      }
    }
    window.handleMappingChange = handleMappingChange;

    function handleMappingToggle(prodId) {
      const chk = document.getElementById("mapToggle_" + prodId) || document.getElementById("mapEnable_" + prodId);
      const lbl = document.getElementById("mapStatusText_" + prodId) || document.getElementById("mapEnableLabel_" + prodId);
      if (chk && lbl) {
        lbl.style.color = chk.checked ? "#10b981" : "#64748b";
        lbl.innerText = chk.checked ? "BẬT (API)" : "TẮT";
      }
      saveSingleApiMapping(prodId);
    }
    window.handleMappingToggle = handleMappingToggle;

    function saveSingleApiMapping(prodId) {
      const select = document.getElementById("mapSelect_" + prodId);
      const chk = document.getElementById("mapToggle_" + prodId) || document.getElementById("mapEnable_" + prodId);
      const pSel = document.getElementById("mapProvider_" + prodId);
      if (!select) return;

      const srcId = select.value;
      const isEnabled = chk ? !!chk.checked : false;
      const provider = (pSel ? pSel.value : null) || "shop1989nd";
      const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[provider]) ? API_SOURCES[provider] : { baseUrl: "https://sellmmo.vn", apiKey: "" };

      const mappings = (typeof getApiProductMappings === "function") ? getApiProductMappings() : {};
      const prods = (typeof getVisibleProducts === "function" ? getVisibleProducts() : null) || (MOCK_DATA && MOCK_DATA.products) || [];
      const prod = prods.find(p => String(p.id) === String(prodId));

      if (!srcId || !isEnabled) {
        delete mappings[prodId];
        if (prod) {
          prod.deliveryType = "local";
          if (typeof MMO_WAREHOUSE !== "undefined") {
            prod.stock = MMO_WAREHOUSE.getAvailable(prodId).length;
          }
        }
        if (typeof saveApiProductMappings === "function") saveApiProductMappings(mappings);
        if (typeof showToast === "function") showToast("Đã tắt liên kết API cho sản phẩm " + (prod ? prod.name : prodId), "info");
      } else {
        const sourceProds = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts)) ? window.cachedSourceProducts : [];
        const srcItem = sourceProds.find(s => String(s.id) === String(srcId));
        const liveSrcStock = (srcItem && typeof srcItem.amount === "number") ? srcItem.amount : ((srcItem && srcItem.amount !== undefined) ? (parseInt(srcItem.amount) || 0) : 0);
        const liveSrcPrice = (srcItem && typeof srcItem.price === "number") ? srcItem.price : 100;

        mappings[prodId] = {
          enabled: true,
          provider: provider,
          baseUrl: pCfg.baseUrl,
          apiKey: pCfg.apiKey,
          sourceProdId: srcId,
          sourceProdName: srcItem ? srcItem.name : ("Sản phẩm " + srcId),
          sourcePrice: liveSrcPrice,
          sourceStock: liveSrcStock
        };

        if (prod) {
          prod.deliveryType = "api";
          prod.stock = liveSrcStock;
          prod.apiMapping = mappings[prodId];
          if (Array.isArray(prod.variants)) {
            prod.variants.forEach(function(v, idx) {
              if (v) {
                v.stock = liveSrcStock;
                mappings[prodId + "_" + idx] = Object.assign({}, mappings[prodId], { targetProdName: v.name || "" });
              }
            });
          }
        }

        if (typeof saveApiProductMappings === "function") saveApiProductMappings(mappings);
        if (typeof showToast === "function") showToast("Đã bật liên kết API: [" + provider + "] " + (srcItem ? srcItem.name : srcId), "success");
      }

      // Lưu đồng bộ vào Turso / Local nếu có
      if (prod && typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured()) {
        TURSO_CLIENT.saveProduct(prod).catch(function(e) { console.warn("Lưu Turso error:", e); });
      }

      // Cập nhật lại giao diện bảng sản phẩm chính để đổi ngay huy hiệu [API: provider]
      if (typeof renderAdminProductsTable === "function") {
        renderAdminProductsTable();
      }
      if (typeof renderProductGrid === "function") {
        renderProductGrid();
      }
    }
    window.saveSingleApiMapping = saveSingleApiMapping;
    window.saveSingleMapping = saveSingleApiMapping;
    

    function saveAllApiMappings() {
      const prods = (MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products : [];
      const mappings = getApiProductMappings();
      let updatedCount = 0;

      prods.forEach(function(p) {
        const select = document.getElementById("mapSelect_" + p.id);
        if (!select) return; // Chỉ cập nhật các dòng đang xuất hiện trên trang hiện tại

        const chk = document.getElementById("mapToggle_" + p.id) || document.getElementById("mapEnable_" + p.id);
        const pSel = document.getElementById("mapProvider_" + p.id);

        const srcId = select.value;
        const isEnabled = chk ? !!chk.checked : false;
        const provider = (pSel ? pSel.value : null) || (select.selectedOptions && select.selectedOptions[0] ? select.selectedOptions[0].getAttribute("data-provider") : "sellmmo") || "sellmmo";
        const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[provider]) ? API_SOURCES[provider] : (API_SOURCES ? API_SOURCES.sellmmo : { baseUrl: "https://sellmmo.vn", apiKey: "" });

        if (!srcId || !isEnabled) {
          delete mappings[p.id];
          if (Array.isArray(p.variants)) {
            p.variants.forEach(function(v) { if (v && v.name) delete mappings[v.name]; });
          }
          const manualStock = (typeof getProductStocksMap === "function") ? (getProductStocksMap()[p.id]?.length || 0) : 0;
          p.stock = manualStock;
          p.deliveryType = "manual";
          delete p.apiMapping;
        } else {
          const prodsSrc = (typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : [];
          const src = prodsSrc.find(s => String(s.id) === String(srcId));
          const srcStock = src ? src.amount : ((p.apiMapping && p.apiMapping.sourceStock) || 0);
          const srcPrice = src ? src.price : ((p.apiMapping && p.apiMapping.sourcePrice) || 100);
          const srcName = src ? src.name : ((p.apiMapping && p.apiMapping.sourceProdName) || ("Sản phẩm " + srcId));

          mappings[p.id] = {
            enabled: true,
            provider: provider,
            baseUrl: pCfg.baseUrl,
            apiKey: pCfg.apiKey,
            sourceProdId: srcId,
            sourceProdName: srcName,
            sourcePrice: srcPrice,
            sourceStock: srcStock,
            targetProdId: p.id,
            targetProdName: p.name || ""
          };
          p.stock = srcStock;
          p.deliveryType = "api";
          p.apiMapping = mappings[p.id];

          if (Array.isArray(p.variants)) {
            p.variants.forEach(function(v) {
              if (v) {
                v.stock = srcStock;
                if (v.name) {
                  mappings[v.name] = Object.assign({}, mappings[p.id], { targetProdName: v.name });
                }
              }
            });
          }
        }
        updatedCount++;
      });

      saveApiProductMappings(mappings);
      if (typeof saveProductsToStorage === "function") saveProductsToStorage();

      renderApiProductMappingsTable();
      if (typeof renderProductGrid === "function") renderProductGrid();
      if (typeof renderAllProductsPage === "function") renderAllProductsPage();
      if (typeof renderBestSellers === "function") renderBestSellers();
      if (typeof renderRecommended === "function") renderRecommended();
      if (typeof renderAdminDashboard === "function") renderAdminDashboard();

      const curP = typeof currentSelectedProduct !== "undefined" ? currentSelectedProduct : null;
      if (curP && typeof syncDetailStockUI === "function") {
        const curVIdx = (typeof currentSelectedVariantIndex === "number") ? currentSelectedVariantIndex : 0;
        syncDetailStockUI(getShopVariantStock(curP, curVIdx));
      }

      if (typeof showToast === "function") {
        showToast("💾 Đã lưu và đồng bộ " + updatedCount + " sản phẩm trên trang hiện tại!", "success");
      }
    }
    window.saveAllApiMappings = saveAllApiMappings;

    async function syncAllProductsStockFromSource(isManual = false) {
      const syncBtn = document.querySelector('button[onclick*="syncAllProductsStockFromSource"]');
      let prevBtnHtml = "";
      if (syncBtn) {
        prevBtnHtml = syncBtn.innerHTML;
        syncBtn.disabled = true;
        syncBtn.innerHTML = "<i class='fa-solid fa-spinner fa-spin'></i> Đang quét 5 nguồn...";
      }

      try {
        // Luôn fetch dữ liệu mới nhất từ 5 nguồn API khi người dùng bấm đồng bộ
        if (isManual || !Array.isArray(cachedSourceProducts) || cachedSourceProducts.length === 0) {
          if (typeof fetchApiSourceProducts === "function") {
            await fetchApiSourceProducts(true);
          }
          if (typeof fetchBothSourceBalances === "function") {
            await fetchBothSourceBalances(true);
          }
        }

        const mappings = (typeof getApiProductMappings === "function") ? getApiProductMappings() : {};
        const prods = (MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products : [];
        const sourceList = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
          ? window.cachedSourceProducts
          : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);

        let syncCount = 0;

        prods.forEach(function(p) {
          const map = mappings[p.id];
          if (map && map.enabled && map.sourceProdId) {
            let provider = map.provider || "sellmmo";
            const sourceBal = (typeof getSourceBalance === "function") ? getSourceBalance(provider) : 999999;
            const minPriceNeeded = Number(map.sourcePrice) || 50;

            const src = sourceList.find(s => String(s.id) === String(map.sourceProdId) && (!map.provider || s.provider === map.provider))
              || sourceList.find(s => String(s.id) === String(map.sourceProdId));

            if (src) {
              map.sourceStock = Number(src.amount) || 0;
              map.sourcePrice = Number(src.price) || map.sourcePrice;
              map.sourceProdName = src.name || map.sourceProdName;
            }

            const targetStock = (typeof map.sourceStock === "number") ? map.sourceStock : 0;

            // Nếu ví nguồn không đủ tiền HOẶC nguồn hết hàng (targetStock <= 0)
            if (sourceBal < minPriceNeeded || targetStock <= 0) {
              p.stock = 0;
              if (Array.isArray(p.variants)) {
                p.variants.forEach(v => { if (v) v.stock = 0; });
              }
            } else {
              p.stock = targetStock;
              if (Array.isArray(p.variants)) {
                p.variants.forEach(v => { if (v) v.stock = targetStock; });
              }
            }
            p.apiMapping = map;
            p.deliveryType = "api";
            p.delivery_type = "api";
            syncCount++;
          }
        });

        if (typeof saveApiProductMappings === "function") saveApiProductMappings(mappings);
        if (typeof saveProductsToStorage === "function") saveProductsToStorage();

        if (typeof renderProductGrid === "function") renderProductGrid();
        if (typeof renderAllProductsPage === "function") renderAllProductsPage();
        if (typeof renderAdminDashboard === "function") renderAdminDashboard();
        if (typeof renderApiProductMappingsTable === "function") renderApiProductMappingsTable();

        const curP = typeof currentSelectedProduct !== "undefined" ? currentSelectedProduct : null;
        if (curP && typeof syncDetailStockUI === "function") {
          const curVIdx = (typeof currentSelectedVariantIndex === "number") ? currentSelectedVariantIndex : 0;
          const liveStock = (typeof getShopVariantStock === "function") ? getShopVariantStock(curP, curVIdx) : (curP.stock || 0);
          syncDetailStockUI(liveStock);
        }

        if (isManual && typeof showToast === "function") {
          showToast("🔄 Đã đồng bộ thành công tồn kho On-Demand cho " + syncCount + " sản phẩm từ 5 nguồn API!", "success");
        }
      } catch(err) {
        console.error("Lỗi đồng bộ nguồn API:", err);
        if (isManual && typeof showToast === "function") {
          showToast("Có lỗi khi đồng bộ từ nguồn: " + (err.message || err), "danger");
        }
      } finally {
        if (syncBtn) {
          syncBtn.disabled = false;
          syncBtn.innerHTML = prevBtnHtml || "<i class='fa-solid fa-cloud-arrow-down'></i> 🔄 ĐỒNG BỘ TỒN KHO TẤT CẢ NGUỒN";
        }
      }
    }
    window.syncAllProductsStockFromSource = syncAllProductsStockFromSource;

    function populateQuickTestSelect() {
      const sel = document.getElementById("quickTestProdSelect");
      if (!sel) return;

      const prods = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
        ? window.cachedSourceProducts
        : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);

      // Lọc các sản phẩm còn hàng thật (> 0 acc) và không chứa "tồn kho ảo"
      const inStockProds = prods.filter(function(s) {
        const stk = Number(s.amount !== undefined ? s.amount : s.stock) || 0;
        const nameLower = String(s.name || "").toLowerCase();
        const idStr = String(s.id || "");
        if (idStr === "19745" || idStr === "19767") return false; // shop1989nd kho ảo
        if (nameLower.includes("tồn kho ảo") || nameLower.includes("kho ảo")) return false;
        return stk > 0;
      });

      // Danh sách sản phẩm mẫu đã xác thực 100% test mua thành công cho từng nguồn
      const PINNED_VERIFIED = [
        { id: "23960", provider: "selltainguyenmmo", name: "ChatGPT New Gmail Trial (Trial 2FA)", price: 2900, stock: 16037, tag: "⭐ [selltainguyenmmo] CHATGPT NEW TRIAL (16.037 ACC)" },
        { id: "26521", provider: "selltainguyenmmo", name: "PROXY IPV4 - PUBLIC - USA 0151", price: 6600, stock: 42, tag: "⭐ [selltainguyenmmo] ĐÃ XÁC THỰC MUA THÀNH CÔNG" },
        { id: "712", provider: "mail72h", name: "Mail 24h [ID 712]", price: 259, stock: 72357, tag: "⭐ [mail72h] ĐÃ XÁC THỰC MUA THÀNH CÔNG" },
        { id: "121063", provider: "nguyenlieummo", name: "Hotmail Trusted - OAuth2 [Graph] Live 12-36 Tháng", price: 656, stock: 88181, tag: "⭐ [nguyenlieummo] HOTMAIL LIVE TRÂU (88K ACC)" },
        { id: "117725", provider: "nguyenlieummo", name: "ID 4 - NVR name ngoai", price: 74, stock: 1810, tag: "⭐ [nguyenlieummo] ĐÃ XÁC THỰC MUA THÀNH CÔNG" },
        { id: "19084", provider: "shop1989nd", name: "Outlook Trusted Oauth2 [Graph]", price: 201.5, stock: 67224, tag: "⭐ [shop1989nd] ĐÃ XÁC THỰC MUA THÀNH CÔNG" },
        { id: "33171", provider: "sellmmo", name: "Gmail Domain ✔️ live 2 phút", price: 55, stock: 1550, tag: "⭐ [sellmmo] ĐÃ XÁC THỰC MUA THÀNH CÔNG" }
      ];

      let html = '<optgroup label="✅ SẢN PHẨM KHUYÊN DÙNG TEST (ĐÃ XÁC THỰC 100% CÒN HÀNG THẬT & MUA THÀNH CÔNG)">';
      PINNED_VERIFIED.forEach(function(item) {
        html += '<option value="' + item.id + '" data-price="' + item.price + '" data-provider="' + item.provider + '" data-stock="' + item.stock + '">' +
          item.tag + ' — ' + escapeHtml(item.name) + ' (Còn ' + item.stock.toLocaleString() + ' acc) - ' + (typeof formatVND === "function" ? formatVND(item.price) : item.price + 'đ') +
        '</option>';
      });
      html += '</optgroup>';

      // Thêm các sản phẩm còn hàng khác từ 5 nguồn
      const PROVIDERS = ["sellmmo", "mail72h", "shop1989nd", "selltainguyenmmo", "nguyenlieummo"];
      PROVIDERS.forEach(function(prov) {
        const provProds = inStockProds.filter(p => (p.provider || "sellmmo") === prov && !PINNED_VERIFIED.some(pin => pin.id === String(p.id) && pin.provider === prov));
        if (provProds.length > 0) {
          html += '<optgroup label="📦 NGUỒN ' + prov.toUpperCase() + ' (CÒN HÀNG THẬT)">';
          provProds.slice(0, 30).forEach(function(s) {
            const stk = Number(s.amount !== undefined ? s.amount : s.stock) || 0;
            html += '<option value="' + s.id + '" data-price="' + s.price + '" data-provider="' + prov + '" data-stock="' + stk + '">' +
              '[' + prov + '] ' + escapeHtml(s.name) + ' (Còn ' + stk.toLocaleString() + ' acc) - ' + (typeof formatVND === "function" ? formatVND(s.price) : s.price + 'đ') +
            '</option>';
          });
          html += '</optgroup>';
        }
      });

      sel.innerHTML = html;
    }

    async function executeQuickTestBuy() {
      const sel = document.getElementById("quickTestProdSelect");
      const btn = document.getElementById("btnQuickTestBuy");
      const resBox = document.getElementById("quickTestResultBox");
      if (!sel) return;

      const prodId = sel.value;
      const opt = (sel.selectedOptions && sel.selectedOptions[0]) ? sel.selectedOptions[0] : (sel.options ? sel.options[sel.selectedIndex] : null);
      if (!opt || !prodId) {
        if (typeof showToast === "function") showToast("Vui lòng chọn một sản phẩm còn hàng trong danh sách!", "warning");
        return;
      }

      const prodName = opt ? opt.innerText : "Sản phẩm " + prodId;
      const price = opt ? Number(opt.getAttribute("data-price") || 0) : 0;
      const stock = opt ? Number(opt.getAttribute("data-stock") || 0) : 0;
      let provider = opt ? (opt.getAttribute("data-provider") || "sellmmo") : "sellmmo";
      const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[provider]) ? API_SOURCES[provider] : API_SOURCES.sellmmo;

      if (stock <= 0) {
        if (typeof showToast === "function") showToast("⚠️ Sản phẩm nguồn này hiện đang có số lượng tồn kho = 0 trên nhà cung cấp! Vui lòng chọn sản phẩm khác có hàng.", "warning");
        return;
      }

      // Khóa chống bấm liên tục làm dính rate limit "Thao tác quá nhanh"
      if (window._lastApiQuickTestTime && (Date.now() - window._lastApiQuickTestTime) < 2500) {
        if (typeof showToast === "function") showToast("⏳ Đang xử lý giao dịch trước, vui lòng chờ 2 giây...", "info");
        return;
      }
      window._lastApiQuickTestTime = Date.now();

      if (!confirm("Xác nhận mua test 1 tài khoản:\n[" + prodName + "]\n\nNguồn: " + pCfg.name + "\nGiá nhập: " + (typeof formatVND === "function" ? formatVND(price) : price + "đ") + " (Trừ từ ví nguồn)")) return;

      const originalBtnHtml = btn ? btn.innerHTML : "";
      if (btn) {
        btn.innerHTML = "<i class='fa-solid fa-spinner fa-spin'></i> Đang kết nối nguồn API...";
        btn.disabled = true;
      }
      if (resBox) resBox.style.display = "none";

      const actualCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[provider]) ? API_SOURCES[provider] : pCfg;

      try {
        const res = await executeSourceApiCall("buyProduct", {
          productId: prodId,
          amount: 1,
          provider: provider,
          baseUrl: actualCfg.baseUrl,
          apiKey: actualCfg.apiKey,
          username: actualCfg.username,
          password: actualCfg.password
        });

        if (res && res.success && Array.isArray(res.accounts) && res.accounts.length > 0) {
          if (resBox) {
            resBox.style.display = "block";
            resBox.innerHTML = '<span style="color:#10b981; font-weight:700;"><i class="fa-solid fa-circle-check"></i> Test thành công từ ' + pCfg.name + '!</span><br/>' +
              '<span style="color:#38bdf8;">Đơn nguồn: ' + (res.trans_id || '') + '</span><br/>' +
              '<code>' + escapeHtml(res.accounts[0]) + '</code>';
          }
          if (typeof showToast === "function") showToast("Mua test thành công 1 tài khoản từ " + pCfg.name + "!", "success");
          fetchSingleSourceProfile(provider, false);
        } else {
          throw new Error((res && (res.message || res.msg)) ? (res.message || res.msg) : "Giao dịch test không thành công");
        }
      } catch(err) {
        if (typeof showToast === "function") showToast("Lỗi mua test: " + err.message, "danger");
      } finally {
        if (btn) {
          btn.innerHTML = originalBtnHtml;
          btn.disabled = false;
        }
      }
    }
    window.executeQuickTestBuy = executeQuickTestBuy;

    async function testBuyForProduct(targetProdId) {
      const map = getApiProductMapping(targetProdId);
      if (!map || !map.sourceProdId) {
        if (typeof showToast === "function") showToast("Vui lòng chọn sản phẩm nguồn và bấm Lưu trước khi test!", "warning");
        return;
      }

      const provider = map.provider || "sellmmo";
      const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[provider]) ? API_SOURCES[provider] : API_SOURCES.sellmmo;
      const src = cachedSourceProducts.find(s => String(s.id) === String(map.sourceProdId));
      const pName = src ? src.name : map.sourceProdId;
      const pPrice = src ? src.price : (map.sourcePrice || 0);

      if (!confirm("Xác nhận mua test 1 tài khoản [" + pName + "] từ nguồn " + pCfg.name + "?\nGiá nhập: " + formatVND(pPrice))) return;

      if (typeof showToast === "function") showToast("Đang gửi lệnh mua test tới " + pCfg.name + "...", "info");

      // Auto-detect provider if mapping had wrong provider
      let sId = String(map.sourceProdId);
      if (sId === "13840" || sId === "138400") {
        sId = "121063";
        map.sourceProdId = "121063";
      }
      if (sId === "19745" || sId === "19768" || sId === "19773" || sId === "19767") {
        provider = "shop1989nd";
      } else if (sId === "712" || sId === "769" || sId === "797" || sId === "817" || sId === "818") {
        provider = "mail72h";
      } else if (sId === "119284" || sId === "13840" || sId === "121063" || sId === "117725" || sId.startsWith("1210") || sId.startsWith("1192") || sId.startsWith("1177")) {
        provider = "nguyenlieummo";
      }
      const actualCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[provider]) ? API_SOURCES[provider] : pCfg;

      try {
        const res = await executeSourceApiCall("buyProduct", {
          productId: map.sourceProdId,
          amount: 1,
          provider: provider,
          baseUrl: actualCfg.baseUrl,
          apiKey: actualCfg.apiKey,
          username: actualCfg.username,
          password: actualCfg.password,
          targetProdId: targetProdId
        });

        if (res && res.success && Array.isArray(res.accounts) && res.accounts.length > 0) {
          alert("✅ MUA TEST THÀNH CÔNG TỪ " + pCfg.name.toUpperCase() + "!\n\n" +
                "Mã giao dịch nguồn: " + (res.trans_id || "N/A") + "\n" +
                "Tài khoản nhận được:\n" + res.accounts.join("\n"));
          fetchSingleSourceProfile(provider, false);
        } else {
          alert("❌ MUA TEST THẤT BẠI TỪ " + pCfg.name.toUpperCase() + ":\n" + ((res && res.message) || JSON.stringify(res)));
        }
      } catch(e) {
        alert("❌ Lỗi kết nối khi mua test: " + e.message);
      }
    }
    window.testBuyForProduct = testBuyForProduct;

    function toggleShowApiKey() {
      const inp = document.getElementById("apiSourceKeyInput");
      if (inp) inp.type = inp.type === "password" ? "text" : "password";
    }
    window.toggleShowApiKey = toggleShowApiKey;

    function handleProviderKeyChange() {
      const sel = document.getElementById("apiSourceProviderSelectKey");
      const inp = document.getElementById("apiSourceKeyInput");
      if (!sel || !inp) return;
      const prov = sel.value;
      if (API_SOURCES[prov]) {
        inp.value = API_SOURCES[prov].apiKey || (API_SOURCES[prov].password ? API_SOURCES[prov].username + ":" + API_SOURCES[prov].password : "");
      }
    }
    window.handleProviderKeyChange = handleProviderKeyChange;

    function saveApiSourceKey() {
      const sel = document.getElementById("apiSourceProviderSelectKey");
      const inp = document.getElementById("apiSourceKeyInput");
      if (!inp) return;
      const prov = sel ? sel.value : "sellmmo";
      const key = inp.value.trim();
      if (!key) {
        if (typeof showToast === "function") showToast("Vui lòng không để trống API Key!", "warning");
        return;
      }
      if (API_SOURCES[prov]) {
        API_SOURCES[prov].apiKey = key;
      }
      try {
        localStorage.setItem("mmo_source_key_" + prov, key);
      } catch(e) {}
      if (typeof showToast === "function") showToast("Đã lưu API Key " + prov + "!", "success");
      fetchSingleSourceProfile(prov, true);
      fetchApiSourceProducts(true);
    }
    window.saveApiSourceKey = saveApiSourceKey;

    function saveSourceProxyUrl() {
      const inp = document.getElementById("apiSourceProxyInput");
      if (!inp) return;
      sourceProxyUrl = inp.value.trim();
      try {
        localStorage.setItem("mmo_source_proxy_url", sourceProxyUrl);
      } catch(e) {}
      if (sourceProxyUrl) {
        if (typeof showToast === "function") showToast("Đã lưu URL Proxy: " + sourceProxyUrl, "success");
      } else {
        if (typeof showToast === "function") showToast("Đã chuyển về Proxy IP sạch tự động (Dynamic Anti-Block)", "info");
      }
      // Lưu lên Google Apps Script nếu có quyền Admin
      if (typeof callGasApi === "function") {
        callGasApi("adminSaveSettings", {
          settings: {
            sourceProxyUrl: sourceProxyUrl
          }
        }).catch(function(e) { console.log("Proxy sync to sheet:", e); });
      }
      fetchSingleSourceProfile("mail72h", true);
      fetchSingleSourceProfile("sellmmo", true);
      fetchSingleSourceProfile("nguyenlieummo", true);
      fetchSingleSourceProfile("selltainguyenmmo", true);
      fetchSingleSourceProfile("shop1989nd", true);
    }
    window.saveSourceProxyUrl = saveSourceProxyUrl;

    async function initStockManagementUI() {
      // 1. Phản hồi chuyển tab tức thì trong 0ms từ bộ nhớ cache
      refreshAllShopStockUI();
      if (typeof handleStockProductChange === "function") {
        handleStockProductChange();
      }
      // 2. Chạy ngầm đồng bộ Turso trong nền, tuyệt đối không await làm treo/chậm 10 giây giao diện
      if (typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured()) {
        syncTursoStockToLocalUI().then(() => {
          refreshAllShopStockUI();
        }).catch(() => {});
      }
    }

    function handleStockProductChange() {
      const select = document.getElementById("admStockProductSelect");
      if (!select) return;
      const prodId = select.value;
      if (!prodId) return;

      try {
        localStorage.setItem("mmo_last_admin_stock_prod_id", prodId);
      } catch(e) {}

      const prod = (MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products.find(p => String(p.id) === String(prodId)) : null;
      const hasVars = prod && Array.isArray(prod.variants) && prod.variants.length > 0;

      const targetProdName = document.getElementById("admStockTargetProdName");
      const targetVarName = document.getElementById("admStockTargetVarName");
      if (targetProdName && prod) targetProdName.innerText = prod.name || prod.id;
      if (targetVarName && !hasVars) {
        targetVarName.innerText = "Kho chính";
        targetVarName.style.background = "rgba(99,102,241,0.2)";
        targetVarName.style.color = "#c7d2fe";
      }

      if (typeof updateVariantSelectForProduct === "function") {
        updateVariantSelectForProduct(prodId);
      }

      // Luôn ủy quyền sang handleStockVariantChange để truy vấn Turso Database trực tiếp
      if (hasVars || (typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured())) {
        if (typeof handleStockVariantChange === "function") handleStockVariantChange();
        return;
      }

      const map = getProductStocksMap();
      let accounts = map[prodId] || [];
      if ((!accounts || accounts.length === 0) && (prodId === "PROD_MTPIJ9XV" || prodId === "PROD_MTPG0PUD" || prodId === "SP_TIKTOK_BRAZIL")) {
        accounts = map["PROD_MTPIJ9XV"] || map["PROD_MTPG0PUD"] || map["SP_TIKTOK_BRAZIL"] || [];
      }

      const count = accounts.length > 0 ? accounts.length : getProductStockCount(prodId);

      // Nếu sản phẩm đã được Admin chủ động xóa sạch kho (manually cleared), KHÔNG BAO GIỜ tự động kéo lại acc cũ từ backend khi F5
      let isManuallyCleared = false;
      try {
        const clearedMap = JSON.parse(localStorage.getItem("mmo_manually_cleared_products") || "{}");
        if (clearedMap[prodId] || (typeof isSameOrAliasProduct === "function" && isSameOrAliasProduct(prodId, "PROD_MTPIJ9XV") && (clearedMap["PROD_MTPIJ9XV"] || clearedMap["PROD_MTPG0PUD"] || clearedMap["SP_TIKTOK_BRAZIL"]))) {
          isManuallyCleared = true;
        }
      } catch(e) {}

      // CHỈ kéo tài khoản từ Google Sheets nếu kho trống và CHƯA TỪNG bị admin xóa sạch
      // Đã bỏ tự động kéo acc cũ từ Cloud khi kho = 0}

      const countDisp = document.getElementById("admStockCountDisplay");
      if (countDisp) {
        countDisp.innerText = count + " acc";
        if (count === 0) countDisp.style.color = "#ef4444";
        else if (count < 5) countDisp.style.color = "#f59e0b";
        else countDisp.style.color = "#10b981";
      }

      const warningBox = document.getElementById("admStockLowWarning");
      if (warningBox) {
        if (count === 0) {
          warningBox.style.display = "flex";
          warningBox.style.borderColor = "rgba(239,68,68,0.4)";
          warningBox.style.background = "rgba(239,68,68,0.12)";
          warningBox.style.color = "#ef4444";
          warningBox.innerHTML = "<i class='fa-solid fa-circle-xmark'></i> <span><strong>CẢNH BÁO:</strong> Sản phẩm này đã <strong>HẾT HÀNG (0 acc)</strong>! Khách hàng không thể mua. Vui lòng nạp thêm tài khoản ngay.</span>";
        } else if (count < 5) {
          warningBox.style.display = "flex";
          warningBox.style.borderColor = "rgba(245,158,11,0.4)";
          warningBox.style.background = "rgba(245,158,11,0.12)";
          warningBox.style.color = "#f59e0b";
          warningBox.innerHTML = "<i class='fa-solid fa-triangle-exclamation'></i> <span><strong>CẢNH BÁO TỒN KHO THẤP:</strong> Chỉ còn <strong>" + count + "</strong> tài khoản trong kho! Cần nhập thêm để không bị gián đoạn đơn hàng.</span>";
        } else {
          warningBox.style.display = "none";
        }
      }

      const currentView = document.getElementById("admStockCurrentView");
      if (currentView) {
        const curVal = currentView.value || "";
        const hasStaleSold = (function() {
          try {
            const sMap = JSON.parse(localStorage.getItem("mmo_sold_accounts") || "{}");
            const lines = curVal.split("\n").map(l => l.trim()).filter(Boolean);
            return lines.some(l => sMap[l]);
          } catch(e) { return false; }
        })();
        if (document.activeElement !== currentView || hasStaleSold) {
          currentView.value = accounts.join("\n");
        }
      }
      if (typeof renderSoldStockAccountsView === "function") {
        renderSoldStockAccountsView(prodId, vVal);
      }
      if (typeof renderSoldStockAccountsView === "function") {
        renderSoldStockAccountsView(prodId, vVal);
      }

      if (count > 0) {
        (MOCK_DATA && MOCK_DATA.products || []).forEach(p => {
          if (p.id === prodId || (typeof isSameOrAliasProduct === "function" && isSameOrAliasProduct(p.id, prodId)) || (p.name && String(p.name).toUpperCase().includes("TIKTOK") && String(p.name).toUpperCase().includes("BRAZIL") && (prodId === "PROD_MTPIJ9XV" || prodId === "PROD_MTPG0PUD" || prodId === "SP_TIKTOK_BRAZIL"))) {
            p.stock = count;
          }
        });
        syncAllOpenViewsStock(prodId, count, accounts);
      }
    }

    let stockViewDebounceTimer = null;
    var _stockViewCountTimer = null;

    function handleCurrentStockViewInput() {
      const select = document.getElementById("admStockProductSelect");
      const varSelect = document.getElementById("admStockVariantSelect");
      const textarea = document.getElementById("admStockCurrentView");
      if (!select || !textarea) return;
      const prodId = select.value;
      if (!prodId) return;

      const lines = textarea.value.split("\n").map(l => l.trim()).filter(Boolean);
      const vVal = varSelect ? varSelect.value : "0";

      // Lưu đè trực tiếp vào sản phẩm ngay lập tức
      MMO_WAREHOUSE.setAccounts(prodId, vVal, lines);

      // Cập nhật số dòng hiển thị tức thì
      const countDisp = document.getElementById("admStockCountDisplay");
      if (countDisp) {
        countDisp.innerText = lines.length + " acc";
        countDisp.style.color = lines.length === 0 ? "#ef4444" : (lines.length < 5 ? "#f59e0b" : "#10b981");
      }

      // Tự động lưu lên Turso Cloud Database và đồng bộ tức thì sau 600ms ngừng gõ
      if (stockViewDebounceTimer) clearTimeout(stockViewDebounceTimer);
      stockViewDebounceTimer = setTimeout(() => {
        handleSaveCurrentStockViewInternal(false);
      }, 600);
    }
    window.handleCurrentStockViewInput = handleCurrentStockViewInput;

    var _importLinesDebounce = null;
    function updateImportLinesCount(immediate) {
      const textarea = document.getElementById("admStockBulkInput");
      const importLinesCount = document.getElementById("admStockImportLines");
      if (!textarea || !importLinesCount) return;

      const doCount = () => {
        const text = textarea.value;
        if (!text) {
          importLinesCount.innerText = "0 dòng";
          return;
        }
        let count = 0;
        const lines = text.split("\n");
        for (let i = 0; i < lines.length; i++) {
          if (lines[i].trim().length > 0) count++;
        }
        importLinesCount.innerText = count + " dòng";
      };

      if (immediate === true) {
        if (_importLinesDebounce) { clearTimeout(_importLinesDebounce); _importLinesDebounce = null; }
        doCount();
      } else {
        if (_importLinesDebounce) clearTimeout(_importLinesDebounce);
        _importLinesDebounce = setTimeout(doCount, 150);
      }
    }
    window.updateImportLinesCount = updateImportLinesCount;

    // [SSOT]: Nạp tài khoản trực tiếp vào biến thể sản phẩm
    async function handleImportStock() {
      const select = document.getElementById("admStockProductSelect");
      const varSelect = document.getElementById("admStockVariantSelect");
      const textarea = document.getElementById("admStockBulkInput");
      const importBtn = document.querySelector("button[onclick='handleImportStock()']");
      if (!select || !textarea) return;
      const prodId = select.value;
      if (!prodId) return;

      const prod = (MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products.find(p => String(p.id) === String(prodId)) : null;
      if (!prod) return;

      const hasVars = Array.isArray(prod.variants) && prod.variants.length > 0;
      let vVal = hasVars ? ((varSelect && varSelect.value !== undefined && varSelect.value !== "") ? varSelect.value : "0") : null;
      if (vVal === "ALL") vVal = "0";

      const text = textarea.value.trim();
      if (!text) {
        showToast("Vui lòng dán danh sách tài khoản cần nạp!", "warning");
        return;
      }
      const newLines = text.split("\n").map(l => l.trim()).filter(Boolean);
      if (newLines.length === 0) return;

      if (importBtn) {
        importBtn.disabled = true;
        importBtn.innerHTML = "<i class='fa-solid fa-spinner fa-spin'></i> Đang nạp kho...";
      }

      try {
        // 1. Luôn nạp trực tiếp vào kho nội bộ MMO_WAREHOUSE và cập nhật giao diện trong 0ms!
        const newStockCount = MMO_WAREHOUSE.importAccounts(prodId, vVal, newLines);
        textarea.value = "";
        const importLinesCount = document.getElementById("admStockImportLines");
        if (importLinesCount) importLinesCount.innerText = "0 dòng";

        if (hasVars && typeof updateVariantSelectForProduct === "function") {
          updateVariantSelectForProduct(prodId);
          if (varSelect && vVal !== null) varSelect.value = vVal;
        }

        // Cập nhật tức thì 0ms vào ô hiển thị tài khoản sẵn sàng trong kho
        const currentView = document.getElementById("admStockCurrentView");
        const targetV = hasVars ? (prod.variants[vVal] || prod.variants[0]) : prod;
        if (currentView && targetV && Array.isArray(targetV.accounts)) {
          currentView.value = targetV.accounts.join("\n");
        }
        const countDisp = document.getElementById("admStockCountDisplay");
        if (countDisp) {
          countDisp.innerText = newStockCount + " acc";
          countDisp.style.color = newStockCount > 0 ? "#10b981" : "#ef4444";
        }
        const warningBox = document.getElementById("admStockLowWarning");
        if (warningBox && newStockCount > 0) {
          warningBox.style.display = "none";
        }

        if (typeof saveProductsToStorage === "function") saveProductsToStorage();
        if (typeof recordProductVariants === "function") recordProductVariants(prodId, prod.variants, prod.name);
        refreshAllShopStockUI(prodId);

        const varName = (hasVars && prod.variants[vVal]) ? ("biến thể [" + prod.variants[vVal].name + "]") : "kho sản phẩm";
        showToast("🎉 Đã nạp thành công " + newLines.length + " tài khoản vào " + varName + "! Tồn kho: " + newStockCount + " acc.", "success");

        // 2. Chạy ngầm đồng bộ Turso Database nếu khả dụng (hoàn toàn chạy nền không chặn giao diện)
        if (typeof MMO_WORKER_API !== "undefined" && MMO_WORKER_API._checkWorkerAvailable()) {
          MMO_WORKER_API.adminImportAccounts(prodId, vVal || 0, newLines, prod).catch(e => console.warn("Turso import bg note:", e));
        }

        if (typeof callGasApi === "function") {
          callGasApi("adminImportStock", {
            prodId: prodId,
            variantIdx: vVal,
            accounts: newLines.join("\n"),
            variants: hasVars ? JSON.stringify(prod.variants) : "",
            stock: newStockCount
          }).catch(err => console.warn("Lỗi sync Google Sheets:", err));
        }

      } catch(err) {
        console.error("Lỗi nạp kho:", err);
        showToast("⚠️ Lỗi nạp kho: " + err.message, "danger");
      } finally {
        if (importBtn) {
          importBtn.disabled = false;
          importBtn.innerHTML = "<i class='fa-solid fa-cloud-arrow-up'></i> Nạp Vào Kho Hàng";
        }
      }
    }
    window.handleImportStock = handleImportStock;

    async function handleSaveCurrentStockViewInternal(isUserClick = false) {
      const select = document.getElementById("admStockProductSelect");
      const varSelect = document.getElementById("admStockVariantSelect");
      const textarea = document.getElementById("admStockCurrentView");
      if (!select || !textarea) return;
      const prodId = select.value;
      if (!prodId) return;

      const prod = (MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products.find(p => String(p.id) === String(prodId)) : null;
      if (!prod) return;

      const hasVars = Array.isArray(prod.variants) && prod.variants.length > 0;
      let vVal = hasVars ? ((varSelect && varSelect.value !== undefined && varSelect.value !== "") ? varSelect.value : "0") : null;
      if (vVal === "ALL") vVal = "0";

      const text = textarea.value.trim();
      const accounts = text ? text.split("\n").map(l => l.trim()).filter(Boolean) : [];

      // [UNIFIED WAREHOUSE CORE]: Cập nhật bộ nhớ local và broadcast tức thì (0ms)
      const newTotalStock = MMO_WAREHOUSE.setAccounts(prodId, vVal, accounts);
      const prodTotalStock = MMO_WAREHOUSE.getStock(prodId, null);

      if (hasVars && typeof updateVariantSelectForProduct === "function" && document.activeElement !== varSelect && (!textarea || document.activeElement !== textarea)) {
        updateVariantSelectForProduct(prodId);
        if (varSelect && vVal !== null) varSelect.value = vVal;
      }

      const count = accounts.length;
      const countDisp = document.getElementById("admStockCountDisplay");
      if (countDisp) {
        countDisp.innerText = count + " acc";
        countDisp.style.color = count > 0 ? "#10b981" : "#ef4444";
      }

      syncAllOpenViewsStock(prodId, prodTotalStock, accounts, false, vVal);

      if (isUserClick) {
        showToast("💾 Đã lưu kho thành công! Tồn kho hiện tại: " + accounts.length + " acc.", "success");
      }

      // NẾU ĐÃ KẾT NỐI TURSO DATABASE: ĐỒNG BỘ TRỰC TIẾP LÊN TURSO CHẠY NGẦM
      if (typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured() && typeof MMO_WORKER_API !== "undefined" && MMO_WORKER_API._checkWorkerAvailable()) {
        TURSO_CLIENT.setAvailableAccounts(prodId, vVal, accounts, prod).catch(e => console.warn("Turso save bg note:", e));
      }

      if (isUserClick && typeof callGasApi === "function") {
        callGasApi("adminImportStock", {
          prodId: prodId,
          variantIdx: vVal,
          accounts: accounts.join("\n"),
          variants: hasVars ? JSON.stringify(prod.variants) : "",
          stock: prodTotalStock,
          overwrite: true
        }).catch(err => console.warn("Lỗi sync Google Sheets:", err));
      }
    }

    function handleSaveCurrentStockView() {
      handleSaveCurrentStockViewInternal(true);
    }
    window.handleSaveCurrentStockView = handleSaveCurrentStockView;

    async function handleClearCurrentProductStock() {
      const select = document.getElementById("admStockProductSelect");
      if (!select) return;
      const prodId = select.value;
      if (!prodId) return;

      const prod = (MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products.find(p => String(p.id) === String(prodId)) : null;
      const prodName = prod ? prod.name : prodId;
      const varSelect = document.getElementById("admStockVariantSelect");
      const hasVars = prod && Array.isArray(prod.variants) && prod.variants.length > 0;
      const isVariantMode = hasVars && varSelect && varSelect.parentElement && varSelect.parentElement.style.display !== "none";
      const vVal = isVariantMode ? varSelect.value : "ALL";
      const isClearAll = !isVariantMode || vVal === "ALL";
      const targetKey = (!isClearAll) ? getVariantStockKey(prodId, vVal) : prodId;

      const targetDesc = (!isClearAll && prod.variants && prod.variants[vVal]) 
        ? ("biến thể [" + prod.variants[vVal].name + "]") 
        : ("toàn bộ kho [" + prodName + "]");
      if (!confirm("⚠️ Bạn có chắc muốn XÓA SẠCH toàn bộ tài khoản trong " + targetDesc + "? Dữ liệu tài khoản sẽ bị xóa hoàn toàn.")) {
        return;
      }

      // XÓA TRỰC TIẾP TRÊN TURSO DATABASE
      if (typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured()) {
        try {
          await TURSO_CLIENT.clearAvailableAccounts(prodId, !isClearAll ? vVal : null);
          const currentView = document.getElementById("admStockCurrentView");
          if (currentView) currentView.value = "";
          const countDisp = document.getElementById("admStockCountDisplay");
          if (countDisp) {
            countDisp.innerText = "0 acc";
            countDisp.style.color = "#ef4444";
          }

          // XÓA ĐỒNG BỘ TRONG BỘ NHỚ LOCAL ĐỂ KHÔNG BỊ TRẢ VỀ STOCK CŨ
          if (hasVars && !isClearAll && prod.variants[vVal]) {
            prod.variants[vVal].accounts = [];
            prod.variants[vVal].stock = 0;
            prod.stock = prod.variants.reduce((s, v) => s + (Array.isArray(v.accounts) ? v.accounts.length : 0), 0);
            if (typeof recordProductVariants === "function") recordProductVariants(prodId, prod.variants, prod.name);
          } else if (hasVars && isClearAll) {
            prod.variants.forEach(v => { v.accounts = []; v.stock = 0; });
            prod.stock = 0;
            if (typeof recordProductVariants === "function") recordProductVariants(prodId, prod.variants, prod.name);
          } else {
            prod.accounts = [];
            prod.stock = 0;
          }
          if (typeof saveProductsToStorage === "function") saveProductsToStorage();
          MMO_WAREHOUSE._broadcast(prodId, isClearAll ? "ALL" : vVal, [], 0);
          refreshAllShopStockUI(prodId);
          syncAllOpenViewsStock(prodId, 0, [], false, isClearAll ? "ALL" : vVal);

          if (hasVars && typeof updateVariantSelectForProduct === "function") {
            updateVariantSelectForProduct(prodId);
            if (varSelect && isVariantMode) varSelect.value = vVal;
          }
          showToast("🗑️ Đã xóa sạch tài khoản trong " + targetDesc + " trên Turso Database!", "success");
          return;
        } catch(tursoClearErr) {
          console.error("Lỗi xóa kho Turso:", tursoClearErr);
          showToast("Lỗi xóa kho Turso: " + tursoClearErr.message, "danger");
          return;
        }
      }

      const map = getProductStocksMap();
      const normName = prodName && typeof normApiText === "function" ? normApiText(prodName) : "";

      if (!isClearAll) {
        // Xóa kho của đúng biến thể này
        map[targetKey] = [];
        if (normName) map[normName + "__VAR__" + vVal] = [];
        if (vVal === "0" || vVal === 0) {
          map[prodId] = [];
          if (normName) map[normName] = [];
        }
        Object.keys(map).forEach(k => {
          if (k === targetKey || k === (normName + "__VAR__" + vVal) || (k.startsWith(prodId) && k.endsWith("__VAR__" + vVal)) || (normName && k.startsWith(normName) && k.endsWith("__VAR__" + vVal))) {
            map[k] = [];
          }
        });
        if (prod && prod.variants && prod.variants[vVal]) {
          prod.variants[vVal].stock = 0;
        }
      } else {
        // Xóa sạch toàn bộ tài khoản của sản phẩm và TẤT CẢ các biến thể
        map[prodId] = [];
        if (normName) map[normName] = [];
        Object.keys(map).forEach(k => {
          if (k === prodId || k.startsWith(prodId + "__VAR__") || (normName && (k === normName || k.startsWith(normName + "__VAR__")))) {
            map[k] = [];
          }
        });
        if (hasVars) {
          prod.variants.forEach((v, idx) => {
            const vk = getVariantStockKey(prodId, idx);
            map[vk] = [];
            if (normName) map[normName + "__VAR__" + idx] = [];
            v.stock = 0;
          });
        }
        if (prod) prod.stock = 0;
      }
      saveProductStocksMap(map);

      // Đánh dấu sản phẩm/biến thể đã bị xóa kho thủ công
      try {
        const clearedMap = JSON.parse(localStorage.getItem("mmo_manually_cleared_products") || "{}");
        if (!isClearAll) {
          clearedMap[targetKey] = true;
          if (normName) clearedMap[normName + "__VAR__" + vVal] = true;
        } else {
          clearedMap[prodId] = true;
          if (normName) clearedMap[normName] = true;
          if (hasVars) {
            prod.variants.forEach((v, idx) => {
              clearedMap[getVariantStockKey(prodId, idx)] = true;
              if (normName) clearedMap[normName + "__VAR__" + idx] = true;
            });
          }
        }
        localStorage.setItem("mmo_manually_cleared_products", JSON.stringify(clearedMap));
      } catch(e) {}

      const totalProdStock = (typeof getVariantStockCount === "function") ? getVariantStockCount(prod || prodId, null) : 0;
      if (prod) prod.stock = totalProdStock;
      if (typeof saveProductsToStorage === "function") saveProductsToStorage();

      const currentView = document.getElementById("admStockCurrentView");
      if (currentView) currentView.value = "";

      const countDisp = document.getElementById("admStockCountDisplay");
      if (countDisp) {
        countDisp.innerText = "0 acc";
        countDisp.style.color = "#ef4444";
      }

      if (hasVars && typeof updateVariantSelectForProduct === "function") {
        updateVariantSelectForProduct(prodId);
        if (varSelect && isVariantMode) varSelect.value = vVal;
      }

      const opt = select.querySelector('option[value="' + prodId + '"]');
      if (opt) {
        opt.textContent = prodName + (totalProdStock === 0 ? " ❌ [HẾT HÀNG]" : (" (" + totalProdStock + " acc)"));
      }

      // Đồng bộ ngay lập tức tới tất cả các view đang mở (Chi tiết sản phẩm, danh sách sản phẩm)
      syncAllOpenViewsStock(prodId, totalProdStock, []);
      showToast("🗑️ Đã xóa sạch tài khoản trong " + targetDesc + "!", "success");

      // Đồng bộ xóa kho triệt để trên Google Sheets
      if (typeof callGasApi === "function") {
        try {
          callGasApi("adminImportStock", {
            prodId: prodId,
            variantIdx: !isClearAll ? vVal : "ALL",
            targetKey: targetKey,
            accounts: "",
            variants: (prod && prod.variants ? JSON.stringify(prod.variants) : ""),
            overwrite: true,
            replace: true
          }).catch(function(err) {
            console.warn("Lỗi đồng bộ xóa kho Google Sheets:", err);
          });
        } catch(err) {}
      }
    }
    window.handleClearCurrentProductStock = handleClearCurrentProductStock;

