    window.loadGeneralSettingsUI = loadGeneralSettingsUI;

    function saveAllAiApiKeysFromSystem(silent) {
      const providers = ['groq', 'cerebras', 'openrouter', 'gemini', 'nvidia', 'mistral'];
      let savedCount = 0;

      providers.forEach(function(p) {
        const el = document.getElementById('setAiKey' + p.charAt(0).toUpperCase() + p.slice(1));
        if (el) {
          const v = el.value.trim();
          if (v) {
            MMO_AI_KEYS.set(p, v);
            savedCount++;
          } else if (MMO_AI_KEYS.get(p)) {
            // BẢO VỆ TUYỆT ĐỐI: NẾU Ô INPUT RỖNG THÌ GIỮ NGUYÊN KEY CŨ, TUYỆT ĐỐI KHÔNG XÓA!
            savedCount++;
          }
        } else {
          if (MMO_AI_KEYS.get(p)) savedCount++;
        }
      });

      const statusEl = document.getElementById('aiSystemKeySaveStatus');
      if (statusEl) {
        statusEl.innerHTML = '<span style="color:#10b981; font-weight:700;"><i class="fa-solid fa-circle-check"></i> Đã lưu thành công danh sách API Key AI (' + savedCount + ' key đang hoạt động)!</span>';
        setTimeout(function() { if (statusEl) statusEl.innerHTML = ''; }, 4000);
      }
      if (!silent && typeof showToast === 'function') {
        showToast('✅ Đã lưu danh sách API Key AI thành công (' + savedCount + ' key)!', 'success');
      }
      if (typeof onAiProviderChange === 'function') onAiProviderChange();
    }
    window.saveAllAiApiKeysFromSystem = saveAllAiApiKeysFromSystem;

    function handleSaveGeneralSettings(e) {
      if (e) {
        if (e.preventDefault) e.preventDefault();
        if (e.stopPropagation) e.stopPropagation();
      }
      try {
        const siteName = document.getElementById("setSiteName") ? document.getElementById("setSiteName").value.trim() : "MUABANTAIKHOANMMO";
        const googleClientId = document.getElementById("setGoogleClientId") ? document.getElementById("setGoogleClientId").value.trim() : "";
        const affiliateRate = parseInt(document.getElementById("setAffiliateRate") ? document.getElementById("setAffiliateRate").value : 10) || 10;
        const hotline = document.getElementById("setHotline") ? document.getElementById("setHotline").value.trim() : "0968033451";
        const telegram = document.getElementById("setTelegram") ? document.getElementById("setTelegram").value.trim() : "https://t.me/groupmuabantaikhoanmmo";
        
        // Marquee text (lấy đúng giá trị người dùng vừa gõ vào ô)
        const marqueeInput = document.getElementById("setMarqueeText");
        const marqueeText = marqueeInput ? marqueeInput.value.trim() : "";

        const gasUrl = document.getElementById("setGasUrl") ? document.getElementById("setGasUrl").value.trim() : "";
        
        // Lấy đúng ID của các ô Logo, Favicon, OG Image trong HTML
        const brandLogo = document.getElementById("setSiteLogoUrl") ? document.getElementById("setSiteLogoUrl").value.trim() : "";
        const brandFavicon = document.getElementById("setSiteFaviconUrl") ? document.getElementById("setSiteFaviconUrl").value.trim() : "";
        const brandOgImage = document.getElementById("setSiteOgImageUrl") ? document.getElementById("setSiteOgImageUrl").value.trim() : "";

        const settings = {
          siteName: siteName,
          googleClientId: googleClientId,
          affiliateRate: affiliateRate,
          hotline: hotline,
          telegram: telegram,
          marqueeText: marqueeText,
          gasUrl: gasUrl,
          brandLogo: brandLogo,
          brandFavicon: brandFavicon,
          brandOgImage: brandOgImage,
          _lastSavedAt: Date.now()
        };

        if (typeof saveAllAiApiKeysFromSystem === "function") {
          saveAllAiApiKeysFromSystem(true);
        } else {
          const providers = ['groq', 'cerebras', 'openrouter', 'gemini', 'nvidia', 'mistral'];
          providers.forEach(function(p) {
            const el = document.getElementById('setAiKey' + p.charAt(0).toUpperCase() + p.slice(1));
            if (el) {
              const v = el.value.trim();
              if (v) {
                MMO_AI_KEYS.set(p, v);
                settings['ai_key_' + p] = v;
              } else {
                const existing = MMO_AI_KEYS.get(p);
                if (existing) settings['ai_key_' + p] = existing;
              }
            } else {
              const existing = MMO_AI_KEYS.get(p);
              if (existing) settings['ai_key_' + p] = existing;
            }
          });
        }
        localStorage.setItem("mmo_system_settings", JSON.stringify(settings));
        localStorage.setItem("mmo_general_settings", JSON.stringify(settings));

        // Áp dụng ngay lập tức lên toàn bộ giao diện
        applyBrandCustomizations(settings);
        if (typeof syncZaloLinks === "function") syncZaloLinks(settings.hotline);
        if (typeof syncTelegramLinks === "function") syncTelegramLinks(settings.telegram);
        if (typeof syncMarqueeNotice === "function") syncMarqueeNotice(settings.marqueeText);

        // Phát sóng đa tab (BroadcastChannel) để cập nhật tức thì mọi tab đang mở
        try {
          if (typeof BroadcastChannel !== "undefined") {
            const bc = new BroadcastChannel("mmo_settings_channel");
            bc.postMessage({ type: "SETTINGS_UPDATED", settings: settings });
          }
        } catch(e) {}

        // Đồng bộ lưu lên Google Apps Script / Google Sheets nếu có cấu hình
        if (typeof callGasApi === "function") {
          const callerEmail = (typeof currentUser !== "undefined" && currentUser && currentUser.email) ? currentUser.email : ((typeof getAdminEmails === "function" && getAdminEmails()[0]) || "manhdongvtc@gmail.com");
          callGasApi("adminSaveSettings", {
            adminEmail: callerEmail,
            settings: {
              tickerText: marqueeText,
              TICKER_TEXT: marqueeText,
              siteName: siteName,
              SITE_NAME: siteName,
              hotline: hotline,
              HOTLINE: hotline,
              telegram: telegram,
              TELEGRAM: telegram,
              googleClientId: googleClientId,
              GOOGLE_CLIENT_ID: googleClientId
            }
          }).then(function(res) {
            console.log("Đã đồng bộ thông báo & cài đặt lên máy chủ:", res);
          }).catch(function(e) { console.warn("Lỗi đồng bộ cấu hình lên Google Sheets:", e); });
        }

        if (typeof showToast === "function") {
          showToast("🎉 Lưu cài đặt hệ thống, thương hiệu & thông báo thành công!", "success");
        }
      } catch(errSave) {
        console.error("handleSaveGeneralSettings error:", errSave);
        if (typeof showToast === "function") {
          showToast("⚠️ Có lỗi khi lưu: " + errSave.message, "danger");
        }
      }
      return false;
    }
    window.handleSaveGeneralSettings = handleSaveGeneralSettings;

    // =========================================================================
    // SẢN PHẨM 2 THANH BÊN THAY ĐỔI MỖI LẦN F5 & ĐỒNG BỘ TELEGRAM, MARQUEE
    // =========================================================================
    function renderDynamicFlankingProducts() {
      try {
        const activeProds = (typeof getVisibleProducts === "function") ? getVisibleProducts() : ((typeof MOCK_DATA !== "undefined" && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products.filter(function(p) { return !p.isDeleted; }) : []);
        if (activeProds.length === 0) return;

        // Xáo trộn ngẫu nhiên danh sách sản phẩm mỗi lần chạy (F5)
        const shuffled = [...activeProds].sort(function() { return 0.5 - Math.random(); });
        const pLeft = shuffled[0] || activeProds[0];
        const pRight = shuffled[1] || (activeProds.length > 1 ? activeProds[1] : activeProds[0]);
        const pSidebar = shuffled[2] || (activeProds.length > 2 ? activeProds[2] : (activeProds.length > 1 ? activeProds[1] : activeProds[0]));

        function renderCardContent(cardEl, p) {
          if (!cardEl || !p) return;
          const rate = p.affiliateRate || 10;
          const commVnd = Math.round((p.price || 0) * (rate / 100));
          const commStr = (typeof formatVND === "function") ? formatVND(commVnd) : (commVnd.toLocaleString("vi-VN") + " Đ");
          const priceStr = (typeof formatVND === "function") ? formatVND(p.price || 0) : ((p.price || 0).toLocaleString("vi-VN") + " đ");
          const ratingStr = (p.rating || 5.0).toFixed ? (p.rating || 5.0).toFixed(1) : (p.rating || "5.0");

          cardEl.innerHTML = 
            '<div class="sponsor-img-wrap">' +
              '<img alt="' + escapeHtml(p.name) + '" src="' + escapeHtml(p.image || '') + '"/>' +
            '</div>' +
            '<h4 class="sponsor-title">' +
              '<a href="?prod=' + encodeURIComponent(p.id) + '&amp;view=viewProductDetail" target="_blank" onclick="if(!event.ctrlKey &amp;&amp; !event.metaKey &amp;&amp; event.button === 0){ event.preventDefault(); openProductDetailById(\'' + escapeHtml(p.id) + '\'); }" style="color:inherit; text-decoration:none;">' +
                escapeHtml(p.name) +
              '</a>' +
            '</h4>' +
            '<span class="sponsor-commission"><i class="fa-solid fa-dollar-sign"></i> HOA HỒNG: ' + rate + '% (~' + commStr + ')</span>' +
            '<div class="sponsor-footer">' +
              '<span class="sponsor-price">' + priceStr + '</span>' +
              '<span class="sponsor-rating"><i class="fa-solid fa-star"></i> ' + ratingStr + '</span>' +
            '</div>';

          cardEl.onclick = function(e) {
            if (e.target.closest('a')) return;
            if (typeof openProductDetailById === "function") openProductDetailById(p.id);
          };
        }

        renderCardContent(document.getElementById("heroLeftSponsorCard"), pLeft);
        renderCardContent(document.getElementById("heroRightSponsorCard"), pRight);
        renderCardContent(document.getElementById("homeSidebarRightCard"), pSidebar);
      } catch(errFlank) {
        console.error("renderDynamicFlankingProducts error:", errFlank);
      }
    }
    window.renderDynamicFlankingProducts = renderDynamicFlankingProducts;

    // ĐỒNG BỘ SỐ HOTLINE & LINK ZALO TỰ ĐỘNG ĐẾN TOÀN BỘ WEBSITE
    function syncZaloLinks(zaloPhone) {
      try {
        let p = zaloPhone;
        if (!p) {
          const s = (typeof getGeneralSettings === "function") ? getGeneralSettings() : {};
          p = (s && s.hotline) ? s.hotline.trim() : "0968033451";
        }
        p = (p || "").trim();
        const cleanDigits = p.replace(/[^0-9]/g, "");
        const cleanPhone = cleanDigits || "0968033451";

        // Định dạng hiển thị chuẩn (VD: 0975.902.076)
        let formattedPhone = cleanPhone;
        if (cleanPhone.length === 10) {
          formattedPhone = cleanPhone.slice(0, 4) + "." + cleanPhone.slice(4, 7) + "." + cleanPhone.slice(7);
        } else if (cleanPhone.length === 11) {
          formattedPhone = cleanPhone.slice(0, 5) + "." + cleanPhone.slice(5, 8) + "." + cleanPhone.slice(8);
        }

        const zaloUrl = "https://zalo.me/" + cleanPhone;

        // 1. Cập nhật tất cả các thẻ a Zalo (loại trừ link chia sẻ zalo.me/share)
        const selLinks = "a[href*='zalo.me'], .btn-chat-live, .mmo-zalo-link";
        document.querySelectorAll(selLinks).forEach(function(el) {
          if (el.href && el.href.includes("zalo.me/share")) return;
          el.href = zaloUrl;
          el.setAttribute("target", "_blank");
          el.setAttribute("rel", "noopener noreferrer");
          el.onclick = function(ev) {
            ev.preventDefault();
            window.open(zaloUrl, "_blank");
          };
        });

        // 2. Cập nhật tất cả các vị trí hiển thị text số điện thoại
        document.querySelectorAll(".mmo-zalo-phone-display").forEach(function(el) {
          el.innerText = formattedPhone;
        });

        // 3. Cập nhật text trong sơ đồ sitemap
        const sitemapZaloEl = document.getElementById("sitemapZaloText");
        if (sitemapZaloEl) {
          sitemapZaloEl.innerHTML = "Trung Tâm Hỗ Trợ 24/7 (Zalo: <span class='mmo-zalo-phone-display'>" + formattedPhone + "</span>)";
        }

        // 4. Cập nhật text trong chính sách bảo mật
        const policyHotlineEl = document.getElementById("policyHotlineText");
        if (policyHotlineEl) {
          policyHotlineEl.innerText = formattedPhone;
        }

        // 5. Cập nhật ô input trong Admin nếu có và không đang focus
        const inputHotline = document.getElementById("setHotline");
        if (inputHotline && document.activeElement !== inputHotline) {
          inputHotline.value = cleanPhone;
        }
      } catch(e) {
        console.error("syncZaloLinks error:", e);
      }
    }
    window.syncZaloLinks = syncZaloLinks;

    // ĐỒNG BỘ LINK TELEGRAM ĐẾN TẤT CẢ NÚT/LIÊN KẾT TRÊN TRANG
    function syncTelegramLinks(teleUrl) {
      try {
        let url = teleUrl;
        if (!url) {
          const s = (typeof getGeneralSettings === "function") ? getGeneralSettings() : {};
          url = (s && s.telegram) ? s.telegram.trim() : "https://t.me/groupmuabantaikhoanmmo";
        }
        url = (url || "").trim();
        if (url && !url.startsWith("http://") && !url.startsWith("https://")) {
          url = "https://" + url;
        }
        if (!url) url = "https://t.me/groupmuabantaikhoanmmo";

        const sel = "a[href*='t.me'], a[href*='telegram'], .btn-telegram, .connect-card-box[href*='t.me'], .mmo-tele-link";
        document.querySelectorAll(sel).forEach(function(el) {
          el.href = url;
          el.setAttribute("target", "_blank");
          el.setAttribute("rel", "noopener noreferrer");
          el.onclick = function(ev) {
            ev.preventDefault();
            window.open(url, "_blank");
          };
        });
      } catch(e) {
        console.error("syncTelegramLinks error:", e);
      }
    }
    window.syncTelegramLinks = syncTelegramLinks;

    // ĐỒNG BỘ CHỮ CHẠY THÔNG BÁO (MARQUEE) - VÒNG LẶP LIÊN TỤC VÔ TẬN KHÔNG KHOẢNG TRỐNG
    function syncMarqueeNotice(text) {
      try {
        let notice = text;
        if (notice === undefined || notice === null) {
          const s = (typeof getGeneralSettings === "function") ? getGeneralSettings() : {};
          notice = (s && s.marqueeText !== undefined && s.marqueeText !== null) ? s.marqueeText : "🎉 Chào mừng bạn đến với MUABANTAIKHOANMMO.COM - Hệ thống mua bán tài khoản MMO, Gmail, TikTok, Facebook, Rom & Tools uy tín số 1. Nạp tiền tự động qua SePay 24/7. Hỗ trợ bảo hành 1-đổi-1 siêu tốc!";
        }
        const wrap = document.getElementById("homeMarqueeWrap");
        const track = document.getElementById("homeMarqueeTrack");
        if (wrap && track) {
          const clean = (notice || "").trim();
          if (!clean) {
            wrap.style.display = "none";
            return;
          }
          wrap.style.display = "flex";
          const safeText = (typeof escapeHtml === "function") ? escapeHtml(clean) : clean.replace(/</g, "&lt;").replace(/>/g, "&gt;");
          
          const singleItemHtml = 
            '<span class="marquee-item"><i class="fa-solid fa-bullhorn" style="color:#38bdf8; margin-right:8px; font-size:0.8rem;"></i>' + safeText + '</span>' +
            '<span class="marquee-bullet">✦</span>' +
            '<span class="marquee-item"><i class="fa-solid fa-star" style="color:#f59e0b; margin-right:8px; font-size:0.8rem;"></i>' + safeText + '</span>' +
            '<span class="marquee-bullet">✦</span>';

          track.innerHTML = 
            '<div class="marquee-group">' + singleItemHtml + '</div>' +
            '<div class="marquee-group" aria-hidden="true">' + singleItemHtml + '</div>';
            
          const totalLength = clean.length;
          const duration = Math.max(22, Math.min(60, Math.round(totalLength * 0.35)));
          track.style.animationDuration = duration + "s";
        }
      } catch(e) {
        console.error("syncMarqueeNotice error:", e);
      }
    }
