    // ==================== MMO TOOLS LOGIC (6 CÔNG CỤ MMO) ====================
    function escapeHtml(str) {
      if (str === null || str === undefined) return '';
      return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
    }

    function switchTool(toolId) {
      const tools = ["toolFbLive", "toolTtLive", "tool2Fa", "toolGmailDot", "toolFakeInfo", "toolTtFollow", "toolFbFollow"];
      tools.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.style.display = "none";
      });

      document.querySelectorAll(".tool-tab-btn").forEach(btn => btn.classList.remove("active"));

      const targetTool = document.getElementById(toolId);
      if (targetTool) {
        targetTool.style.display = "block";
      }

      const activeMap = {
        toolFbLive: "tabBtnToolFbLive",
        toolTtLive: "tabBtnToolTtLive",
        tool2Fa: "tabBtnTool2Fa",
        toolGmailDot: "tabBtnToolGmailDot",
        toolFakeInfo: "tabBtnToolFakeInfo",
        toolTtFollow: "tabBtnToolTtFollow",
        toolFbFollow: "tabBtnToolFbFollow"
      };
      if (activeMap[toolId]) {
        const btn = document.getElementById(activeMap[toolId]);
        if (btn) btn.classList.add("active");
      }
    }
    window.switchTool = switchTool;

    // =========================================================================
    // GMAIL DOT TRICK GENERATOR FUNCTIONS
    // =========================================================================
    function generateGmailDotTrick() {
      const rawInput = document.getElementById("inputGmailDot") ? document.getElementById("inputGmailDot").value.trim() : "";
      if (!rawInput) {
        if (typeof showToast === "function") showToast("Vui lòng nhập địa chỉ Gmail!", "warning");
        return;
      }
      
      let cleanUser = rawInput.toLowerCase();
      if (cleanUser.includes("@")) {
        cleanUser = cleanUser.split("@")[0].trim();
      }
      cleanUser = cleanUser.replace(/\./g, "").split("+")[0].replace(/[^a-z0-9]/g, "");

      if (cleanUser.length < 2) {
        if (typeof showToast === "function") showToast("Tên Gmail quá ngắn để tạo Dot Trick (tối thiểu 2 ký tự)!", "warning");
        return;
      }
      if (cleanUser.length > 30) {
        cleanUser = cleanUser.substring(0, 30);
      }

      const maxLimit = parseInt(document.getElementById("gmailDotLimit") ? document.getElementById("gmailDotLimit").value : "500") || 500;
      const includeGooglemail = document.getElementById("gmailDotGooglemail") ? document.getElementById("gmailDotGooglemail").checked : true;
      const includePlus = document.getElementById("gmailDotPlus") ? document.getElementById("gmailDotPlus").checked : false;

      const results = [];
      const chars = cleanUser.split("");
      const n = chars.length;
      const numGaps = n - 1;
      const totalCombos = Math.pow(2, numGaps);
      const combosToGenerate = Math.min(totalCombos, maxLimit);

      for (let i = 0; i < combosToGenerate; i++) {
        let emailUser = chars[0];
        for (let j = 0; j < numGaps; j++) {
          if ((i & (1 << j)) !== 0) {
            emailUser += ".";
          }
          emailUser += chars[j + 1];
        }
        results.push(emailUser + "@gmail.com");
        if (includeGooglemail && results.length < maxLimit * 2) {
          results.push(emailUser + "@googlemail.com");
        }
      }

      if (includePlus) {
        const plusTags = ["1", "2", "3", "sub", "mmo", "vip", "order", "acc"];
        plusTags.forEach(tag => {
          results.push(cleanUser + "+" + tag + "@gmail.com");
          if (includeGooglemail) {
            results.push(cleanUser + "+" + tag + "@googlemail.com");
          }
        });
      }

      const uniqueResults = Array.from(new Set(results));
      const outputEl = document.getElementById("outputGmailDot");
      if (outputEl) {
        outputEl.value = uniqueResults.join("\n");
      }

      const statTotal = document.getElementById("gmailDotStatTotal");
      if (statTotal) statTotal.innerText = uniqueResults.length.toLocaleString("vi-VN");

      const statRoot = document.getElementById("gmailDotStatRoot");
      if (statRoot) statRoot.innerText = cleanUser + "@gmail.com";

      if (typeof showToast === "function") {
        showToast("🎉 Đã tạo thành công " + uniqueResults.length + " biến thể Gmail Dot Trick!", "success");
      }
    }
    window.generateGmailDotTrick = generateGmailDotTrick;

    function copyGmailDotOutput() {
      const out = document.getElementById("outputGmailDot");
      if (!out || !out.value.trim()) {
        if (typeof showToast === "function") showToast("Chưa có danh sách Gmail để sao chép!", "warning");
        return;
      }
      if (typeof copyTextDirect === "function") {
        copyTextDirect(out.value);
        if (typeof showToast === "function") showToast("✅ Đã sao chép toàn bộ danh sách Gmail Dot Trick vào bộ nhớ tạm!", "success");
      }
    }
    window.copyGmailDotOutput = copyGmailDotOutput;

    function downloadGmailDotTxt() {
      const out = document.getElementById("outputGmailDot");
      if (!out || !out.value.trim()) {
        if (typeof showToast === "function") showToast("Chưa có danh sách Gmail để tải về!", "warning");
        return;
      }
      const blob = new Blob([out.value], { type: "text/plain;charset=utf-8" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = "gmail_dot_trick_" + Date.now() + ".txt";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      if (typeof showToast === "function") showToast("💾 Đã tải file .txt danh sách Gmail về máy!", "success");
    }
    window.downloadGmailDotTxt = downloadGmailDotTxt;

