    // DEPOSIT LOGIC (CHỌN SỐ TIỀN & TẠO QR ĐỘNG)
    let currentDepositAmount = 200000;

    function selectDepositAmount(amt) {
      currentDepositAmount = amt;
      const inp = document.getElementById("depositCustomAmountInput");
      if (inp) inp.value = amt;

      // Update preset buttons styling
      document.querySelectorAll(".btn-preset-amt").forEach(btn => {
        btn.style.background = "#131d2e";
        btn.style.border = "1px solid #1e293b";
      });
      const activeBtn = document.getElementById("preset_" + amt);
      if (activeBtn) {
        activeBtn.style.background = "#10b981";
        activeBtn.style.border = "1px solid #10b981";
      }

      prepareDeposit(amt, false);
    }

    function handleCustomDepositAmount(val) {
      const amt = parseInt(val) || 0;
      if (amt >= 0) {
        currentDepositAmount = amt;
        document.querySelectorAll(".btn-preset-amt").forEach(btn => {
          btn.style.background = "#131d2e";
          btn.style.border = "1px solid #1e293b";
        });
        const activeBtn = document.getElementById("preset_" + amt);
        if (activeBtn) {
          activeBtn.style.background = "#10b981";
          activeBtn.style.border = "1px solid #10b981";
        }
        prepareDeposit(amt, false);
      }
    }

    function prepareDeposit(amount = 200000, regenCode = true) {
      const pay = typeof getPaymentSettings === "function" ? getPaymentSettings() : {
        bankCode: "MB",
        bankName: "MB Bank",
        accountNumber: "0968033451",
        accountOwner: "NGUYEN MANH DONG",
        depositPrefix: "MMO"
      };

      if (regenCode || !depositOrderCode) {
        depositOrderCode = "DH" + Math.floor(1000000000 + Math.random() * 9000000000);
      }

      currentDepositAmount = amount;

      const orderBadge = document.getElementById("depositOrderCodeBadge");
      const memoText = document.getElementById("depositMemoText");
      const amountDisp = document.getElementById("depositAmountDisplay");
      const bankNameEl = document.getElementById("depositBankName");
      const bankAccEl = document.getElementById("depositBankAcc");
      const bankOwnerEl = document.getElementById("depositBankOwner");
      const qrImgEl = document.getElementById("depositQrImg");

      if (orderBadge) orderBadge.innerText = depositOrderCode;
      if (memoText) memoText.innerText = depositOrderCode;
      if (amountDisp) amountDisp.innerText = formatVND(amount);

      // Đồng bộ ô nhập và nút chọn nhanh với số tiền
      const customInp = document.getElementById("depositCustomAmountInput");
      if (customInp) customInp.value = amount;
      document.querySelectorAll(".btn-preset-amt").forEach(btn => {
        btn.style.background = "#131d2e";
        btn.style.border = "1px solid #1e293b";
      });
      const curActiveBtn = document.getElementById("preset_" + amount);
      if (curActiveBtn) {
        curActiveBtn.style.background = "#10b981";
        curActiveBtn.style.border = "1px solid #10b981";
      }
      if (bankNameEl) bankNameEl.innerText = pay.bankName || "MB Bank";
      if (bankAccEl) bankAccEl.innerText = pay.accountNumber || "0968033451";
      if (bankOwnerEl) bankOwnerEl.innerText = pay.accountOwner || "NGUYEN MANH DONG";

      const bankCode = (pay.bankCode || "MB").toUpperCase();
      const bankAcc = pay.accountNumber || "0968033451";
      const bankOwner = encodeURIComponent(pay.accountOwner || "NGUYEN MANH DONG");
      const memo = encodeURIComponent(depositOrderCode);

      const qrUrl = `https://img.vietqr.io/image/${bankCode}-${bankAcc}-compact.png?amount=${amount}&addInfo=${memo}&accountName=${bankOwner}`;
      if (qrImgEl) qrImgEl.src = qrUrl;

      // Register deposit order with Google Apps Script Cloud Backend
      if (currentUser && currentUser.email) {
        callGasApi("createDepositOrder", {
          orderId: depositOrderCode,
          amount: amount,
          email: currentUser.email
        }).catch(() => {});
      }

      startDepositWatcher();
    }

        var depositPollingTimer = null;

    function startDepositWatcher() {
      if (depositPollingTimer) {
        clearInterval(depositPollingTimer);
        depositPollingTimer = null;
      }
      depositPollingTimer = setInterval(checkDepositStatus, 2000);
    }

        async function handleManualDepositCheck() {
      if (depositPollingTimer) {
        clearInterval(depositPollingTimer);
        depositPollingTimer = null;
      }

      showToast("⏳ Đang kiểm tra giao dịch nạp tiền...", "info");

      // Gọi đối soát đơn nạp với máy chủ
      const currentCode = (depositOrderCode || "").toUpperCase();
      if (currentCode && typeof callGasApi === "function") {
        try {
          await callGasApi("checkOrder", { orderId: currentCode });
        } catch(e) {}
      }

      showToast("🎉 Đang mở trang Ví để hiển thị số dư...", "success");

      // Chuyển view sang tab Ví
      switchView("viewProfile");
      switchProfileTab("tabProfWallet");

      // Tải số dư & lịch sử mới nhất từ máy chủ
      if (typeof loadUserWalletFromCloud === "function") {
        await loadUserWalletFromCloud();
      }
    }

    async function checkDepositStatus() {
      const depositView = document.getElementById("viewDeposit");
      if (!depositView || depositView.style.display === "none") {
        if (depositPollingTimer) {
          clearInterval(depositPollingTimer);
          depositPollingTimer = null;
        }
        return;
      }

      const currentCode = (depositOrderCode || "").toUpperCase();
      if (!currentCode) return;

      let paymentDetected = false;
      let detectedAmount = currentDepositAmount || 20000;

      // 1. Quét từ checkOrder
      try {
        const orderData = await callGasApi("checkOrder", { orderId: currentCode });
        if (orderData && (orderData.status === "COMPLETED" || orderData.status === "PAID")) {
          paymentDetected = true;
          detectedAmount = Number(orderData.totalAmount) || detectedAmount;
        }
      } catch(e) {}

      // 2. Quét từ Cloud getUserOrders
      if (!paymentDetected && currentUser && currentUser.email) {
        try {
          const ordersRes = await callGasApi("getUserOrders", { email: currentUser.email });
          if (ordersRes && Array.isArray(ordersRes.orders)) {
            const matched = ordersRes.orders.find(o => String(o.orderId).trim().toUpperCase() === currentCode && (o.status === "COMPLETED" || o.status === "PAID"));
            if (matched) {
              paymentDetected = true;
              detectedAmount = Number(matched.totalAmount) || detectedAmount;
            }
          }
        } catch(e) {}
      }

      // XỬ LÝ KHI PHÁT HIỆN THANH TOÁN THÀNH CÔNG ĐÚNG MÃ ĐƠN NẠP NÀY
      if (paymentDetected) {
        if (depositPollingTimer) {
          clearInterval(depositPollingTimer);
          depositPollingTimer = null;
        }

        if (currentUser && currentUser.email) {
          const cleanEmail = (currentUser.email || "").toLowerCase().trim();
          let creditedTxs = {};
          try {
            creditedTxs = JSON.parse(localStorage.getItem("mmo_credited_txs_" + cleanEmail) || "{}");
          } catch(e) {}

          if (!creditedTxs[currentCode]) {
            creditedTxs[currentCode] = true;
            localStorage.setItem("mmo_credited_txs_" + cleanEmail, JSON.stringify(creditedTxs));
            currentUser.balance = (Number(currentUser.balance) || 0) + detectedAmount;
            localStorage.setItem("mmo_user", JSON.stringify(currentUser));

            let allUsers = getRegisteredUsers();
            const uIdx = allUsers.findIndex(u => (u.email || "").toLowerCase().trim() === cleanEmail);
            if (uIdx !== -1) {
              allUsers[uIdx].balance = currentUser.balance;
              saveRegisteredUsers(allUsers);
            }
            updateUserUI();
          }
        }

        showToast("🎉 Nạp tiền tự động thành công! Đã cộng +" + formatVND(detectedAmount) + " vào ví.", "success");
        if (typeof addUserNotification === "function") {
          addUserNotification({
            title: "💰 Nạp tiền thành công +" + formatVND(detectedAmount),
            message: "Hệ thống đã tự động cộng +" + formatVND(detectedAmount) + " vào số dư ví của bạn.",
            type: "DEPOSIT",
            email: currentUser && currentUser.email ? currentUser.email : "",
            playSound: true
          });
        } else if (typeof playNotificationSound === "function") {
          playNotificationSound();
        }
        
        // CHUYỂN NGAY LẬP TỨC SANG TRANG VÍ
        switchView("viewProfile");
        switchProfileTab("tabProfWallet");
        if (typeof loadUserWalletFromCloud === "function") {
          loadUserWalletFromCloud();
        }
      }
    }

    let cachedCloudWalletHistory = [];

    var _lastWalletCloudFetchTime = 0;
    var _isLoadingWalletFromCloud = false;

    async function loadUserWalletFromCloud(force = false) {
      if (!currentUser || !currentUser.email) return;
      const now = Date.now();
      if (!force && (now - _lastWalletCloudFetchTime < 15000 || _isLoadingWalletFromCloud)) return;
      _isLoadingWalletFromCloud = true;
      _lastWalletCloudFetchTime = now;
      const cleanEmail = (currentUser.email || "").toLowerCase().trim();

      try {
        // 1. Quét từ Cloud getUserWallet để lấy số dư thực tế và lịch sử nạp tiền
        const walletRes = await callGasApi("getUserWallet", { email: cleanEmail });
        if (walletRes && walletRes.wallet) {
          const cloudBal = Number(walletRes.wallet.balance);
          if (!isNaN(cloudBal)) {
            let allUsers = getRegisteredUsers();
            const uIdx = allUsers.findIndex(u => (u.email || "").toLowerCase().trim() === cleanEmail);
            const localBal = (uIdx !== -1 && allUsers[uIdx].balance !== undefined) ? Number(allUsers[uIdx].balance) : 0;

            const lastChangeTime = Number(localStorage.getItem("mmo_last_balance_change_time") || 0);
            const isRecentLocalChange = (Date.now() - lastChangeTime) < 60000;

            let compBal = localBal;
            if (typeof getUserComprehensiveTransactions === "function") {
              const comp = getUserComprehensiveTransactions(cleanEmail);
              if (comp && comp.currentBalance !== undefined && !isNaN(Number(comp.currentBalance))) {
                compBal = Number(comp.currentBalance);
              }
            }

            let finalBal = Math.max(localBal, compBal);
            if (cloudBal > finalBal) {
              finalBal = cloudBal;
            } else if (finalBal > cloudBal && typeof callGasApi === "function") {
              callGasApi("adminUpdateBalance", {
                adminEmail: cleanEmail,
                targetEmail: cleanEmail,
                amount: (finalBal - cloudBal),
                reason: "Đồng bộ số dư ví tự động"
              }).catch(() => {});
            }

            if (currentUser.balance !== finalBal) {
              currentUser.balance = finalBal;
              localStorage.setItem("mmo_user", JSON.stringify(currentUser));
            }

            if (uIdx !== -1 && allUsers[uIdx].balance !== finalBal) {
              allUsers[uIdx].balance = finalBal;
              saveRegisteredUsers(allUsers);
            }
            updateUserUI();
          }

          if (Array.isArray(walletRes.wallet.history)) {
            cachedCloudWalletHistory = walletRes.wallet.history;
          }
        }

        // 2. Quét từ Cloud getUserOrders để bổ sung các lần nạp tiền NAP_VI vào lịch sử
        const ordersRes = await callGasApi("getUserOrders", { email: cleanEmail });
        if (ordersRes && Array.isArray(ordersRes.orders)) {
          ordersRes.orders.forEach(o => {
            const isDeposit = o.prodId === "NAP_VI" || String(o.orderId).startsWith("NAP");
            if (isDeposit && (o.status === "COMPLETED" || o.status === "PAID")) {
              const alreadyExists = cachedCloudWalletHistory.some(h => h.id === o.orderId || (h.content && h.content.includes(o.orderId)));
              if (!alreadyExists) {
                cachedCloudWalletHistory.push({
                  id: o.orderId,
                  time: o.createdAt || new Date().toLocaleDateString("vi-VN"),
                  type: "Nạp tiền VietQR / SePay",
                  amount: Number(o.totalAmount) || 20000,
                  status: "Thành công",
                  content: o.prodName || ("Nạp tiền ví " + o.orderId),
                  bank: "MBBank",
                  note: o.accounts || "Đã cộng tiền tự động vào ví"
                });
              }
            }
          });
        }

        renderUserWalletTransactions();
        renderUserBalanceLogs();
      } catch(e) {
        renderUserWalletTransactions();
        renderUserBalanceLogs();
      } finally {
        _isLoadingWalletFromCloud = false;
      }
    }

    // SubTab 1: LỊCH SỬ NẠP / RÚT TIỀN (Chỉ hiển thị nạp tiền, rút tiền và hoàn tiền)
    function renderUserWalletTransactions() {
      const tbody = document.getElementById("profDepositHistoryTableBody");
      if (!tbody) return;

      if (!currentUser) {
        try {
          const storedUser = localStorage.getItem("mmo_user");
          if (storedUser) currentUser = JSON.parse(storedUser);
        } catch(e) {}
      }

      const cleanEmail = currentUser ? (currentUser.email || "").toLowerCase().trim() : "";
      if (!cleanEmail) {
        tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:28px; color:#64748b;">Vui lòng đăng nhập để xem lịch sử nạp / rút tiền.</td></tr>';
        return;
      }

      let allHistory = [];
      if (typeof getUserComprehensiveTransactions === "function") {
        const res = getUserComprehensiveTransactions(cleanEmail);
        const rawTxs = res.transactions || [];
        allHistory = rawTxs.filter(tx => {
          const t = String(tx.type || "").toLowerCase();
          const n = String(tx.note || "").toLowerCase();
          const amt = Number(tx.amount) || 0;
          return t.includes("nạp") || t.includes("rút") || t.includes("hoàn tiền") || t.includes("thủ công") || n.includes("hoàn tiền") || amt > 0;
        });
      } else {
        const localHistory = typeof getTransactionHistory === "function" ? getTransactionHistory() : [];
        allHistory = localHistory.filter(tx => {
          if ((tx.userEmail || "").toLowerCase().trim() !== cleanEmail) return false;
          const t = (tx.type || "").toLowerCase();
          return t.includes("nạp") || t.includes("rút") || t.includes("cộng/trừ") || t.includes("hoàn tiền") || Number(tx.amount) > 0;
        });
      }

      if (allHistory.length === 0) {
        tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:28px; color:#64748b;">Chưa có lịch sử nạp / rút tiền nào.</td></tr>';
        return;
      }

      function parseVietnamDateTime(str) {
        if (!str) return 0;
        if (typeof str === "number") return str;
        str = String(str).trim();
        const tokens = str.split(/\s+/);
        let dPart = "", tPart = "00:00:00";
        for (let t of tokens) {
          if (t.includes("/")) dPart = t;
          else if (t.includes(":")) tPart = t;
        }
        if (dPart) {
          const dp = dPart.split("/");
          if (dp.length === 3) {
            const d = parseInt(dp[0], 10);
            const m = parseInt(dp[1], 10) - 1;
            const y = parseInt(dp[2], 10);
            const tp = tPart.split(":");
            const h = parseInt(tp[0] || "0", 10);
            const min = parseInt(tp[1] || "0", 10);
            const s = parseInt(tp[2] || "0", 10);
            const res = new Date(y, m, d, h, min, s).getTime();
            if (!isNaN(res)) return res;
          }
        }
        const parsed = new Date(str).getTime();
        return isNaN(parsed) ? 0 : parsed;
      }

      allHistory.sort((a, b) => parseVietnamDateTime(b.time || b.date) - parseVietnamDateTime(a.time || a.date));

      tbody.innerHTML = allHistory.map(tx => {
        const amt = Number(tx.amount) || 0;
        const isPlus = amt > 0;
        const amtHtml = isPlus 
          ? '<span style="color:#10b981; font-weight:800;">+' + formatVND(amt) + '</span>' 
          : '<span style="color:#ef4444; font-weight:800;">' + formatVND(amt) + '</span>';
        
        const tLow = (tx.type || "").toLowerCase();
        const isWithdraw = tLow.includes("rút") || tLow.includes("trừ");
        const isAdminTopup = tLow.includes("thủ công") || (tx.id && String(tx.id).includes("ADMIN_TOPUP")) || (tx.content && String(tx.content).includes("ADMIN_TOPUP"));
        const isRefund = tLow.includes("hoàn tiền");

        let typeBadge = '<span class="badge-verified" style="font-size:0.72rem; white-space:nowrap; display:inline-flex; align-items:center;">' + escapeHtml(tx.type || 'Nạp tiền VietQR') + '</span>';
        if (isWithdraw) {
          typeBadge = '<span class="badge-trust" style="font-size:0.72rem; background:rgba(239,68,68,0.15); color:#ef4444; white-space:nowrap; display:inline-flex; align-items:center;">' + escapeHtml(tx.type || 'Rút tiền') + '</span>';
        } else if (isRefund) {
          typeBadge = '<span class="badge-trust" style="font-size:0.72rem; background:rgba(16,185,129,0.2); color:#10b981; border:1px solid rgba(16,185,129,0.4); white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-rotate-left"></i> Hoàn tiền bảo hành</span>';
        } else if (isAdminTopup) {
          typeBadge = '<span class="badge-trust" style="font-size:0.72rem; background:rgba(16,185,129,0.2); color:#10b981; border:1px solid rgba(16,185,129,0.4); white-space:nowrap; display:inline-flex; align-items:center;">Nạp thủ công Admin</span>';
        }

        return '<tr>' +
          '<td style="font-size:0.78rem; color:#94a3b8; white-space:nowrap;">' + (tx.time || tx.date || '') + '</td>' +
          '<td style="white-space:nowrap;">' + typeBadge + '</td>' +
          '<td style="white-space:nowrap;">' + amtHtml + '</td>' +
          '<td style="white-space:nowrap;"><span class="badge-trust" style="font-size:0.7rem; background:rgba(16,185,129,0.15); color:#10b981; white-space:nowrap; display:inline-flex; align-items:center;">' + escapeHtml(tx.status || 'Thành công') + '</span></td>' +
          '<td style="font-size:0.78rem; color:#cbd5e1; white-space:nowrap;">' + escapeHtml(tx.note || tx.content || '') + '</td>' +
        '</tr>';
      }).join("");
    }

    // SubTab 2: BIẾN ĐỘNG SỐ DƯ (Hiển thị đầy đủ 5 cột: Thời gian | Giao dịch | Số tiền | Số dư sau | Ghi chú)
    function renderUserBalanceLogs() {
      const tbody = document.getElementById("profBalanceLogsTableBody");
      if (!tbody) return;

      if (!currentUser) {
        try {
          const storedUser = localStorage.getItem("mmo_user");
          if (storedUser) currentUser = JSON.parse(storedUser);
        } catch(e) {}
      }

      const cleanEmail = currentUser ? (currentUser.email || "").toLowerCase().trim() : "";
      if (!cleanEmail) {
        tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:28px; color:#64748b;">Vui lòng đăng nhập để xem biến động số dư.</td></tr>';
        return;
      }

      if (typeof getUserComprehensiveTransactions === "function") {
        const res = getUserComprehensiveTransactions(cleanEmail);
        const allLogs = res.transactions;

        if (allLogs.length === 0) {
          tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:28px; color:#64748b;">Chưa có biến động số dư nào.</td></tr>';
          return;
        }

        tbody.innerHTML = allLogs.map(tx => {
          const amt = Number(tx.amount) || 0;
          const isPlus = amt > 0;
          const amtHtml = isPlus 
            ? '<span style="color:#10b981; font-weight:800;">+' + formatVND(amt) + '</span>' 
            : '<span style="color:#ef4444; font-weight:800;">' + formatVND(amt) + '</span>';

          let balAfterStr = (tx.balanceAfter !== null && tx.balanceAfter !== undefined && !isNaN(Number(tx.balanceAfter))) ? formatVND(Math.max(0, tx.balanceAfter)) : "-";

          const tLow = String(tx.type || "").toLowerCase();
          const nLow = String(tx.note || "").toLowerCase();
          const isRefund = tLow.includes("hoàn tiền") || nLow.includes("hoàn tiền");
          const isPurchase = tLow.includes("thanh toán") || tLow.includes("mua hàng") || amt < 0;

          let typeHtml = "";
          if (isRefund) {
            typeHtml = '<span style="color:#10b981; font-weight:700; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-hand-holding-dollar"></i> Hoàn tiền đơn hàng bảo hành</span>';
          } else if (isPurchase) {
            typeHtml = '<span style="color:#f87171; font-weight:700; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-cart-shopping"></i> Thanh toán mua hàng</span>';
          } else if (tLow.includes("rút")) {
            typeHtml = '<span style="color:#fbbf24; font-weight:700; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-arrow-up-right-from-square"></i> Rút tiền</span>';
          } else if (tLow.includes("thủ công") || nLow.includes("thủ công")) {
            typeHtml = '<span style="color:#38bdf8; font-weight:700; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-user-shield"></i> Nạp tiền ví</span>';
          } else {
            typeHtml = '<span style="color:#38bdf8; font-weight:700; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-wallet"></i> Nạp tiền ví</span>';
          }

          let displayNote = tx.note || "";
          if (isRefund && (!displayNote || displayNote.includes("NAP ") || displayNote.includes("SePay"))) {
            displayNote = "Hoàn tiền đơn hàng bảo hành mã đơn #" + (tx.orderId || "");
          }

          return '<tr>' +
            '<td style="font-size:0.78rem; color:#94a3b8; white-space:nowrap;">' + (tx.time || tx.date || '') + '</td>' +
            '<td style="white-space:nowrap;">' + typeHtml + '</td>' +
            '<td style="white-space:nowrap;">' + amtHtml + '</td>' +
            '<td style="font-size:0.85rem; font-weight:700; color:#38bdf8; font-family:monospace; white-space:nowrap;">' + balAfterStr + '</td>' +
            '<td style="font-size:0.78rem; color:#cbd5e1; white-space:nowrap;">' + escapeHtml(displayNote) + '</td>' +
          '</tr>';
        }).join("");
        return;
      }

      const rawLogs = [];

      // A. Lấy từ mmo_transaction_history (hệ thống giao dịch chuẩn)
      try {
        const localHistory = typeof getTransactionHistory === "function" ? getTransactionHistory() : [];
        localHistory.forEach(tx => {
          if ((tx.userEmail || "").toLowerCase().trim() === cleanEmail) {
            rawLogs.push({
              id: tx.id || tx.txId,
              orderId: tx.orderId || "",
              time: tx.time || tx.date,
              type: tx.type || "Giao dịch ví",
              amount: Number(tx.amount) || 0,
              balanceAfter: (tx.balanceAfter !== undefined && tx.balanceAfter !== null) ? tx.balanceAfter : null,
              note: tx.note || ""
            });
          }
        });
      } catch(e) {}

      // B. Quét từ mmo_transactions & mmo_wallet_transactions
      try {
        const extraTxs = JSON.parse(localStorage.getItem("mmo_transactions") || "[]");
        extraTxs.forEach(etx => {
          if ((etx.userEmail || "").toLowerCase().trim() === cleanEmail) {
            rawLogs.push({
              id: etx.id || etx.txId,
              orderId: etx.orderId || "",
              time: etx.time || etx.date,
              type: etx.type || "Giao dịch ví",
              amount: Number(etx.amount) || 0,
              balanceAfter: (etx.balanceAfter !== undefined && etx.balanceAfter !== null) ? etx.balanceAfter : null,
              note: etx.note || etx.content || ""
            });
          }
        });
      } catch(e) {}

      // C. Quét toàn bộ đơn hàng (Cả đơn mua hàng và đơn hoàn tiền)
      try {
        const uOrders = typeof getUserOrders === "function" ? getUserOrders() : [];
        const aOrders = typeof getAllOrders === "function" ? getAllOrders() : [];
        const combinedOrders = [...uOrders];
        aOrders.forEach(ao => {
          if (!combinedOrders.some(co => (co.orderId === ao.orderId || co.id === ao.id))) {
            combinedOrders.push(ao);
          }
        });

        combinedOrders.forEach(o => {
          const ordEmail = (o.email || o.userEmail || "").toLowerCase().trim();
          if (ordEmail === cleanEmail) {
            const oId = String(o.orderId || o.id || "").trim();
            const pName = o.productName || o.prodName || "Sản phẩm";
            const vName = (o.variantName && o.variantName !== "Mặc định") ? (" (" + o.variantName + ")") : "";
            const ordAmt = Number(o.total || o.totalCost || o.totalPrice || o.totalAmount) || 0;
            const ordTime = o.date || (o.createdAt ? new Date(o.createdAt).toLocaleString("vi-VN") : "") || "";

            // 1. Đơn mua hàng (trừ tiền)
            if (ordAmt > 0) {
              rawLogs.push({
                id: "ORD_" + oId,
                orderId: oId,
                time: ordTime,
                type: "Thanh toán mua hàng",
                amount: -ordAmt,
                balanceAfter: o.balanceAfter !== undefined ? o.balanceAfter : null,
                note: "Mua SP: " + pName + vName + " - Đơn #" + oId
              });
            }

            // 2. Đơn được hoàn tiền bảo hành (cộng tiền)
            const st = String(o.status || "").toLowerCase();
            const isRefunded = o.refundedAt || o.refundAmount || st.includes("hoàn tiền") || st.includes("refund");
            if (isRefunded) {
              const refAmt = Number(o.refundAmount) || ordAmt || 15000;
              const refTime = o.refundedAt || ordTime;
              rawLogs.push({
                id: "REFUND_" + oId,
                orderId: oId,
                time: refTime,
                type: "Hoàn tiền đơn hàng bảo hành",
                amount: +refAmt,
                balanceAfter: o.refundBalanceAfter !== undefined ? o.refundBalanceAfter : null,
                note: "Hoàn tiền đơn hàng bảo hành mã đơn #" + oId + " - " + pName
              });
            }
          }
        });
      } catch(e) {}

      // D. Gộp từ Cloud SePay / VietQR (cachedCloudWalletHistory)
      if (Array.isArray(cachedCloudWalletHistory)) {
        cachedCloudWalletHistory.forEach(ch => {
          rawLogs.push({
            id: ch.id,
            orderId: ch.id,
            time: ch.time || ch.date,
            type: ch.type || "Nạp tiền VietQR / SePay",
            amount: Number(ch.amount) || 0,
            balanceAfter: null,
            note: ch.note || ch.content || "Nạp tiền tự động qua QR"
          });
        });
      }

      // E. Lọc trùng thông minh theo mã giao dịch và loại
      const seenMap = new Map();
      rawLogs.forEach(item => {
        const amt = Number(item.amount) || 0;
        const oId = String(item.orderId || item.id || "").replace(/^REFUND_|^ORD_/, "").trim();
        const isRef = amt > 0 && (String(item.type).toLowerCase().includes("hoàn tiền") || String(item.note).toLowerCase().includes("hoàn tiền"));
        const isPurchase = amt < 0;

        let key = "";
        if (oId && isRef) {
          key = "REFUND_" + oId;
        } else if (oId && isPurchase) {
          key = "PURCHASE_" + oId;
        } else if (item.id) {
          key = "ID_" + item.id;
        } else {
          key = "TIME_" + (item.time || "") + "_" + amt;
        }

        if (!seenMap.has(key)) {
          seenMap.set(key, item);
        } else {
          const existing = seenMap.get(key);
          if (!existing.balanceAfter && item.balanceAfter) {
            seenMap.set(key, item);
          }
        }
      });

      const allLogs = Array.from(seenMap.values());

      if (allLogs.length === 0) {
        tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:28px; color:#64748b;">Chưa có biến động số dư nào.</td></tr>';
        return;
      }

      // F. Sắp xếp theo thời gian mới nhất lên đầu danh sách
      function parseVietnamDateTime(str) {
        if (!str) return 0;
        if (typeof str === "number") return str;
        str = String(str).trim();
        
        const tokens = str.split(/\s+/);
        let dPart = "", tPart = "00:00:00";
        for (let t of tokens) {
          if (t.includes("/")) dPart = t;
          else if (t.includes(":")) tPart = t;
        }

        if (dPart) {
          const dp = dPart.split("/");
          if (dp.length === 3) {
            const d = parseInt(dp[0], 10);
            const m = parseInt(dp[1], 10) - 1;
            const y = parseInt(dp[2], 10);
            const tp = tPart.split(":");
            const h = parseInt(tp[0] || "0", 10);
            const min = parseInt(tp[1] || "0", 10);
            const s = parseInt(tp[2] || "0", 10);
            const res = new Date(y, m, d, h, min, s).getTime();
            if (!isNaN(res)) return res;
          }
        }

        const parsed = new Date(str).getTime();
        return isNaN(parsed) ? 0 : parsed;
      }

      allLogs.sort((a, b) => parseVietnamDateTime(b.time || b.date) - parseVietnamDateTime(a.time || a.date));

      // G. Tính toán số dư sau chuẩn xác theo chuỗi thời gian
      const curBal = currentUser && currentUser.balance !== undefined ? Number(currentUser.balance) : 0;
      let runningBal = curBal;

      tbody.innerHTML = allLogs.map((tx, idx) => {
        const amt = Number(tx.amount) || 0;
        const isPlus = amt > 0;
        const amtHtml = isPlus 
          ? '<span style="color:#10b981; font-weight:800;">+' + formatVND(amt) + '</span>' 
          : '<span style="color:#ef4444; font-weight:800;">' + formatVND(amt) + '</span>';
        
        let rowBal = null;
        if (idx === 0) {
          rowBal = (tx.balanceAfter !== null && tx.balanceAfter !== undefined && tx.balanceAfter !== "") ? Number(tx.balanceAfter) : curBal;
          runningBal = rowBal;
        } else {
          const prevTx = allLogs[idx - 1];
          const prevAmt = Number(prevTx.amount) || 0;
          runningBal = runningBal - prevAmt;
          rowBal = (tx.balanceAfter !== null && tx.balanceAfter !== undefined && tx.balanceAfter !== "") ? Number(tx.balanceAfter) : runningBal;
        }

        let balAfterStr = (rowBal !== null && !isNaN(rowBal)) ? formatVND(Math.max(0, rowBal)) : "-";

        const tLow = String(tx.type || "").toLowerCase();
        const nLow = String(tx.note || "").toLowerCase();
        const isRefund = tLow.includes("hoàn tiền") || nLow.includes("hoàn tiền");
        const isPurchase = tLow.includes("thanh toán") || tLow.includes("mua hàng") || amt < 0;

        let typeHtml = "";
        if (isRefund) {
          typeHtml = '<span style="color:#10b981; font-weight:700; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-hand-holding-dollar"></i> Hoàn tiền đơn hàng bảo hành</span>';
        } else if (isPurchase) {
          typeHtml = '<span style="color:#f87171; font-weight:700; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-cart-shopping"></i> Thanh toán mua hàng</span>';
        } else if (tLow.includes("rút")) {
          typeHtml = '<span style="color:#fbbf24; font-weight:700; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-arrow-up-right-from-square"></i> Rút tiền</span>';
        } else {
          typeHtml = '<span style="color:#38bdf8; font-weight:700; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-wallet"></i> Nạp tiền ví</span>';
        }

        let displayNote = tx.note || "";
        if (isRefund && (!displayNote || displayNote.includes("NAP ") || displayNote.includes("SePay"))) {
          displayNote = "Hoàn tiền đơn hàng bảo hành mã đơn #" + (tx.orderId || "");
        }

        return '<tr>' +
          '<td style="font-size:0.78rem; color:#94a3b8; white-space:nowrap;">' + (tx.time || tx.date || '') + '</td>' +
          '<td style="white-space:nowrap;">' + typeHtml + '</td>' +
          '<td style="white-space:nowrap;">' + amtHtml + '</td>' +
          '<td style="font-size:0.85rem; font-weight:700; color:#38bdf8; font-family:monospace; white-space:nowrap;">' + balAfterStr + '</td>' +
          '<td style="font-size:0.78rem; color:#cbd5e1; white-space:nowrap;">' + escapeHtml(displayNote) + '</td>' +
        '</tr>';
      }).join("");
    }
    function handleProfileWithdraw() {
      showToast("Chức năng Rút Tiền: Số dư tối thiểu 50.000 đ. Vui lòng cập nhật Tài Khoản Ngân Hàng để rút.", "info");
      switchProfileTab("tabProfBank");
    }

    function populateProfileInfoInputs() {
      if (!currentUser) return;
      const inpName = document.getElementById("profInputName");
      const inpEmail = document.getElementById("profInputEmail");
      const inpPhone = document.getElementById("profInputPhone");
      if (inpName) inpName.value = currentUser.name || "";
      if (inpEmail) inpEmail.value = currentUser.email || "";
      if (inpPhone) inpPhone.value = currentUser.phone || "";
    }

    function saveProfileInfo() {
      if (!currentUser) return;
      const inpName = document.getElementById("profInputName")?.value.trim();
      const inpPhone = document.getElementById("profInputPhone")?.value.trim();
      if (inpName) currentUser.name = inpName;
      if (inpPhone) currentUser.phone = inpPhone;
      localStorage.setItem("mmo_user", JSON.stringify(currentUser));
      updateUserUI();
      showToast("Đã lưu thông tin cá nhân thành công!", "success");
    }

    function saveProfileBankInfo() {
      const bName = document.getElementById("profBankName")?.value.trim();
      const bAcc = document.getElementById("profBankAcc")?.value.trim();
      const bOwner = document.getElementById("profBankOwner")?.value.trim();
      if (!bName || !bAcc || !bOwner) {
        showToast("Vui lòng điền đầy đủ thông tin ngân hàng!", "warning");
        return;
      }
      localStorage.setItem("mmo_user_bank", JSON.stringify({ bankName: bName, bankAcc: bAcc, bankOwner: bOwner }));
      showToast("Đã lưu tài khoản ngân hàng nhận tiền thành công!", "success");
    }


    // ==================== WITHDRAWAL REQUEST & PLATFORM FINANCE SYSTEM ====================
    const DEFAULT_WITHDRAW_REQUESTS = [];

    function getWithdrawRequests() {
      try {
        const stored = localStorage.getItem("mmo_withdraw_requests");
        let list = stored ? JSON.parse(stored) : [];
        if (!Array.isArray(list)) list = [];
        // Lọc bỏ yêu cầu rút demo hoặc dữ liệu mẫu nếu có, chỉ giữ dữ liệu thực tế
        list = list.filter(w => {
          if (!w) return false;
          const em = String(w.userEmail || "").toLowerCase().trim();
          const nm = String(w.userName || "").toLowerCase().trim();
          const id = String(w.id || "").toLowerCase().trim();
          if (em.includes("demo") || em.includes("sample") || em === "test@gmail.com") return false;
          if (nm.includes("demo") || nm.includes("mẫu")) return false;
          if (id.includes("demo") || id.includes("sample")) return false;
          return true;
        });
        return list;
      } catch(e) {
        return [];
      }
    }
    window.getWithdrawRequests = getWithdrawRequests;

    function saveWithdrawRequests(list) {
      localStorage.setItem("mmo_withdraw_requests", JSON.stringify(list));
    }
    window.saveWithdrawRequests = saveWithdrawRequests;

    // Helper: Lấy danh sách giao dịch nạp tiền thành công toàn sàn (Dữ liệu thực tế 100%, không demo)
    function getPlatformDeposits() {
      const depositList = [];
      const seenDepositIds = new Set();

      // 1. From localStorage 'mmo_deposits'
      try {
        const raw = localStorage.getItem("mmo_deposits");
        if (raw) {
          const parsed = JSON.parse(raw);
          if (Array.isArray(parsed)) {
            parsed.forEach(d => {
              if (!d) return;
              const st = String(d.status || "").toLowerCase();
              if (st.includes("thành công") || st.includes("success") || st.includes("completed") || st.includes("paid") || !st) {
                const cleanId = String(d.id || d.orderId || d.code || "").trim();
                if (cleanId && !seenDepositIds.has(cleanId)) {
                  seenDepositIds.add(cleanId);
                  depositList.push(d);
                }
              }
            });
          }
        }
      } catch(e) {}

      // 2. From cachedCloudWalletHistory (VietQR / SePay cloud)
      if (typeof cachedCloudWalletHistory !== "undefined" && Array.isArray(cachedCloudWalletHistory)) {
        cachedCloudWalletHistory.forEach(ch => {
          if (!ch) return;
          const t = String(ch.type || "").toLowerCase();
          const st = String(ch.status || "").toLowerCase();
          if ((t.includes("nạp") || t.includes("vietqr") || t.includes("sepay")) && (!st || st.includes("thành công") || st.includes("success") || st.includes("completed"))) {
            const cleanId = String(ch.id || ch.orderId || "").trim();
            if (cleanId && !seenDepositIds.has(cleanId)) {
              seenDepositIds.add(cleanId);
              depositList.push({
                id: cleanId,
                orderId: cleanId,
                userEmail: ch.userEmail || ch.email || "khachhang@gmail.com",
                userName: ch.userName || ch.name || "Khách Hàng",
                type: "Nạp tiền VietQR / SePay",
                amount: Number(ch.amount) || 0,
                bankName: ch.bank || "MBBank (VietQR SePay)",
                bankAcc: ch.bankAcc || "0988888888",
                bankOwner: "NGUYEN MANH DONG",
                time: ch.time || ch.date || (new Date().toLocaleDateString("vi-VN")),
                status: "Thành công",
                handledBy: "Tự động SePay 24/7",
                note: ch.note || ch.content || "Nạp tiền tự động qua VietQR"
              });
            }
          }
        });
      }

      // 3. From getTransactionHistory()
      try {
        const txHistory = typeof getTransactionHistory === "function" ? getTransactionHistory() : [];
        txHistory.forEach(tx => {
          if (!tx) return;
          const t = String(tx.type || "").toLowerCase();
          const amt = Number(tx.amount) || 0;
          if (amt > 0 && (t.includes("nạp") || t.includes("sepay") || t.includes("vietqr") || t.includes("cộng tiền") || t.includes("topup"))) {
            const cleanId = String(tx.txId || tx.id || "").trim();
            if (cleanId && !seenDepositIds.has(cleanId)) {
              seenDepositIds.add(cleanId);
              depositList.push({
                id: cleanId,
                orderId: cleanId,
                userEmail: tx.userEmail || "khachhang@gmail.com",
                userName: tx.userName || "Khách Hàng",
                type: tx.type || "Nạp tiền VietQR / SePay",
                amount: amt,
                bankName: "MBBank (VietQR SePay)",
                bankAcc: "0988888888",
                bankOwner: "NGUYEN MANH DONG",
                time: tx.time || tx.date || (new Date().toLocaleDateString("vi-VN")),
                status: "Thành công",
                handledBy: t.includes("admin") ? "Admin" : "Tự động SePay 24/7",
                note: tx.note || "Nạp tiền tự động qua VietQR"
              });
            }
          }
        });
      } catch(e) {}

      // 4. From mmo_balance_logs
      try {
        const rawLogs = localStorage.getItem("mmo_balance_logs");
        if (rawLogs) {
          const logs = JSON.parse(rawLogs);
          if (Array.isArray(logs)) {
            logs.forEach((lg, idx) => {
              const amt = Number(lg.amount || lg.diff || 0);
              const t = String(lg.type || lg.reason || "").toLowerCase();
              if (amt > 0 && (t.includes("nạp") || t.includes("deposit") || t.includes("cộng tiền"))) {
                const cleanId = String(lg.id || ("DEP_LOG_" + idx)).trim();
                if (cleanId && !seenDepositIds.has(cleanId)) {
                  seenDepositIds.add(cleanId);
                  depositList.push({
                    id: cleanId,
                    orderId: cleanId,
                    userEmail: lg.userEmail || lg.email || "khachhang@gmail.com",
                    userName: lg.userName || lg.name || "Khách Hàng",
                    type: "Nạp tiền VietQR / SePay",
                    amount: amt,
                    bankName: "MBBank (VietQR SePay)",
                    bankAcc: "0988888888",
                    bankOwner: "NGUYEN MANH DONG",
                    time: lg.time || lg.date || (new Date().toLocaleDateString("vi-VN")),
                    status: "Thành công",
                    handledBy: "Tự động SePay 24/7",
                    note: lg.reason || lg.description || "Nạp tiền thành công"
                  });
                }
              }
            });
          }
        }
      } catch(e) {}

      return depositList;
    }
    window.getPlatformDeposits = getPlatformDeposits;

    // Helper: Tổng hợp toàn bộ biến động số dư ví toàn sàn
    function getAllPlatformWalletTransactions() {
      const txList = [];
      const seenMap = new Map();

      // 1. Transaction History (mmo_transaction_history)
      try {
        const hist = typeof getTransactionHistory === "function" ? getTransactionHistory() : [];
        hist.forEach(tx => {
          if (!tx) return;
          const tId = String(tx.txId || tx.id || "").trim();
          const amt = Number(tx.amount) || 0;
          const key = (tId || "TX") + "_" + (tx.type || "") + "_" + (tx.userEmail || "") + "_" + amt;
          if (!seenMap.has(key)) {
            seenMap.set(key, true);
            txList.push({
              id: tId || ("TX" + Math.floor(10000000 + Math.random() * 90000000)),
              txId: tId,
              orderId: tx.orderId || "",
              userEmail: tx.userEmail || "khach@gmail.com",
              userName: tx.userName || (tx.userEmail ? tx.userEmail.split("@")[0] : "Khách Hàng"),
              type: tx.type || (amt > 0 ? "Nạp tiền ví" : "Thanh toán mua hàng"),
              amount: amt,
              balanceAfter: tx.balanceAfter !== undefined && tx.balanceAfter !== null ? tx.balanceAfter : null,
              time: tx.time || tx.date || (new Date().toLocaleDateString("vi-VN")),
              note: tx.note || ""
            });
          }
        });
      } catch(e) {}

      // 2. Balance Logs (mmo_balance_logs)
      try {
        const rawLogs = localStorage.getItem("mmo_balance_logs");
        if (rawLogs) {
          const bLogs = JSON.parse(rawLogs);
          if (Array.isArray(bLogs)) {
            bLogs.forEach((lg, idx) => {
              if (!lg) return;
              const amt = Number(lg.amount || lg.diff || 0);
              const lgId = String(lg.id || ("BL_" + idx)).trim();
              const key = lgId + "_" + (lg.type || lg.reason || "") + "_" + (lg.userEmail || "") + "_" + amt;
              if (!seenMap.has(key)) {
                seenMap.set(key, true);
                txList.push({
                  id: lgId,
                  txId: lgId,
                  orderId: lg.orderId || "",
                  userEmail: lg.userEmail || lg.email || "khach@gmail.com",
                  userName: lg.userName || lg.name || "Khách Hàng",
                  type: lg.type || (amt > 0 ? "Cộng tiền ví" : "Trừ tiền ví"),
                  amount: amt,
                  balanceAfter: lg.balanceAfter !== undefined && lg.balanceAfter !== null ? lg.balanceAfter : null,
                  time: lg.time || lg.date || (new Date().toLocaleDateString("vi-VN")),
                  note: lg.reason || lg.description || ""
                });
              }
            });
          }
        }
      } catch(e) {}

      // 3. All Orders from getAllOrders()
      try {
        const orders = typeof getAllOrders === "function" ? getAllOrders() : [];
        orders.forEach(o => {
          if (!o) return;
          const oid = String(o.orderId || o.id || o.orderCode || "").replace("#", "").trim();
          if (!oid) return;
          const amt = Number(o.total || o.totalCost || o.totalPrice || o.totalAmount) || 0;
          const uEmail = (o.email || o.userEmail || o.customerEmail || "khach@gmail.com").toLowerCase().trim();
          const uName = o.buyerName || o.customerName || o.userName || uEmail.split("@")[0];
          const oTime = o.date || o.createdAt || (new Date().toLocaleDateString("vi-VN"));
          const pName = o.productName || o.prodName || "Tài khoản MMO";

          // 3.1. Purchase tx
          if (amt > 0) {
            const pKey = "ORD_" + oid;
            if (!seenMap.has(pKey)) {
              seenMap.set(pKey, true);
              txList.push({
                id: pKey,
                txId: pKey,
                orderId: oid,
                userEmail: uEmail,
                userName: uName,
                type: "Thanh toán mua hàng",
                amount: -amt,
                balanceAfter: o.balanceAfter !== undefined ? o.balanceAfter : null,
                time: oTime,
                note: "Mua SP: " + pName + (o.variantName && o.variantName !== "Mặc định" ? " (" + o.variantName + ")" : "") + " - Đơn #" + oid
              });
            }
          }

          // 3.2. Refund tx if refunded
          const st = String(o.status || "").toLowerCase();
          if (o.isRefunded || o.refundedAt || o.refundAmount || st.includes("hoàn tiền") || st.includes("refund")) {
            const refKey = "REFUND_" + oid;
            const refAmt = Number(o.refundAmount || amt) || 15000;
            if (!seenMap.has(refKey)) {
              seenMap.set(refKey, true);
              txList.push({
                id: refKey,
                txId: refKey,
                orderId: oid,
                userEmail: uEmail,
                userName: uName,
                type: "Hoàn tiền bảo hành & đổi trả",
                amount: +refAmt,
                balanceAfter: o.refundBalanceAfter !== undefined ? o.refundBalanceAfter : null,
                time: o.refundedAt || oTime,
                note: "Hoàn tiền bảo hành đơn #" + oid + " (" + pName + ")"
              });
            }
          }
        });
      } catch(e) {}

      // 4. Pre-Orders from getPreOrders()
      try {
        const preOrders = typeof getPreOrders === "function" ? getPreOrders() : [];
        preOrders.forEach(po => {
          if (!po) return;
          const poid = String(po.orderCode || po.id || po.orderId || "").replace("#", "").trim();
          if (!poid) return;
          const pAmt = Number(po.finalTotal || po.totalCost || po.totalPrice || po.amount) || 0;
          const puEmail = (po.buyerEmail || po.customerEmail || (po.user ? po.user.email : "") || "khach@gmail.com").toLowerCase().trim();
          const puName = po.buyerUsername || po.buyerName || po.customerName || puEmail.split("@")[0];
          const poTime = po.createdAt || po.date || (new Date().toLocaleDateString("vi-VN"));

          if (pAmt > 0) {
            const poKey = "TX_PO_" + poid;
            if (!seenMap.has(poKey)) {
              seenMap.set(poKey, true);
              txList.push({
                id: poKey,
                txId: poKey,
                orderId: poid,
                userEmail: puEmail,
                userName: puName,
                type: "Thanh toán đặt hàng trước",
                amount: -pAmt,
                balanceAfter: po.balanceAfter !== undefined ? po.balanceAfter : null,
                time: poTime,
                note: "Đặt trước " + (po.quantity || 1) + "x " + (po.productName || "Sản phẩm") + " - Đơn #" + poid
              });
            }
          }

          if (po.status === "CANCELLED" || po.isRefunded) {
            const poRefKey = "REFUND_PO_" + poid;
            const refAmt = Number(po.refundAmount || pAmt);
            if (!seenMap.has(poRefKey)) {
              seenMap.set(poRefKey, true);
              txList.push({
                id: poRefKey,
                txId: poRefKey,
                orderId: poid,
                userEmail: puEmail,
                userName: puName,
                type: "Hoàn tiền hủy đơn đặt trước",
                amount: +refAmt,
                balanceAfter: po.refundBalanceAfter !== undefined ? po.refundBalanceAfter : null,
                time: po.refundedAt || po.updatedAt || poTime,
                note: "Hoàn tiền 100% hủy đơn đặt trước #" + poid
              });
            }
          }
        });
      } catch(e) {}

      // 5. Withdraw Requests from getWithdrawRequests()
      try {
        const withdrawals = typeof getWithdrawRequests === "function" ? getWithdrawRequests() : [];
        withdrawals.forEach(w => {
          if (!w) return;
          const wid = String(w.id || "").trim();
          const wAmt = Number(w.amount) || 0;
          const wKey = "WD_" + wid;
          if (!seenMap.has(wKey)) {
            seenMap.set(wKey, true);
            txList.push({
              id: wKey,
              txId: wid,
              orderId: wid,
              userEmail: w.userEmail || "khach@gmail.com",
              userName: w.userName || "Khách Hàng",
              type: "Rút tiền ngân hàng",
              amount: -wAmt,
              balanceAfter: w.status === "Đã từ chối (Hoàn tiền)" ? "Đã hoàn" : "Đã trừ",
              time: w.time || (new Date().toLocaleDateString("vi-VN")),
              note: "Rút tiền về STK: " + (w.bankAcc || "") + " (" + (w.bankName || "") + ") - " + (w.status || "Chờ Duyệt")
            });
          }
        });
      } catch(e) {}

      // 6. Deposits
      try {
        const deps = typeof getPlatformDeposits === "function" ? getPlatformDeposits() : [];
        deps.forEach(d => {
          if (!d) return;
          const did = String(d.id || d.orderId || "").trim();
          const dAmt = Number(d.amount) || 0;
          const dKey = "DEP_" + did;
          if (!seenMap.has(dKey)) {
            seenMap.set(dKey, true);
            txList.push({
              id: dKey,
              txId: did,
              orderId: did,
              userEmail: d.userEmail || "khach@gmail.com",
              userName: d.userName || "Khách Hàng",
              type: d.type || "Nạp tiền VietQR / SePay",
              amount: +dAmt,
              balanceAfter: null,
              time: d.time || (new Date().toLocaleDateString("vi-VN")),
              note: d.note || "Nạp tiền tự động qua VietQR SePay"
            });
          }
        });
      } catch(e) {}

      function parseDateForSort(str) {
        if (!str) return 0;
        if (typeof str === "number") return str;
        const s = String(str).trim();
        const parts = s.split(/\s+/);
        let dPart = "", tPart = "00:00:00";
        for (let p of parts) {
          if (p.includes("/")) dPart = p;
          else if (p.includes(":")) tPart = p;
        }
        if (dPart) {
          const dp = dPart.split("/");
          if (dp.length === 3) {
            const d = parseInt(dp[0], 10);
            const m = parseInt(dp[1], 10) - 1;
            const y = parseInt(dp[2], 10);
            const tp = tPart.split(":");
            const h = parseInt(tp[0] || "0", 10);
            const min = parseInt(tp[1] || "0", 10);
            const sec = parseInt(tp[2] || "0", 10);
            const res = new Date(y, m, d, h, min, sec).getTime();
            if (!isNaN(res)) return res;
          }
        }
        const parsed = new Date(s).getTime();
        return isNaN(parsed) ? 0 : parsed;
      }

      txList.sort((a, b) => parseDateForSort(b.time) - parseDateForSort(a.time));
      return txList;
    }
    window.getAllPlatformWalletTransactions = getAllPlatformWalletTransactions;

    // Bộ lọc & Tìm kiếm cho Tab Nạp & Rút Tiền
    let adminWithdrawActiveFilter = "ALL";
    let adminWithdrawSearchQuery = "";

    function handleFilterAdminWithdraw(filterType) {
      adminWithdrawActiveFilter = filterType || "ALL";
      if (typeof paginationState !== "undefined") paginationState.admWithdraw = 1;
      
      const btns = {
        ALL: { id: "btnWdFilterAll", border: "#38bdf8" },
        DEPOSIT: { id: "btnWdFilterDeposit", border: "#10b981" },
        WITHDRAW: { id: "btnWdFilterWithdraw", border: "#ef4444" },
        PENDING: { id: "btnWdFilterPending", border: "#f59e0b" }
      };
      Object.keys(btns).forEach(k => {
        const item = btns[k];
        const btn = document.getElementById(item.id);
        if (btn) {
          if (k === adminWithdrawActiveFilter) {
            btn.classList.add("active");
            btn.style.background = "#1e293b";
            btn.style.borderColor = item.border;
            btn.style.color = "#ffffff";
            btn.style.fontWeight = "700";
          } else {
            btn.classList.remove("active");
            btn.style.background = "#0f172a";
            btn.style.borderColor = "#1e293b";
            btn.style.color = "#ffffff";
            btn.style.fontWeight = "600";
          }
        }
      });
      renderAdminWithdrawTable();
    }
    window.handleFilterAdminWithdraw = handleFilterAdminWithdraw;

    function handleSearchAdminWithdraw(val) {
      adminWithdrawSearchQuery = (val || "").toLowerCase().trim();
      if (typeof paginationState !== "undefined") paginationState.admWithdraw = 1;
      renderAdminWithdrawTable();
    }
    window.handleSearchAdminWithdraw = handleSearchAdminWithdraw;

    // Helper: Vẽ biểu đồ dòng tiền (Đã gỡ bỏ theo yêu cầu người dùng)
    function renderAdminCashflowChart() {
      return;
    }

    // =========================================================================
    // CORE SYSTEM: RENDER ADMIN WITHDRAW & DEPOSIT FINANCE TABLE
    // =========================================================================
    function renderAdminWithdrawTable() {
      const tbody = document.getElementById("admWithdrawTableBody");
      if (!tbody) return;

      const withdrawList = getWithdrawRequests();
      const deposits = (typeof getPlatformDeposits === "function") ? getPlatformDeposits() : [];

      // 1. Tính toán số liệu tài chính toàn sàn
      const users = (typeof getRegisteredUsers === "function") ? getRegisteredUsers() : [];
      const totalUserBalance = users.reduce((acc, u) => acc + (Number(u.balance) || 0), 0);
      const totalDeposit = deposits.reduce((acc, d) => acc + (Number(d.amount) || 0), 0);
      const totalWithdraw = withdrawList.reduce((acc, w) => acc + (Number(w.amount) || 0), 0);
      const netCashflow = totalDeposit - totalWithdraw;

      // 2. Cập nhật 4 thẻ thống kê
      const elBal = document.getElementById("admStatTotalUserBalance");
      if (elBal) elBal.innerText = formatVND(totalUserBalance);

      const elDep = document.getElementById("admStatTotalDeposit");
      if (elDep) elDep.innerText = "+" + formatVND(totalDeposit);

      const elWd = document.getElementById("admStatTotalWithdraw");
      if (elWd) elWd.innerText = "-" + formatVND(totalWithdraw);

      const elNet = document.getElementById("admStatNetCashflow");
      if (elNet) {
        elNet.innerText = (netCashflow >= 0 ? "+" : "") + formatVND(netCashflow);
        elNet.style.color = netCashflow >= 0 ? "#34d399" : "#ef4444";
      }

      // 3. Kết hợp danh sách nạp tiền thành công và tất cả yêu cầu rút tiền
      const combinedList = [];

      // A. Nạp tiền (CHỈ THÀNH CÔNG)
      deposits.forEach(d => {
        combinedList.push({
          isDeposit: true,
          id: d.id || d.orderId || "DEP",
          userEmail: d.userEmail || d.email || "",
          userName: d.userName || d.name || "Khách Hàng",
          type: d.type || "Nạp tiền VietQR / SePay",
          amount: Number(d.amount) || 0,
          bankInfo: (d.bankAcc ? (d.bankAcc + " - " + (d.bankName || "MBBank")) : "VietQR MBBank SePay"),
          time: d.time || d.date || "",
          status: "Thành công",
          handledBy: d.handledBy || "Tự động SePay 24/7",
          rawWithdrawItem: null
        });
      });

      // B. Rút tiền (TẤT CẢ YÊU CẦU RÚT)
      withdrawList.forEach(w => {
        combinedList.push({
          isDeposit: false,
          id: w.id,
          userEmail: w.userEmail || "",
          userName: w.userName || "Khách Hàng",
          type: "Rút tiền ngân hàng",
          amount: Number(w.amount) || 0,
          bankInfo: (w.bankName || "") + "<br/><span style='font-family:monospace; color:#fff; font-weight:700;'>" + (w.bankAcc || "") + "</span><br/><span style='font-size:0.75rem; color:#94a3b8;'>" + (w.bankOwner || "") + "</span>",
          time: w.time || "",
          status: w.status || "Chờ Duyệt",
          handledBy: w.handledBy || "",
          rawWithdrawItem: w
        });
      });

      // Sắp xếp mới nhất lên đầu
      function parseDateTimeSort(str) {
        if (!str) return 0;
        const s = String(str).trim();
        const parts = s.split(/\s+/);
        let dPart = "", tPart = "00:00:00";
        for (let p of parts) {
          if (p.includes("/")) dPart = p;
          else if (p.includes(":")) tPart = p;
        }
        if (dPart) {
          const dp = dPart.split("/");
          if (dp.length === 3) {
            const d = parseInt(dp[0], 10);
            const m = parseInt(dp[1], 10) - 1;
            const y = parseInt(dp[2], 10);
            const tp = tPart.split(":");
            const h = parseInt(tp[0] || "0", 10);
            const min = parseInt(tp[1] || "0", 10);
            const sec = parseInt(tp[2] || "0", 10);
            const res = new Date(y, m, d, h, min, sec).getTime();
            if (!isNaN(res)) return res;
          }
        }
        const parsed = new Date(s).getTime();
        return isNaN(parsed) ? 0 : parsed;
      }
      combinedList.sort((a, b) => parseDateTimeSort(b.time) - parseDateTimeSort(a.time));

      // Cập nhật huy hiệu bộ lọc
      const badgeAll = document.getElementById("badgeWdAll");
      if (badgeAll) badgeAll.innerText = combinedList.length;

      const badgeDeposit = document.getElementById("badgeWdDeposit");
      if (badgeDeposit) badgeDeposit.innerText = deposits.length;

      const badgeWithdraw = document.getElementById("badgeWdWithdraw");
      if (badgeWithdraw) badgeWithdraw.innerText = withdrawList.length;

      const pendingWdCount = withdrawList.filter(w => w.status === "Chờ Duyệt").length;
      const badgePending = document.getElementById("badgeWdPending");
      if (badgePending) badgePending.innerText = pendingWdCount;

      // 5. Lọc danh sách hiển thị
      let filtered = combinedList;

      if (adminWithdrawActiveFilter === "DEPOSIT") {
        filtered = filtered.filter(item => item.isDeposit);
      } else if (adminWithdrawActiveFilter === "WITHDRAW") {
        filtered = filtered.filter(item => !item.isDeposit);
      } else if (adminWithdrawActiveFilter === "PENDING") {
        filtered = filtered.filter(item => !item.isDeposit && item.status === "Chờ Duyệt");
      }

      if (adminWithdrawSearchQuery) {
        filtered = filtered.filter(item => {
          const idStr = String(item.id || "").toLowerCase();
          const emailStr = String(item.userEmail || "").toLowerCase();
          const nameStr = String(item.userName || "").toLowerCase();
          const bankStr = String(item.bankInfo || "").toLowerCase();
          return idStr.includes(adminWithdrawSearchQuery) || emailStr.includes(adminWithdrawSearchQuery) || nameStr.includes(adminWithdrawSearchQuery) || bankStr.includes(adminWithdrawSearchQuery);
        });
      }

      if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="9" style="text-align:center; padding:28px; color:#64748b;">Không tìm thấy giao dịch nạp / rút tiền nào phù hợp.</td></tr>';
        renderPaginationUI("admWithdrawPagination", 1, 0, "changeAdmWithdrawPage");
        return;
      }

      // Phân trang 10 mục/trang
      const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);
      if (paginationState.admWithdraw > totalPages) paginationState.admWithdraw = totalPages;
      if (paginationState.admWithdraw < 1) paginationState.admWithdraw = 1;

      const startIndex = (paginationState.admWithdraw - 1) * ITEMS_PER_PAGE;
      const pageList = filtered.slice(startIndex, startIndex + ITEMS_PER_PAGE);

      tbody.innerHTML = pageList.map(item => {
        let typeBadge = '';
        let amtHtml = '';
        let statusBadge = '';
        let actionHtml = '';

        if (item.isDeposit) {
          typeBadge = '<span style="display:inline-flex; align-items:center; gap:5px; font-size:0.72rem; font-weight:700; padding:3px 8px; border-radius:6px; background:rgba(16,185,129,0.15); color:#10b981; border:1px solid rgba(16,185,129,0.3); white-space:nowrap;"><i class="fa-solid fa-circle-arrow-down"></i> Nạp tiền</span>';
          amtHtml = '<span style="font-size:0.92rem; font-weight:800; color:#10b981; font-family:monospace; white-space:nowrap;">+' + formatVND(item.amount) + '</span>';
          statusBadge = '<span class="badge-verified" style="font-size:0.72rem; background:rgba(16,185,129,0.2); color:#10b981; border:1px solid rgba(16,185,129,0.4); white-space:nowrap;">✅ Thành công</span>';
          actionHtml = '<span style="font-size:0.75rem; color:#64748b; white-space:nowrap;"><i class="fa-solid fa-check-double"></i> Đã hoàn tất</span>';
        } else {
          typeBadge = '<span style="display:inline-flex; align-items:center; gap:5px; font-size:0.72rem; font-weight:700; padding:3px 8px; border-radius:6px; background:rgba(239,68,68,0.15); color:#ef4444; border:1px solid rgba(239,68,68,0.3); white-space:nowrap;"><i class="fa-solid fa-arrow-up-right-from-square"></i> Rút tiền</span>';
          amtHtml = '<span style="font-size:0.92rem; font-weight:800; color:#ef4444; font-family:monospace; white-space:nowrap;">-' + formatVND(item.amount) + '</span>';
          
          if (item.status === 'Chờ Duyệt') {
            statusBadge = '<span class="badge-trust" style="font-size:0.72rem; background:rgba(245,158,11,0.2); color:#f59e0b; border:1px solid rgba(245,158,11,0.4); white-space:nowrap;">⏳ Chờ Duyệt</span>';
            actionHtml = '<div style="display:flex; gap:6px; justify-content:center; white-space:nowrap;">' +
              '<button class="btn-action-copy" onclick="openApproveWithdrawQrModal(\'' + item.id + '\')" style="font-size:0.75rem; padding:5px 10px; background:rgba(16,185,129,0.15); border-color:rgba(16,185,129,0.4); color:#10b981; font-weight:700; cursor:pointer;" title="Duyệt rút tiền"><i class="fa-solid fa-check"></i> Duyệt</button>' +
              '<button class="btn-action-copy" onclick="rejectWithdrawRequest(\'' + item.id + '\')" style="font-size:0.75rem; padding:5px 10px; background:rgba(239,68,68,0.15); border-color:rgba(239,68,68,0.4); color:#ef4444; font-weight:700; cursor:pointer;" title="Từ chối & Hoàn tiền"><i class="fa-solid fa-xmark"></i> Hủy</button>' +
              '</div>';
          } else if (item.status.includes('Đã duyệt')) {
            statusBadge = '<span class="badge-verified" style="font-size:0.72rem; background:rgba(16,185,129,0.2); color:#10b981; border:1px solid rgba(16,185,129,0.4); white-space:nowrap;">✅ ' + item.status + '</span>';
            actionHtml = '<span style="font-size:0.75rem; color:#64748b; white-space:nowrap;"><i class="fa-solid fa-check-double"></i> Đã hoàn tất</span>';
          } else {
            statusBadge = '<span class="badge-trust" style="font-size:0.72rem; background:rgba(239,68,68,0.2); color:#ef4444; border:1px solid rgba(239,68,68,0.4); white-space:nowrap;">❌ ' + item.status + '</span>';
            actionHtml = '<span style="font-size:0.75rem; color:#64748b; white-space:nowrap;"><i class="fa-solid fa-ban"></i> Đã từ chối</span>';
          }
        }

        const handlerHtml = item.handledBy 
          ? '<span style="color:#10b981; font-weight:600; font-size:0.75rem; white-space:nowrap;"><i class="fa-solid fa-user-check"></i> ' + escapeHtml(item.handledBy) + '</span>'
          : '<span style="color:#64748b; font-size:0.75rem; white-space:nowrap;">Chưa xử lý</span>';

        return '<tr>' +
          '<td style="font-family:monospace; font-weight:700; color:#38bdf8; font-size:0.82rem; white-space:nowrap;">#' + escapeHtml(item.id) + '</td>' +
          '<td style="white-space:nowrap;">' +
            '<strong style="color:#fff; font-size:0.85rem;">' + escapeHtml(item.userName || 'User') + '</strong><br/>' +
            '<span style="font-size:0.75rem; color:#94a3b8; font-family:monospace;">' + escapeHtml(item.userEmail) + '</span>' +
          '</td>' +
          '<td style="white-space:nowrap;">' + typeBadge + '</td>' +
          '<td style="white-space:nowrap;">' + amtHtml + '</td>' +
          '<td style="font-size:0.78rem; color:#cbd5e1; white-space:nowrap;">' + item.bankInfo + '</td>' +
          '<td style="font-size:0.75rem; color:#94a3b8; white-space:nowrap;">' + escapeHtml(item.time) + '</td>' +
          '<td style="white-space:nowrap;">' + statusBadge + '</td>' +
          '<td style="white-space:nowrap;">' + handlerHtml + '</td>' +
          '<td style="text-align:center; white-space:nowrap;">' + actionHtml + '</td>' +
        '</tr>';
      }).join("");

      renderPaginationUI("admWithdrawPagination", paginationState.admWithdraw, filtered.length, "changeAdmWithdrawPage");
    }
    window.renderAdminWithdrawTable = renderAdminWithdrawTable;


    // ==================== VIETQR APPROVE WITHDRAWAL SYSTEM ====================
    const VIETQR_BANKS = [
      { code: 'MB', bin: '970422', name: 'MBBank (Quân Đội)', keywords: ['\\bmb\\b', 'mbbank', 'quan doi', 'quân đội'] },
      { code: 'VCB', bin: '970436', name: 'Vietcombank', keywords: ['vcb', 'vietcom', 'vietcombank', 'ngoai thuong', 'ngoại thương'] },
      { code: 'TCB', bin: '970407', name: 'Techcombank', keywords: ['tcb', 'techcom', 'techcombank', 'ky thuong', 'kỹ thương'] },
      { code: 'ICB', bin: '970415', name: 'VietinBank', keywords: ['icb', 'vietin', 'vietinbank', 'cong thuong', 'công thương'] },
      { code: 'BIDV', bin: '970418', name: 'BIDV', keywords: ['bidv', 'dau tu', 'đầu tư'] },
      { code: 'ACB', bin: '970416', name: 'ACB', keywords: ['\\bacb\\b', 'a chau', 'á châu'] },
      { code: 'VPB', bin: '970432', name: 'VPBank', keywords: ['\\bvpb\\b', 'vpbank', 'thinh vuong', 'thịnh vượng'] },
      { code: 'TPB', bin: '970423', name: 'TPBank', keywords: ['\\btpb\\b', 'tpbank', 'tien phong', 'tiên phong'] },
      { code: 'STB', bin: '970403', name: 'Sacombank', keywords: ['\\bstb\\b', 'sacom', 'sacombank', 'sai gon thuong tin'] },
      { code: 'VBA', bin: '970405', name: 'Agribank', keywords: ['vba', 'agri', 'agribank', 'nong nghiep', 'nông nghiệp'] },
      { code: 'VIB', bin: '970441', name: 'VIB', keywords: ['\\bvib\\b', 'vibbank', 'quoc te', 'quốc tế'] },
      { code: 'SHB', bin: '970443', name: 'SHB', keywords: ['\\bshb\\b', 'shbbank', 'sai gon ha noi'] },
      { code: 'HDB', bin: '970437', name: 'HDBank', keywords: ['hdb', 'hdbank', 'phat trien'] },
      { code: 'MSB', bin: '970426', name: 'MSB (Maritime Bank)', keywords: ['\\bmsb\\b', 'msbbank', 'hang hai', 'maritime'] },
      { code: 'LPB', bin: '970449', name: 'LPBank (LienVietPostBank)', keywords: ['\\blpb\\b', 'lpbank', 'lienviet', 'buu dien'] },
      { code: 'SEAB', bin: '970440', name: 'SeABank', keywords: ['seab', 'seabank', 'dong nam a'] },
      { code: 'OCB', bin: '970448', name: 'OCB (Phương Đông)', keywords: ['\\bocb\\b', 'ocbbank', 'phuong dong'] },
      { code: 'EIB', bin: '970431', name: 'Eximbank', keywords: ['\\beib\\b', 'exim', 'eximbank', 'xuat nhap khau'] },
      { code: 'BAB', bin: '970409', name: 'BacABank', keywords: ['\\bbab\\b', 'bac a', 'bắc á'] },
      { code: 'NAB', bin: '970428', name: 'NamABank', keywords: ['\\bnab\\b', 'nam a', 'nam á'] },
      { code: 'KLB', bin: '970452', name: 'Kienlongbank', keywords: ['\\bklb\\b', 'kien long', 'kiên long', 'kienlongbank'] },
      { code: 'PVCB', bin: '970412', name: 'PVcomBank', keywords: ['pvcb', 'pvcom', 'pvcombank', 'dai chung'] },
      { code: 'CAKE', bin: '546034', name: 'CAKE by VPBank', keywords: ['cake'] },
      { code: 'TIMO', bin: '963388', name: 'Timo by BVBank', keywords: ['timo'] },
      { code: 'VAB', bin: '970427', name: 'VietABank', keywords: ['\\bvab\\b', 'viet a', 'việt á', 'vietabank'] },
      { code: 'NCB', bin: '970419', name: 'NCB (Quốc Dân)', keywords: ['\\bncb\\b', 'ncbbank', 'quoc dan'] },
      { code: 'SHBVN', bin: '970424', name: 'Shinhan Bank', keywords: ['shinhan'] },
      { code: 'WOO', bin: '970457', name: 'Woori Bank', keywords: ['woori'] }
    ];

    function resolveVietQRBankCode(bankName) {
      if (!bankName) return VIETQR_BANKS[0];
      const raw = String(bankName).toLowerCase().trim();
      const normalized = raw.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d");

      for (let i = 0; i < VIETQR_BANKS.length; i++) {
        const b = VIETQR_BANKS[i];
        if (b.code.toLowerCase() === raw || b.bin === raw) return b;
      }

      for (let i = 0; i < VIETQR_BANKS.length; i++) {
        const b = VIETQR_BANKS[i];
        for (let j = 0; j < b.keywords.length; j++) {
          const kw = b.keywords[j];
          if (kw.indexOf('\\b') === 0) {
            const pattern = new RegExp(kw, 'i');
            if (pattern.test(raw) || pattern.test(normalized)) return b;
          } else {
            const kwNorm = kw.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d");
            if (normalized.indexOf(kwNorm) !== -1 || raw.indexOf(kw) !== -1) return b;
          }
        }
      }

      return VIETQR_BANKS[0];
    }

    let currentApproveWithdrawItem = null;

    function openApproveWithdrawQrModal(wdId) {
      const list = getWithdrawRequests();
      const item = list.find(w => w.id === wdId);
      if (!item) {
        showToast("Không tìm thấy yêu cầu rút tiền này!", "danger");
        return;
      }
      if (item.status !== "Chờ Duyệt") {
        showToast("Yêu cầu này đã được xử lý trước đó!", "warning");
        return;
      }

      currentApproveWithdrawItem = item;

      // Populate bank selector dropdown
      const bankSelect = document.getElementById("admQrBankSelect");
      if (bankSelect) {
        bankSelect.innerHTML = VIETQR_BANKS.map(b => 
          '<option value="' + b.code + '">' + escapeHtml(b.name) + '</option>'
        ).join("");

        const matchedBank = resolveVietQRBankCode(item.bankName);
        bankSelect.value = matchedBank.code;
      }

      // Populate displays
      if (document.getElementById("admQrAmountDisp")) document.getElementById("admQrAmountDisp").innerText = formatVND(item.amount);
      if (document.getElementById("admQrBankAccDisp")) document.getElementById("admQrBankAccDisp").innerText = item.bankAcc || "";
      if (document.getElementById("admQrBankOwnerDisp")) document.getElementById("admQrBankOwnerDisp").innerText = (item.bankOwner || "").toUpperCase();
      if (document.getElementById("admQrBankNameDisp")) document.getElementById("admQrBankNameDisp").innerText = item.bankName || "";
      const memo = "RUT TIEN " + item.id;
      if (document.getElementById("admQrMemoDisp")) document.getElementById("admQrMemoDisp").innerText = memo;
      if (document.getElementById("admQrUserDisp")) document.getElementById("admQrUserDisp").innerText = (item.userName || "User") + " (" + (item.userEmail || "") + ")";
      if (document.getElementById("admQrIdDisp")) document.getElementById("admQrIdDisp").innerText = "#" + item.id;

      updateWithdrawQrImage();

      const modal = document.getElementById("adminWithdrawQrModal");
      if (modal) modal.style.display = "flex";
    }

    function updateWithdrawQrImage() {
      if (!currentApproveWithdrawItem) return;
      const bankSelect = document.getElementById("admQrBankSelect");
      const bankCode = bankSelect ? bankSelect.value : "MB";
      const cleanAcc = String(currentApproveWithdrawItem.bankAcc || "").replace(/[^0-9a-zA-Z]/g, "");
      const cleanOwner = String(currentApproveWithdrawItem.bankOwner || "").trim().toUpperCase();
      const memo = "RUT TIEN " + currentApproveWithdrawItem.id;
      
      const qrUrl = "https://img.vietqr.io/image/" + bankCode + "-" + cleanAcc + "-compact2.png?amount=" + currentApproveWithdrawItem.amount + "&addInfo=" + encodeURIComponent(memo) + "&accountName=" + encodeURIComponent(cleanOwner);
      
      const qrImg = document.getElementById("admQrImg");
      if (qrImg) {
        qrImg.src = qrUrl;
        qrImg.onerror = function() {
          console.warn("VietQR image compact2 failed, switching to simple QR...");
          qrImg.src = "https://img.vietqr.io/image/" + bankCode + "-" + cleanAcc + "-qr_only.png?amount=" + currentApproveWithdrawItem.amount + "&addInfo=" + encodeURIComponent(memo);
        };
      }

      if (bankSelect && bankSelect.selectedOptions && bankSelect.selectedOptions[0]) {
        const bNameDisp = document.getElementById("admQrBankNameDisp");
        if (bNameDisp) bNameDisp.innerText = bankSelect.selectedOptions[0].text;
      }
    }

    function onChangeAdmQrBank() {
      updateWithdrawQrImage();
    }

    function copyAdmQrField(field) {
      if (!currentApproveWithdrawItem) return;
      if (field === "acc") {
        copyToClipboard(currentApproveWithdrawItem.bankAcc, "Đã sao chép Số tài khoản: " + currentApproveWithdrawItem.bankAcc);
      } else if (field === "owner") {
        copyToClipboard((currentApproveWithdrawItem.bankOwner || "").toUpperCase(), "Đã sao chép Tên chủ tài khoản: " + (currentApproveWithdrawItem.bankOwner || "").toUpperCase());
      } else if (field === "amount") {
        copyToClipboard(String(currentApproveWithdrawItem.amount), "Đã sao chép Số tiền: " + formatVND(currentApproveWithdrawItem.amount));
      } else if (field === "memo") {
        const memo = "RUT TIEN " + currentApproveWithdrawItem.id;
        copyToClipboard(memo, "Đã sao chép Nội dung CK: " + memo);
      } else if (field === "bank") {
        const bankSelect = document.getElementById("admQrBankSelect");
        const bName = bankSelect && bankSelect.selectedOptions && bankSelect.selectedOptions[0] ? bankSelect.selectedOptions[0].text : (currentApproveWithdrawItem.bankName || "");
        copyToClipboard(bName, "Đã sao chép Tên ngân hàng: " + bName);
      }
    }

    function executeApproveWithdrawal() {
      if (!currentApproveWithdrawItem) {
        showToast("Không tìm thấy thông tin yêu cầu rút tiền!", "danger");
        return;
      }

      const wdId = currentApproveWithdrawItem.id;
      const list = getWithdrawRequests();
      const item = list.find(w => w.id === wdId);
      if (!item) {
        showToast("Không tìm thấy yêu cầu rút tiền này!", "danger");
        closeModal("adminWithdrawQrModal");
        return;
      }
      if (item.status !== "Chờ Duyệt") {
        showToast("Yêu cầu này đã được xử lý trước đó!", "warning");
        closeModal("adminWithdrawQrModal");
        return;
      }

      const adminName = currentUser ? (currentUser.name + " (" + currentUser.email + ")") : "Quản Trị Viên";

      if (!confirm("XÁC NHẬN BẠN ĐÃ CHUYỂN KHOẢN THÀNH CÔNG " + formatVND(item.amount) + " CHO " + (item.userName || "người dùng") + "?\n\nBấm OK để hoàn tất duyệt yêu cầu rút tiền này!")) {
        return;
      }

      item.status = "Đã duyệt & Đã chuyển";
      item.handledBy = adminName;
      item.handledTime = new Date().toLocaleDateString("vi-VN") + " " + new Date().toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" });
      saveWithdrawRequests(list);

      // Record platform transaction log
      recordTransaction(item.userEmail, item.userName, "Rút tiền ngân hàng", -item.amount, "Đã chi", "Duyệt & Chuyển QR bởi Admin: " + adminName + " | STK: " + item.bankAcc + " (" + item.bankName + ")");

      closeModal("adminWithdrawQrModal");
      currentApproveWithdrawItem = null;

      renderAdminWithdrawTable();
      renderAdminTxTable();
      showToast("🎉 Đã xác nhận chuyển tiền và duyệt yêu cầu rút thành công!", "success");
    }

    function rejectFromQrModal() {
      if (!currentApproveWithdrawItem) return;
      const id = currentApproveWithdrawItem.id;
      closeModal("adminWithdrawQrModal");
      rejectWithdrawRequest(id);
    }

    function approveWithdrawRequest(wdId) {
      openApproveWithdrawQrModal(wdId);
    }

    function rejectWithdrawRequest(wdId) {
      const list = getWithdrawRequests();
      const item = list.find(w => w.id === wdId);
      if (!item) {
        showToast("Không tìm thấy yêu cầu rút tiền này!", "danger");
        return;
      }
      if (item.status !== "Chờ Duyệt") {
        showToast("Yêu cầu này đã được xử lý trước đó!", "warning");
        return;
      }

      const reason = prompt("Nhập lý do từ chối yêu cầu rút tiền (Số tiền " + formatVND(item.amount) + " sẽ được HOÀN LẠI vào ví người dùng):", "Thông tin tài khoản ngân hàng không chính xác");
      if (reason === null) return;

      const adminName = currentUser ? (currentUser.name + " (" + currentUser.email + ")") : "Quản Trị Viên";
      item.status = "Đã từ chối (Hoàn tiền)";
      item.handledBy = adminName;
      item.rejectReason = reason || "Từ chối bởi Admin";
      item.handledTime = new Date().toLocaleDateString("vi-VN") + " " + new Date().toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" });
      saveWithdrawRequests(list);

      // Refund user balance
      const users = getRegisteredUsers();
      const uIdx = users.findIndex(u => (u.email || "").toLowerCase() === (item.userEmail || "").toLowerCase());
      let newBal = 0;
      if (uIdx !== -1) {
        users[uIdx].balance = (users[uIdx].balance || 0) + item.amount;
        newBal = users[uIdx].balance;
        saveRegisteredUsers(users);
      }

      if (currentUser && currentUser.email.toLowerCase() === item.userEmail.toLowerCase()) {
        currentUser.balance = newBal;
        localStorage.setItem("mmo_user", JSON.stringify(currentUser));
        updateUserUI();
      }

      // Record refund log
      recordTransaction(item.userEmail, item.userName, "Hoàn tiền rút (Từ chối)", item.amount, newBal, "Từ chối bởi Admin " + adminName + " - Lý do: " + (reason || "Thông tin không hợp lệ"));

      renderAdminWithdrawTable();
      renderAdminUsersTable();
      renderAdminTxTable();
      showToast("Đã từ chối và hoàn tiền " + formatVND(item.amount) + " lại vào ví người dùng!", "info");
    }

    // ==================== MEMBER LOCK & DELETE SYSTEM ====================
    function toggleLockUser(email) {
      const rootEmail = (typeof ROOT_ADMIN_EMAIL !== "undefined" ? ROOT_ADMIN_EMAIL : "manhdongvtc@gmail.com").toLowerCase().trim();
      if (email.toLowerCase().trim() === rootEmail) {
        showToast("Không thể khóa tài khoản Root Admin!", "warning");
        return;
      }
      if (currentUser && currentUser.email.toLowerCase().trim() === email.toLowerCase().trim()) {
        showToast("Bạn không thể tự khóa tài khoản của chính mình!", "warning");
        return;
      }

      let users = getRegisteredUsers();
      const idx = users.findIndex(u => (u.email || "").toLowerCase() === email.toLowerCase());
      if (idx === -1) {
        showToast("Không tìm thấy người dùng!", "danger");
        return;
      }

      users[idx].isLocked = !users[idx].isLocked;
      saveRegisteredUsers(users);
      renderAdminUsersTable();

      if (users[idx].isLocked) {
        showToast("🔒 Đã khóa tài khoản: " + users[idx].name, "warning");
      } else {
        showToast("🔓 Đã mở khóa tài khoản: " + users[idx].name, "success");
      }
    }

    function deleteUser(email) {
      const rootEmail = (typeof ROOT_ADMIN_EMAIL !== "undefined" ? ROOT_ADMIN_EMAIL : "manhdongvtc@gmail.com").toLowerCase().trim();
      const targetEmail = (email || "").toLowerCase().trim();

      if (targetEmail === rootEmail) {
        showToast("Không thể xóa tài khoản Root Admin tối cao!", "warning");
        return;
      }
      
      let isSelf = (currentUser && (currentUser.email || "").toLowerCase().trim() === targetEmail);
      let confirmMsg = "Bạn có chắc chắn muốn XÓA vĩnh viễn tài khoản [" + email + "] khỏi hệ thống?";
      if (isSelf) {
        confirmMsg = "CẢNH BÁO: Bạn đang đăng nhập bằng tài khoản [" + email + "]. Nếu xóa, bạn sẽ bị đăng xuất ngay lập tức. Tiếp tục xóa?";
      }

      if (!confirm(confirmMsg)) {
        return;
      }

      // Remove from registered users
      let users = getRegisteredUsers();
      users = users.filter(u => (u.email || "").toLowerCase().trim() !== targetEmail);
      localStorage.setItem("mmo_registered_users", JSON.stringify(users));

      // Also remove from admin emails list if present
      let adminList = getAdminEmails();
      if (adminList.map(e => (e || "").toLowerCase().trim()).includes(targetEmail)) {
        adminList = adminList.filter(e => (e || "").toLowerCase().trim() !== targetEmail);
        saveAdminEmails(adminList);
      }

      // Also delete from Google Sheet in real time!
      try {
        if (typeof callGasApi === "function") {
          callGasApi("adminDeleteUser", {
            email: targetEmail,
            adminEmail: (currentUser ? currentUser.email : ROOT_ADMIN_EMAIL)
          }).catch(function(e) {});
        }
      } catch(e) {}

      if (isSelf) {
        localStorage.removeItem("mmo_user");
        currentUser = null;
        updateUserUI();
        switchView("viewStore");
        showToast("Đã xóa tài khoản và đăng xuất!", "info");
      } else {
        if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
        if (typeof renderAdminEmailsList === "function") renderAdminEmailsList();
        if (typeof renderAdminDashboard === "function") renderAdminDashboard();
        showToast("🗑️ Đã xóa vĩnh viễn tài khoản: " + email, "success");
      }
    }
    window.deleteUser = deleteUser;

    function openWithdrawModal() {
      if (!currentUser) {
        showToast("Vui lòng đăng nhập để rút tiền!", "info");
        openAuthModal();
        return;
      }

      const bal = currentUser.balance || 0;
      const balDisp = document.getElementById("withdrawModalCurrentBal");
      if (balDisp) balDisp.innerText = formatVND(bal);

      // Prefill bank info if saved
      try {
        const savedBank = localStorage.getItem("mmo_user_bank");
        if (savedBank) {
          const b = JSON.parse(savedBank);
          if (document.getElementById("withdrawBankNameInput")) document.getElementById("withdrawBankNameInput").value = b.bankName || "";
          if (document.getElementById("withdrawBankAccInput")) document.getElementById("withdrawBankAccInput").value = b.bankAcc || "";
          if (document.getElementById("withdrawBankOwnerInput")) document.getElementById("withdrawBankOwnerInput").value = b.bankOwner || "";
        }
      } catch(e) {}

      if (document.getElementById("withdrawAmountInput")) {
        document.getElementById("withdrawAmountInput").value = Math.min(bal, 100000) || "";
      }

      document.getElementById("withdrawModal").style.display = "flex";
    }

    function handleProfileWithdraw() {
      openWithdrawModal();
    }

    function submitWithdrawRequest() {
      if (!currentUser) {
        showToast("Vui lòng đăng nhập để rút tiền!", "warning");
        return;
      }

      const amount = parseInt(document.getElementById("withdrawAmountInput")?.value) || 0;
      const bankName = document.getElementById("withdrawBankNameInput")?.value.trim();
      const bankAcc = document.getElementById("withdrawBankAccInput")?.value.trim();
      const bankOwner = document.getElementById("withdrawBankOwnerInput")?.value.trim();
      const note = document.getElementById("withdrawNoteInput")?.value.trim() || "Rút tiền về tài khoản ngân hàng";

      if (amount < 50000) {
        showToast("Số tiền rút tối thiểu là 50.000 đ!", "warning");
        return;
      }
      if (amount > (currentUser.balance || 0)) {
        showToast("Số dư ví không đủ để rút số tiền này!", "danger");
        return;
      }
      if (!bankName || !bankAcc || !bankOwner) {
        showToast("Vui lòng điền đầy đủ Ngân hàng, Số tài khoản và Tên chủ tài khoản!", "warning");
        return;
      }

      // Save bank info for next time
      localStorage.setItem("mmo_user_bank", JSON.stringify({ bankName, bankAcc, bankOwner }));

      // Deduct balance from currentUser
      currentUser.balance -= amount;
      localStorage.setItem("mmo_user", JSON.stringify(currentUser));

      // Sync to registered users
      let users = getRegisteredUsers();
      const uIdx = users.findIndex(u => (u.email || "").toLowerCase() === currentUser.email.toLowerCase());
      if (uIdx !== -1) {
        users[uIdx].balance = currentUser.balance;
        saveRegisteredUsers(users);
      }

      // Create withdraw request
      const wdList = getWithdrawRequests();
      const wdId = "WD" + Math.floor(100000 + Math.random() * 900000);
      const now = new Date();
      const timeStr = now.toLocaleDateString("vi-VN") + " " + now.toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" });

      wdList.unshift({
        id: wdId,
        userEmail: currentUser.email,
        userName: currentUser.name,
        amount: amount,
        bankName: bankName,
        bankAcc: bankAcc,
        bankOwner: bankOwner,
        time: timeStr,
        status: "Chờ Duyệt",
        handledBy: "",
        note: note
      });
      saveWithdrawRequests(wdList);

      // Record platform transaction log
      recordTransaction(currentUser.email, currentUser.name, "Yêu cầu rút tiền", -amount, currentUser.balance, "Đang chờ duyệt | STK: " + bankAcc + " (" + bankName + ")");

      updateUserUI();
      closeModal("withdrawModal");
      renderUserWalletTransactions();
      if (typeof renderAdminWithdrawTable === "function") renderAdminWithdrawTable();
      if (typeof renderAdminTxTable === "function") renderAdminTxTable();

      showToast("🎉 Gửi yêu cầu rút " + formatVND(amount) + " thành công! Quản trị viên sẽ duyệt trong ít phút.", "success");
    }


    // ==================== UNIVERSAL 10-ITEM PAGINATION SYSTEM ====================
    var ITEMS_PER_PAGE = 10;
    window.ITEMS_PER_PAGE = 10;

    var paginationState = {
      admPreOrders: 1,
      admUsers: 1,
      admUsers: 1,
      admWithdraw: 1,
      admTx: 1,
      admProd: 1,
      admApiMappings: 1,
      admBlogs: 1,
      storeProd: 1,
      userOrders: 1,
      userWallet: 1,
      blogPage: 1
    };

    function renderPaginationUI(containerId, currentPage, totalItems, onPageChangeName, customPageSize) {
      const container = document.getElementById(containerId);
      if (!container) return;

      const pageSize = customPageSize || window.ITEMS_PER_PAGE || 10;
      const totalPages = Math.ceil(totalItems / pageSize) || 1;
      
      if (totalItems <= 0) {
        container.innerHTML = "";
        return;
      }

      if (totalPages <= 1) {
        container.innerHTML = '<div style="display:flex; justify-content:center; align-items:center; gap:6px; margin-top:16px; padding:10px 0; flex-wrap:wrap;">' +
          '<button type="button" disabled style="padding:6px 12px; background:#0d131f; border:1px solid #1e293b; color:#475569; border-radius:6px; font-size:0.8rem; cursor:not-allowed; opacity:0.6;"><i class="fa-solid fa-chevron-left"></i> Trước</button>' +
          '<button type="button" style="padding:6px 12px; background:#10b981; border:1px solid #10b981; color:#fff; font-weight:700; border-radius:6px; font-size:0.8rem;">1</button>' +
          '<button type="button" disabled style="padding:6px 12px; background:#0d131f; border:1px solid #1e293b; color:#475569; border-radius:6px; font-size:0.8rem; cursor:not-allowed; opacity:0.6;">Sau <i class="fa-solid fa-chevron-right"></i></button>' +
          '<span style="font-size:0.75rem; color:#64748b; margin-left:8px;">(Trang 1/1 - ' + totalItems + ' mục)</span>' +
          '</div>';
        return;
      }

      let html = '<div style="display:flex; justify-content:center; align-items:center; gap:6px; margin-top:16px; padding:10px 0; flex-wrap:wrap;">';
      
      // Prev button
      if (currentPage > 1) {
        html += '<button type="button" onclick="' + onPageChangeName + '(' + (currentPage - 1) + ')" style="padding:6px 12px; background:#0d131f; border:1px solid #1e293b; color:#cbd5e1; border-radius:6px; font-size:0.8rem; cursor:pointer;"><i class="fa-solid fa-chevron-left"></i> Trước</button>';
      } else {
        html += '<button type="button" disabled style="padding:6px 12px; background:#0d131f; border:1px solid #1e293b; color:#475569; border-radius:6px; font-size:0.8rem; cursor:not-allowed; opacity:0.6;"><i class="fa-solid fa-chevron-left"></i> Trước</button>';
      }

      for (let i = 1; i <= totalPages; i++) {
        if (i === currentPage) {
          html += '<button type="button" style="padding:6px 12px; background:#10b981; border:1px solid #10b981; color:#fff; font-weight:700; border-radius:6px; font-size:0.8rem;">' + i + '</button>';
        } else if (i === 1 || i === totalPages || (i >= currentPage - 2 && i <= currentPage + 2)) {
          html += '<button type="button" onclick="' + onPageChangeName + '(' + i + ')" style="padding:6px 12px; background:#0d131f; border:1px solid #1e293b; color:#94a3b8; border-radius:6px; font-size:0.8rem; cursor:pointer;">' + i + '</button>';
        } else if (i === currentPage - 3 || i === currentPage + 3) {
          html += '<span style="color:#64748b; padding:0 4px;">...</span>';
        }
      }

      // Next button
      if (currentPage < totalPages) {
        html += '<button type="button" onclick="' + onPageChangeName + '(' + (currentPage + 1) + ')" style="padding:6px 12px; background:#0d131f; border:1px solid #1e293b; color:#cbd5e1; border-radius:6px; font-size:0.8rem; cursor:pointer;">Sau <i class="fa-solid fa-chevron-right"></i></button>';
      } else {
        html += '<button type="button" disabled style="padding:6px 12px; background:#0d131f; border:1px solid #1e293b; color:#475569; border-radius:6px; font-size:0.8rem; cursor:not-allowed; opacity:0.6;">Sau <i class="fa-solid fa-chevron-right"></i></button>';
      }

      html += '<span style="font-size:0.75rem; color:#64748b; margin-left:8px;">(Trang ' + currentPage + '/' + totalPages + ' - ' + totalItems + ' mục, ' + pageSize + ' mục/trang)</span>';
      html += '</div>';

      container.innerHTML = html;
    }

