    // Tự động kiểm tra và quyết toán hoa hồng tiếp thị đã qua 3 ngày
    try {
      if (typeof processAffiliateSettlement === "function") {
        processAffiliateSettlement();
      }
      setInterval(function() {
        if (typeof processAffiliateSettlement === "function") {
          processAffiliateSettlement();
        }
      }, 60000);
    } catch(e) {}

    // GLOBAL DOM CONTENT LOADED INITIALIZER & CROSS-TAB SYNC
    // 1. Capture Ref Code and Product Navigation from URL
    try {
      if (typeof window !== "undefined" && window.location) {
        const urlParams = new URLSearchParams(window.location.search);
        let refParam = urlParams.get("ref");
        if (!refParam && window.location.hash.includes("ref=")) {
          const m = window.location.hash.match(/ref=([^&]+)/);
          if (m) refParam = decodeURIComponent(m[1]);
        }
        if (refParam && refParam.trim()) {
          const cleanRef = refParam.trim().toLowerCase();
          localStorage.setItem("mmo_ref_code", cleanRef);
          try { sessionStorage.setItem("mmo_ref_code", cleanRef); } catch(e) {}
          console.log("MMO Affiliate Ref Code captured:", cleanRef);
        }

        // Auto-open product if ?prod= or ?id= or #product_ in URL
        let prodParam = urlParams.get("prod") || urlParams.get("product") || urlParams.get("id");
        if (!prodParam && window.location.hash.startsWith("#product_")) {
          prodParam = window.location.hash.replace("#product_", "").split("?")[0];
        }
        if (prodParam) {
          setTimeout(function() {
            if (typeof openProductDetailById === "function") {
              openProductDetailById(prodParam);
            }
          }, 400);
        }
      }
    } catch(e) {}

    // [SSOT NATIVE SYNC]: Lắng nghe sự kiện storage chuẩn trình duyệt giữa các cửa sổ song song
    if (typeof window !== "undefined") {
      window.addEventListener("storage", function(e) {
        if (e.key === "mmo_warehouse" || e.key === "mmo_products" || e.key === "mmo_admin_products" || e.key === "mmo_products_stock" || e.key === "mmo_stock_items" || e.key === "mmo_product_variants_map" || e.key === "mmo_stock_webhook_bus") {
          // [SSOT FIX]: Đọc dữ liệu mới từ localStorage trực tiếp, KHÔNG thông qua loadPersistedProducts
          // vì loadPersistedProducts có thể merge sai và gọi restoreProductVariants làm mất accounts
          try {
            const freshJson = localStorage.getItem("mmo_admin_products") || localStorage.getItem("mmo_products");
            if (freshJson) {
              const freshProds = JSON.parse(freshJson);
              if (Array.isArray(freshProds) && freshProds.length > 0) {
                // Merge vào MOCK_DATA - bảo toàn accounts đang có trong memory nếu nhiều hơn
                if (typeof MOCK_DATA !== "undefined" && MOCK_DATA && MOCK_DATA.products) {
                  freshProds.forEach(function(fp) {
                    const mp = MOCK_DATA.products.find(function(p) { return String(p.id) === String(fp.id); });
                    if (mp) {
                      const accsMap = {};
                      if (Array.isArray(mp.variants)) {
                        mp.variants.forEach(function(mv, vi) {
                          if (Array.isArray(mv.accounts) && mv.accounts.length > 0) accsMap[mv.name || vi] = mv.accounts.slice();
                        });
                      }
                      // Cập nhật 100% dữ liệu mới nhất
                      Object.assign(mp, fp);
                      if (Array.isArray(mp.variants)) {
                        mp.variants.forEach(function(mv, vi) {
                          const accs = (fp.variants && fp.variants[vi] && Array.isArray(fp.variants[vi].accounts) && fp.variants[vi].accounts.length > 0)
                            ? fp.variants[vi].accounts
                            : (accsMap[mv.name || vi] || (Array.isArray(mv.accounts) ? mv.accounts : []));
                          mv.accounts = accs;
                          if (accs.length > 0) mv.stock = accs.length;
                        });
                      }
                    } else {
                      MOCK_DATA.products.push(fp);
                    }
                  });
                }
              }
            }
          } catch(storageErr) {}
          // Sau khi merge xong, sync UI với dữ liệu hiện tại
          if (typeof syncAllOpenViewsStock === "function") {
            // Lấy accounts của sản phẩm/biến thể đang xem
            try {
              if (typeof currentSelectedProduct !== "undefined" && currentSelectedProduct) {
                const fresh = (MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products.find(p => String(p.id) === String(currentSelectedProduct.id) || (p.name && currentSelectedProduct.name && p.name.trim().toLowerCase() === currentSelectedProduct.name.trim().toLowerCase())) : null;
                if (fresh) currentSelectedProduct = fresh;
                const vIdx = (typeof currentSelectedVariantIndex !== "undefined") ? currentSelectedVariantIndex : 0;
                const hasV = Array.isArray(currentSelectedProduct.variants) && currentSelectedProduct.variants.length > 0;
                const curAccounts = hasV
                  ? (currentSelectedProduct.variants[vIdx] ? currentSelectedProduct.variants[vIdx].accounts : [])
                  : currentSelectedProduct.accounts;
                const curStock = getShopVariantStock(currentSelectedProduct, hasV ? vIdx : null);
                syncAllOpenViewsStock(currentSelectedProduct.id, curStock, curAccounts || [], true, vIdx);
                if (typeof syncDetailStockUI === "function") syncDetailStockUI(curStock);
                const pillsContainer = document.getElementById("dtlVariantPills");
                if (pillsContainer && hasV) {
                  pillsContainer.innerHTML = currentSelectedProduct.variants.map((v, idx) => {
                    const vs = getShopVariantStock(currentSelectedProduct, idx);
                    const badge = vs > 0 
                      ? '<small style="color:#10b981; font-weight:700; margin-left:6px; font-size:0.75rem;">(' + vs + ' acc)</small>' 
                      : '<small style="color:#ef4444; font-weight:700; margin-left:6px; font-size:0.75rem;">(0 acc)</small>';
                    return '<div class="variant-pill-option ' + (idx === vIdx ? 'active' : '') + '" onclick="selectVariant(' + idx + ', ' + (v.price || 0) + ')">' +
                      '<span>' + escapeHtml(v.name || ('Gói ' + (idx + 1))) + badge + '</span>' +
                      '<span style="font-weight:700;">' + formatVND(v.price || 0) + '</span>' +
                    '</div>';
                  }).join("");
                }
              } else {
                syncAllOpenViewsStock(null, null, null, true);
              }
            } catch(e2) { syncAllOpenViewsStock(null, null, null, true); }
          }
        }
      });
    }

    // 2. Cross-tab live sync for real-time admin updates
    // Lắng nghe BroadcastChannel để đồng bộ realtime giữa các tab/cửa sổ song song
    try {
      if (typeof BroadcastChannel !== "undefined") {
        // Xử lý sự kiện đặt trước phát sóng đa tab Realtime 0ms
    
    // ============================================================
    // [REALTIME PRE-ORDER MULTI-CHANNEL ENGINE - 0MS NO REFRESH]
    // ============================================================
    function getMmoPreOrdersBc() {
      if (typeof window === "undefined" || typeof BroadcastChannel === "undefined") return null;
      if (!window._mmoPersistentPreOrdersBc) {
        window._mmoPersistentPreOrdersBc = new BroadcastChannel("mmo_preorders_channel");
        window._mmoPersistentPreOrdersBc.onmessage = function(ev) {
          if (ev && ev.data) handlePreOrdersBroadcastMessage(ev.data);
        };
      }
      return window._mmoPersistentPreOrdersBc;
    }
    window.getMmoPreOrdersBc = getMmoPreOrdersBc;

    function getMmoGlobalBc() {
      if (typeof window === "undefined" || typeof BroadcastChannel === "undefined") return null;
      if (!window._mmoPersistentGlobalBc) {
        window._mmoPersistentGlobalBc = new BroadcastChannel("mmo_channel");
        window._mmoPersistentGlobalBc.onmessage = function(ev) {
          if (ev && ev.data && (ev.data.type === "NEW_PREORDER" || ev.data.type === "ORDER_STATUS_CHANGED" || ev.data.type === "PREORDERS_UPDATED")) {
            handlePreOrdersBroadcastMessage(ev.data);
          }
        };
      }
      return window._mmoPersistentGlobalBc;
    }
    window.getMmoGlobalBc = getMmoGlobalBc;

    function broadcastPreOrderEvent(payload) {
      if (!payload) return;
      // 1. Same-origin BroadcastChannel (persistent, never closed)
      try {
        const poBc = getMmoPreOrdersBc();
        if (poBc) poBc.postMessage(payload);
      } catch(e) {}
      try {
        const mmoBc = getMmoGlobalBc();
        if (mmoBc) mmoBc.postMessage(payload);
      } catch(e) {}

      // 2. Cross-profile & cross-incognito Realtime SSE Hub (0ms latency)
      try {
        fetch("https://ntfy.sh/mmo_preorders_realtime_stream/publish", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload)
        }).catch(function() {});
      } catch(e) {}
    }
    window.broadcastPreOrderEvent = broadcastPreOrderEvent;

    var _preOrdersRealtimeSSE = null;
    function initPreOrdersRealtimeSSE() {
      try {
        if (typeof window === "undefined" || typeof EventSource === "undefined") return;
        if (_preOrdersRealtimeSSE) {
          _preOrdersRealtimeSSE.close();
        }
        _preOrdersRealtimeSSE = new EventSource("https://ntfy.sh/mmo_preorders_realtime_stream/sse");
        _preOrdersRealtimeSSE.onmessage = function(ev) {
          try {
            const data = JSON.parse(ev.data);
            if (data && data.event === "message" && data.message) {
              const incoming = JSON.parse(data.message);
              handlePreOrdersBroadcastMessage(incoming);
            } else if (data && data.type) {
              handlePreOrdersBroadcastMessage(data);
            }
          } catch(err) {}
        };
      } catch(e) {}
    }
    window.initPreOrdersRealtimeSSE = initPreOrdersRealtimeSSE;

    function handlePreOrdersBroadcastMessage(data) {
      if (!data) return;
      if (data.type === "NEW_PREORDER" && data.order) {
        _cachedPreOrdersList = null;
        _lastPreOrdersFetchTime = 0;
        const newOrd = data.order;
        const ordCode = String(newOrd.orderCode || newOrd.id || "").replace("#","").toLowerCase();
        
        // 1. Cập nhật mmo_pre_orders
        const curOrders = (typeof getPreOrders === "function") ? getPreOrders(true) : [];
        if (!curOrders.some(p => String(p.orderCode || p.id).replace("#","").toLowerCase() === ordCode)) {
          curOrders.unshift(newOrd);
          try { localStorage.setItem("mmo_pre_orders", JSON.stringify(curOrders)); } catch(e) {}
        }

        // 2. Cập nhật mmo_all_orders và mmo_orders để bảng Lịch sử đơn hàng toàn sàn thấy ngay lập tức
        ["mmo_all_orders", "mmo_orders"].forEach(function(k) {
          try {
            const raw = localStorage.getItem(k);
            let list = raw ? JSON.parse(raw) : [];
            if (!Array.isArray(list)) list = [];
            if (!list.some(p => String(p.orderCode || p.id || p.orderId).replace("#","").toLowerCase() === ordCode)) {
              list.unshift(newOrd);
              localStorage.setItem(k, JSON.stringify(list));
            }
          } catch(e) {}
        });

        // 3. Rerender toàn bộ UI Admin và UI Người dùng trong 0ms
        if (typeof updateAdminPreOrdersBadge === "function") updateAdminPreOrdersBadge();
        if (typeof renderAdminPreOrdersTable === "function") renderAdminPreOrdersTable();
        if (typeof renderAdminOrdersTable === "function") renderAdminOrdersTable();
        if (typeof renderProfileOrders === "function") renderProfileOrders();
        if (typeof renderSystemOverview === "function") renderSystemOverview();

        // 4. Phát âm thanh chuông và hiển thị thông báo toast nếu là Admin
        if (typeof isAdminUser === "function" && isAdminUser()) {
          if (typeof playNotificationSound === "function") playNotificationSound();
          if (typeof showToast === "function") showToast("🔔 Có đơn đặt hàng trước mới #" + (newOrd.orderCode || newOrd.id) + " - " + (newOrd.productName || "Sản phẩm"), "info");
          if (typeof addUserNotification === "function") {
            addUserNotification({
              title: "⏳ Đơn đặt trước mới #" + (newOrd.orderCode || newOrd.id),
              message: "Khách [" + (newOrd.buyerEmail || newOrd.userEmail || "Khách") + "] vừa đặt trước " + (newOrd.quantity || newOrd.qty || 1) + "x " + (newOrd.productName || "Sản phẩm") + ".",
              type: "PRE_ORDER",
              orderId: newOrd.orderCode || newOrd.id,
              forAdmin: true,
              playSound: false
            });
          }
          if (typeof updateAdminSidebarBadges === "function") updateAdminSidebarBadges();
        }
      } else if (data.type === "ORDER_STATUS_CHANGED" && data.orderId) {
        const cleanId = String(data.orderId).replace("#","").toLowerCase();
        const keys = ["mmo_pre_orders", "mmo_orders", "mmo_user_orders", "mmo_all_orders"];
        keys.forEach(k => {
          try {
            const raw = localStorage.getItem(k);
            if (!raw) return;
            const arr = JSON.parse(raw);
            if (!Array.isArray(arr)) return;
            let mod = false;
            arr.forEach(o => {
              const oId = String(o.orderCode || o.id || o.orderId || "").replace("#","").toLowerCase();
              if (oId === cleanId) {
                o.status = data.status;
                o.statusText = data.statusText;
                if (data.deliveredAccounts) o.deliveredAccounts = data.deliveredAccounts;
                if (data.credentials) o.credentials = data.credentials;
                if (data.status === "CANCELLED") {
                  o.isCancelled = true;
                  o.isRefunded = true;
                }
                mod = true;
              }
            });
            if (mod) localStorage.setItem(k, JSON.stringify(arr));
          } catch(e) {}
        });
        _cachedPreOrdersList = null;
        _lastPreOrdersFetchTime = 0;
        if (typeof updateAdminPreOrdersBadge === "function") updateAdminPreOrdersBadge();
        if (typeof renderAdminPreOrdersTable === "function") renderAdminPreOrdersTable();
        if (typeof renderAdminOrdersTable === "function") renderAdminOrdersTable();
        if (typeof renderProfileOrders === "function") renderProfileOrders();
        if (typeof renderSystemOverview === "function") renderSystemOverview();
        if (typeof updateAdminSidebarBadges === "function") updateAdminSidebarBadges();
        
        const dtlOidEl = document.getElementById("podOrderId");
        if (dtlOidEl && String(dtlOidEl.innerText).replace("#","").toLowerCase() === cleanId) {
          if (typeof openPreOrderDetailView === "function") openPreOrderDetailView(data.orderId);
        }
      }
    }
    window.handlePreOrdersBroadcastMessage = handlePreOrdersBroadcastMessage;

    try {
      if (typeof BroadcastChannel !== "undefined") {
        const poChannel = new BroadcastChannel("mmo_preorders_channel");
        poChannel.onmessage = function(ev) {
          if (ev && ev.data) handlePreOrdersBroadcastMessage(ev.data);
        };
      }
    } catch(ePoBc) {}

    const globalBc = new BroadcastChannel("mmo_channel");
        globalBc.onmessage = function(ev) {
          if (ev && ev.data && (ev.data.type === "NEW_ORDER" || ev.data.type === "ORDER_CREATED")) {
            const newOrd = ev.data.order;
            if (newOrd) {
              if (!window._mmoInMemoryOrders) window._mmoInMemoryOrders = [];
              if (!window._mmoInMemoryOrders.some(o => o && o.id === newOrd.id)) {
                window._mmoInMemoryOrders.unshift(newOrd);
              }
              ['mmo_all_orders', 'mmo_orders', 'mmo_user_orders'].forEach(function(k) {
                try {
                  let arr = JSON.parse(localStorage.getItem(k) || '[]');
                  if (!arr.some(o => o && (o.id === newOrd.id || o.orderId === newOrd.id))) {
                    arr.unshift(newOrd);
                    localStorage.setItem(k, JSON.stringify(arr.slice(0, 250)));
                  }
                } catch(e) {}
              });
            }
            if (typeof renderProfileOrders === "function") renderProfileOrders();
            if (typeof renderAdminOrdersTable === "function") renderAdminOrdersTable();
            if (typeof updateAdminSidebarBadges === "function") updateAdminSidebarBadges();
            if (typeof renderSystemOverview === "function") renderSystemOverview();
            if (typeof renderUserWalletTransactions === "function") renderUserWalletTransactions();
            if (typeof renderUserBalanceLogs === "function") renderUserBalanceLogs();
          }
          if (ev && ev.data && (ev.data.type === "NEW_PREORDER" || ev.data.type === "ORDER_STATUS_CHANGED")) {
            handlePreOrdersBroadcastMessage(ev.data);
          }
          if (ev && ev.data && ev.data.type === "BALANCE_UPDATED") {
            if (typeof loadStoredUser === "function") loadStoredUser();
            if (typeof updateUserUI === "function") updateUserUI();
            if (typeof renderUserWalletTransactions === "function") renderUserWalletTransactions();
            if (typeof renderUserBalanceLogs === "function") renderUserBalanceLogs();
            if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
          }
          if (ev && ev.data && ev.data.type === "STOCK_UPDATED") {
            _cachedStockRaw = null;
            _cachedStockItems = null;
            _cachedStockMap = null;
            try {
              if (ev.data.prodId && MOCK_DATA && MOCK_DATA.products) {
                const targetProd = MOCK_DATA.products.find(function(p) {
                  return String(p.id) === String(ev.data.prodId) || 
                         (typeof isSameOrAliasProduct === "function" && isSameOrAliasProduct(p.id, ev.data.prodId)) ||
                         (p.name && ev.data.prodData && typeof isSameOrAliasProduct === "function" && isSameOrAliasProduct(p.name, ev.data.prodData.name));
                });
                if (targetProd) {
                  if (Array.isArray(ev.data.variants)) {
                    targetProd.variants = ev.data.variants.map(v => Object.assign({}, v));
                  }
                  const vIdx = (ev.data.variantIdx !== undefined && ev.data.variantIdx !== null && ev.data.variantIdx !== "ALL") ? Number(ev.data.variantIdx) : null;
                  if (ev.data.accounts && Array.isArray(ev.data.accounts)) {
                    if (vIdx !== null && Array.isArray(targetProd.variants) && targetProd.variants[vIdx]) {
                      targetProd.variants[vIdx].accounts = ev.data.accounts.slice();
                      targetProd.variants[vIdx].stock = ev.data.accounts.length;
                    } else if (vIdx === null) {
                      targetProd.accounts = ev.data.accounts.slice();
                      targetProd.stock = ev.data.accounts.length;
                    }
                  } else if (typeof ev.data.stock === "number" && vIdx !== null && Array.isArray(targetProd.variants) && targetProd.variants[vIdx]) {
                    targetProd.variants[vIdx].stock = ev.data.stock;
                  }
                  if (typeof ev.data.totalStock === "number") {
                    targetProd.stock = ev.data.totalStock;
                  } else {
                    targetProd.stock = Array.isArray(targetProd.variants) && targetProd.variants.length > 0
                      ? targetProd.variants.reduce((s, v) => s + ((v && Array.isArray(v.accounts)) ? v.accounts.length : (Number(v && v.stock) || 0)), 0)
                      : (Array.isArray(targetProd.accounts) ? targetProd.accounts.length : (Number(targetProd.stock) || 0));
                  }
                  if (typeof recordProductVariants === "function" && Array.isArray(targetProd.variants)) {
                    recordProductVariants(targetProd.id, targetProd.variants, targetProd.name);
                  }
                }
              }
            } catch(e2) {}
            // Cập nhật tức thì trang chi tiết sản phẩm nếu đang mở
            if (typeof currentSelectedProduct !== "undefined" && currentSelectedProduct && 
                ((typeof isSameOrAliasProduct === "function" && isSameOrAliasProduct(currentSelectedProduct.id, ev.data.prodId)) || 
                 (currentSelectedProduct.name && ev.data.prodData && typeof isSameOrAliasProduct === "function" && isSameOrAliasProduct(currentSelectedProduct.name, ev.data.prodData.name)))) {
              const freshP = findShopProduct(ev.data.prodId) || currentSelectedProduct;
              if (Array.isArray(ev.data.variants)) {
                freshP.variants = JSON.parse(JSON.stringify(ev.data.variants));
                currentSelectedProduct.variants = JSON.parse(JSON.stringify(ev.data.variants));
              }
              if (typeof ev.data.totalStock === "number") {
                freshP.stock = ev.data.totalStock;
                currentSelectedProduct.stock = ev.data.totalStock;
              }
              currentSelectedProduct = freshP;
              const curVarIdx = (typeof currentSelectedVariantIndex !== "undefined") ? currentSelectedVariantIndex : 0;
              const hasVars = Array.isArray(freshP.variants) && freshP.variants.length > 0;
              const activeStock = getShopVariantStock(freshP, hasVars ? curVarIdx : null);
              if (typeof syncDetailStockUI === "function") syncDetailStockUI(activeStock);

              const pillsContainer = document.getElementById("dtlVariantPills");
              if (pillsContainer && hasVars) {
                pillsContainer.innerHTML = freshP.variants.map((v, idx) => {
                  const vs = getShopVariantStock(freshP, idx);
                  const badge = vs > 0 
                    ? '<small style="color:#10b981; font-weight:700; margin-left:6px; font-size:0.75rem;">(' + vs + ' acc)</small>' 
                    : '<small style="color:#ef4444; font-weight:700; margin-left:6px; font-size:0.75rem;">(0 acc)</small>';
                  return '<div class="variant-pill-option ' + (idx === curVarIdx ? 'active' : '') + '" onclick="selectVariant(' + idx + ', ' + (v.price || 0) + ')">' +
                    '<span>' + escapeHtml(v.name || ('Gói ' + (idx + 1))) + badge + '</span>' +
                    '<span style="font-weight:700;">' + formatVND(v.price || 0) + '</span>' +
                  '</div>';
                }).join("");
              }
            }
            if (typeof syncAllOpenViewsStock === "function") syncAllOpenViewsStock(ev.data.prodId, ev.data.stock, ev.data.accounts || null, true, ev.data.variantIdx);
            const selectEl = document.getElementById("admStockProductSelect");
            if (selectEl && selectEl.value && (String(selectEl.value) === String(ev.data.prodId) || (typeof isSameOrAliasProduct === "function" && isSameOrAliasProduct(selectEl.value, ev.data.prodId)))) {
              const currentView = document.getElementById("admStockCurrentView");
              const bulkInput = document.getElementById("admStockBulkInput");
              const isTyping = (document.activeElement === currentView || document.activeElement === bulkInput);
              if (!isTyping) {
                if (typeof updateVariantSelectForProduct === "function") updateVariantSelectForProduct(selectEl.value);
                if (typeof handleStockVariantChange === "function") handleStockVariantChange();
              }
            }
            if (typeof _viewDirty !== "undefined") {
              _viewDirty["viewStore"] = true;
              _viewDirty["viewAllProducts"] = true;
              _viewDirty["viewAdmin"] = true;
            }
          }
          if (ev && ev.data && ev.data.type === "PRODUCT_DELETED") {
            const delId = String(ev.data.prodId || "");
            const delName = ev.data.prodName || "";
            if (delId) {
              let deletedIds = (typeof getDeletedProductIds === "function") ? getDeletedProductIds() : [];
              if (!deletedIds.includes(delId)) deletedIds.push(delId);
              localStorage.setItem("mmo_deleted_product_ids", JSON.stringify(deletedIds));
            }
            if (MOCK_DATA && Array.isArray(MOCK_DATA.products)) {
              MOCK_DATA.products = MOCK_DATA.products.filter(p => p && String(p.id) !== delId && (delName ? p.name !== delName : true));
            }
            if (typeof currentSelectedProduct !== "undefined" && currentSelectedProduct && (String(currentSelectedProduct.id) === delId || (delName && currentSelectedProduct.name === delName))) {
              currentSelectedProduct = null;
              try {
                const u = new URL(window.location.href);
                u.searchParams.delete("prod");
                u.searchParams.delete("product");
                window.history.replaceState(null, "", u.pathname + (u.searchParams.toString() ? '?' + u.searchParams.toString() : ''));
              } catch(e) {}
              if (typeof switchView === "function") switchView("viewStore");
            }
            if (typeof renderProductGrid === "function") renderProductGrid();
            if (typeof renderCategories === "function") renderCategories();
            if (typeof renderBestSellers === "function") renderBestSellers();
            if (typeof renderRecommended === "function") renderRecommended();
            if (typeof renderAllProductsPage === "function") renderAllProductsPage();
            if (typeof refreshAllShopStockUI === "function") refreshAllShopStockUI();
          }
          if (ev && ev.data && ev.data.type === "PRODUCT_UPDATED") {
            const updId = ev.data.prodId;
            const updVariants = ev.data.variants;
            const updData = ev.data.prodData;
            if (typeof loadPersistedProducts === "function") loadPersistedProducts();
            if (typeof MOCK_DATA !== "undefined" && MOCK_DATA.products) {
              const target = MOCK_DATA.products.find(p => p.id === updId || (p.name && updData && p.name.trim().toLowerCase() === updData.name.trim().toLowerCase()));
              if (target && updData) {
                Object.assign(target, updData);
                if (updVariants) target.variants = updVariants;
                if (ev.data.stock !== undefined) target.stock = ev.data.stock;
              }
            }
            if (typeof currentSelectedProduct !== "undefined" && currentSelectedProduct) {
              if (String(currentSelectedProduct.id) === String(updId) || (currentSelectedProduct.name && updData && currentSelectedProduct.name.trim().toLowerCase() === updData.name.trim().toLowerCase())) {
                if (updData) Object.assign(currentSelectedProduct, updData);
                if (updVariants) currentSelectedProduct.variants = updVariants;
                if (ev.data.stock !== undefined) currentSelectedProduct.stock = ev.data.stock;
                if (currentSelectedVariantIndex >= (currentSelectedProduct.variants ? currentSelectedProduct.variants.length : 1)) {
                  currentSelectedVariantIndex = 0;
                }
              }
            }
            if (typeof syncAllOpenViewsStock === "function") syncAllOpenViewsStock(updId, ev.data.stock, null, true);
            const dtlViewEl = document.getElementById("viewProductDetail");
            if (dtlViewEl && dtlViewEl.style.display !== "none" && !dtlViewEl.classList.contains("hidden")) {
              if (currentSelectedProduct && (String(currentSelectedProduct.id) === String(updId) || (currentSelectedProduct.name && updData && currentSelectedProduct.name.trim().toLowerCase() === updData.name.trim().toLowerCase()))) {
                if (typeof openProductDetailById === "function") openProductDetailById(updId);
              } else {
                if (typeof renderDetailRelatedProducts === "function" && currentSelectedProduct) renderDetailRelatedProducts(currentSelectedProduct);
              }
            }
            if (typeof renderProductGrid === "function") renderProductGrid();
            if (typeof renderBestSellers === "function") renderBestSellers();
            if (typeof renderRecommended === "function") renderRecommended();
            if (typeof renderAdminProductsTable === "function") renderAdminProductsTable();
          }
        };
      }
    } catch(e) {}

    if (typeof window !== "undefined") {
      var _mmoStorageDebounceTimer = null;
      window.addEventListener("storage", function(e) {
        if (!e || !e.key || (!e.key.startsWith("mmo_") && e.key.indexOf("mmo_") === -1)) return;
        
        clearTimeout(_mmoStorageDebounceTimer);
        _mmoStorageDebounceTimer = setTimeout(function() {
          try {
            if (e.key === "mmo_user") {
              try {
                const stored = localStorage.getItem("mmo_user");
                if (stored) currentUser = JSON.parse(stored);
              } catch(errUser) {}
              if (typeof updateUserUI === "function") updateUserUI();
              if (typeof loadStoredUser === "function") loadStoredUser();
            }

            if (e.key === "mmo_warehouse" || e.key === "mmo_admin_products" || e.key === "mmo_products_stock" || e.key === "mmo_stock_items" || e.key === "mmo_product_variants_map" || e.key === "mmo_deleted_product_ids") {
              if (typeof loadPersistedProducts === "function") loadPersistedProducts();
              // Truyền isFromBroadcast=true để không gửi ngược lại BroadcastChannel, chống nghẽn vòng lặp
              if (typeof syncAllOpenViewsStock === "function") syncAllOpenViewsStock(null, null, null, true);
            }

            if (e.key === "mmo_user_orders") {
              if (typeof renderProfileOrders === "function") renderProfileOrders();
            }

            if (e.key === "mmo_transaction_history") {
              if (typeof renderUserBalanceLogs === "function") renderUserBalanceLogs();
              if (typeof renderUserWalletTransactions === "function") renderUserWalletTransactions();
            }
          } catch(err) {
            console.warn("Storage sync error:", err);
          }
        }, 120);
      });
    }

    // =========================================================================
    // REAL-TIME LIVE CLOCK & DATE (FOOTER)
    // =========================================================================
    var _clockInterval = null;
    function updateLiveRealTimeClock() {
      if (_clockInterval) return;
      function tick() {
        const timeEl = document.getElementById("liveClockTime");
        const dateEl = document.getElementById("liveClockDate");
        if (!timeEl && !dateEl) return;
        const now = new Date();
        if (timeEl) {
          const hh = String(now.getHours()).padStart(2, "0");
          const mm = String(now.getMinutes()).padStart(2, "0");
          const ss = String(now.getSeconds()).padStart(2, "0");
          timeEl.innerText = hh + ":" + mm + ":" + ss;
        }
        if (dateEl) {
          const days = ["Chủ Nhật", "Thứ Hai", "Thứ Ba", "Thứ Tư", "Thứ Năm", "Thứ Sáu", "Thứ Bảy"];
          const dayName = days[now.getDay()];
          const dd = String(now.getDate()).padStart(2, "0");
          const mo = String(now.getMonth() + 1).padStart(2, "0");
          const yy = now.getFullYear();
          dateEl.innerText = dayName + ", " + dd + "/" + mo + "/" + yy;
        }
      }
      tick();
      _clockInterval = setInterval(tick, 1000);
    }
    window.updateLiveRealTimeClock = updateLiveRealTimeClock;
    updateLiveRealTimeClock();

    function initMMOApplication() {
      if (window._mmoAppFullyInitialized) {
        if (typeof ensureUniversalComponentsExist === "function") ensureUniversalComponentsExist();
        if (typeof renderHeaderNotifications === "function") renderHeaderNotifications();
        return;
      }
      window._mmoAppFullyInitialized = true;
      window._mmoCdnAppBooted = true;
      try {
        if (typeof syncCloudOrdersToLocalUI === "function") {
          syncCloudOrdersToLocalUI(true);
        }
        setInterval(function() {
          if (typeof syncCloudOrdersToLocalUI === "function") {
            syncCloudOrdersToLocalUI(false);
          }
        }, 12000);
      } catch(e) {}

      const gBtn = document.getElementById("btnGoogleCustom");
      if (gBtn) {
        gBtn.addEventListener("click", function(e) {
          e.preventDefault();
          triggerGoogleSignIn();
        });
      }
      if (typeof loadStoredUser === "function") loadStoredUser();
      if (typeof applyBrandCustomizations === "function") applyBrandCustomizations();
      if (typeof syncZaloLinks === "function") syncZaloLinks();
      if (typeof syncTelegramLinks === "function") syncTelegramLinks();
      if (typeof syncMarqueeNotice === "function") syncMarqueeNotice();
      if (typeof loadGeneralSettingsUI === "function") loadGeneralSettingsUI();

      // Đăng ký nhận sự kiện cập nhật cấu hình tức thì từ các tab khác
      try {
        if (typeof BroadcastChannel !== "undefined") {
          const settingsBc = new BroadcastChannel("mmo_settings_channel");
          settingsBc.onmessage = function(ev) {
            if (ev && ev.data && ev.data.type === "SETTINGS_UPDATED" && ev.data.settings) {
              const s = ev.data.settings;
              if (typeof applyBrandCustomizations === "function") applyBrandCustomizations(s);
              if (typeof syncZaloLinks === "function") syncZaloLinks(s.hotline);
              if (typeof syncTelegramLinks === "function") syncTelegramLinks(s.telegram);
              if (typeof syncMarqueeNotice === "function") syncMarqueeNotice(s.marqueeText);
              if (typeof loadGeneralSettingsUI === "function") loadGeneralSettingsUI();
            }
          };
        }
      } catch(e) {}
      if (typeof renderDynamicFlankingProducts === "function") renderDynamicFlankingProducts();
      if (typeof renderCategories === "function") renderCategories();
      if (typeof renderBestSellers === "function") renderBestSellers();
      if (typeof renderRecommended === "function") renderRecommended();
      if (typeof renderProductGrid === "function") renderProductGrid();
      if (typeof renderSidebarBlogs === "function") renderSidebarBlogs();
      if (typeof _viewRendered !== "undefined") _viewRendered["viewStore"] = true;
      setTimeout(function() {
        const bList = document.getElementById("bestSellerList");
        const rGrid = document.getElementById("recommendedGrid");
        if ((!bList || bList.children.length === 0) && typeof renderBestSellers === "function") {
          renderBestSellers();
        }
        if ((!rGrid || rGrid.children.length === 0) && typeof renderRecommended === "function") {
          renderRecommended();
        }
      }, 50);
      setTimeout(function() {
        const bList = document.getElementById("bestSellerList");
        const rGrid = document.getElementById("recommendedGrid");
        if ((!bList || bList.children.length === 0) && typeof renderBestSellers === "function") {
          renderBestSellers();
        }
        if ((!rGrid || rGrid.children.length === 0) && typeof renderRecommended === "function") {
          renderRecommended();
        }
      }, 250);
      if (typeof updateLiveRealTimeClock === "function") updateLiveRealTimeClock();
      if (typeof initPreOrdersRealtimeSSE === "function") initPreOrdersRealtimeSSE();
      // Polling dự phòng đơn hàng thời gian thực cho Admin mỗi 45 giây (chỉ khi mở tab viewAdmin)
      if (!window._mmoAdminOrdersRealtimePollTimer) {
        window._mmoAdminOrdersRealtimePollTimer = setInterval(function() {
          if (typeof isAdminUser === "function" && isAdminUser() && !document.hidden) {
            const curV = typeof currentView !== "undefined" ? currentView : (localStorage.getItem("mmo_current_view") || "");
            if (curV !== "viewAdmin") return;
            if (typeof MMO_WORKER_API !== "undefined" && typeof MMO_WORKER_API.getApiUrl === "function") {
              fetch(MMO_WORKER_API.getApiUrl() + "/api/orders?limit=30")
                .then(r => r.json())
                .then(data => {
                  if (data && data.success && Array.isArray(data.orders)) {
                    let hasNew = false;
                    const curPre = getPreOrders(true);
                    data.orders.forEach(o => {
                      const oCode = String(o.orderCode || o.id || o.orderId || "").replace("#","").toLowerCase();
                      if (oCode.startsWith("pre") && !curPre.some(p => String(p.orderCode || p.id).replace("#","").toLowerCase() === oCode)) {
                        curPre.unshift(o);
                        hasNew = true;
                      }
                    });
                    if (hasNew) {
                      savePreOrders(curPre);
                      if (typeof updateAdminPreOrdersBadge === "function") updateAdminPreOrdersBadge();
                      if (typeof renderAdminPreOrdersTable === "function") renderAdminPreOrdersTable();
                      if (typeof renderAdminOrdersTable === "function") renderAdminOrdersTable();
                      if (typeof playNotificationSound === "function") playNotificationSound();
                    }
                  }
                }).catch(function() {});
            }
          }
        }, 45000);
      }
      if (typeof initGoogleAuth === "function") initGoogleAuth();
      if (typeof initTursoUI === "function") initTursoUI();
      if (typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured()) {
        setTimeout(function() {
          syncTursoProductsToLocalUI().then(() => {
            return syncTursoStockToLocalUI();
          }).catch(e => console.error("Turso init sync error:", e));
        }, 150);
      }
      // Tự động tải sản phẩm mới nhất từ máy chủ để mọi người xem được ngay
      const _urlHasProd = window.location.search && (window.location.search.includes("prod=") || window.location.search.includes("product=") || window.location.search.includes("view=viewProductDetail"));
      setTimeout(function() {
        if (typeof syncProductsFromBackend === "function") {
          syncProductsFromBackend();
        }
        if (typeof syncAdminEmailsFromCloud === "function") {
          syncAdminEmailsFromCloud();
        }
      }, _urlHasProd ? 200 : 1500);

      // RESTORE CURRENT ACTIVE VIEW AND SUB-TABS ON F5 REFRESH
      try {
        let targetView = "viewStore";
        const hash = (window.location.hash || "").replace("#", "").trim();
        const savedView = localStorage.getItem("mmo_current_view");
        const urlParams = new URLSearchParams(window.location.search);
        const hasProdParam = !!(urlParams.get("prod") || urlParams.get("product") || (hash.startsWith("product_")));
        const hasBlogParam = !!(urlParams.get("post") || urlParams.get("blog"));
        
        const validViews = ["viewStore", "viewProductDetail", "viewBlog", "viewBlogDetail", "viewTools", "viewProfile", "viewDeposit", "viewAdmin", "viewAllProducts", "viewSitemap", "viewTerms", "viewPrivacy", "viewWarranty"];
        const viewParam = urlParams.get("view");
        const catParam = urlParams.get("category");
        if (hash === "viewPrivacy" || hash === "privacy" || viewParam === "viewPrivacy" || (viewParam === "viewTerms" && (hash === "viewPrivacy" || hash === "privacy"))) {
          targetView = "viewPrivacy";
        } else if (hash === "viewTerms" || hash === "terms" || viewParam === "viewTerms") {
          targetView = "viewTerms";
        } else if (hasProdParam) {
          targetView = "viewProductDetail";
        } else if (hasBlogParam) {
          targetView = "viewBlogDetail";
        } else if (viewParam && validViews.includes(viewParam)) {
          targetView = viewParam;
        } else if (hash && validViews.includes(hash) && hash !== "viewProductDetail") {
          targetView = hash;
        } else if (savedView && validViews.includes(savedView) && savedView !== "viewProductDetail") {
          targetView = savedView;
        } else {
          targetView = "viewStore";
        }
        if (catParam && typeof filterCategory === "function") {
          setTimeout(function() { filterCategory(catParam); }, 80);
        }

        if (targetView === "viewBlogDetail") {
          const targetBlogId = urlParams.get("post") || urlParams.get("blog") || localStorage.getItem("mmo_current_blog_id");
          if (typeof openBlogDetail === "function") {
            openBlogDetail(targetBlogId);
          } else {
            switchView("viewBlogDetail");
          }
        } else if (targetView && targetView !== "viewStore") {
          const storedUser = localStorage.getItem("mmo_user");
          if ((targetView === "viewProfile" || targetView === "viewAdmin" || targetView === "viewDeposit") && !storedUser) {
            targetView = "viewStore";
          }
          switchView(targetView);
        } else {
          switchView("viewStore");
        }
        updateUserUI();

        if (targetView === "viewAdmin") {
          const savedAdminTab = localStorage.getItem("mmo_admin_tab") || "tabAdmDashboard";
          if (savedAdminTab && typeof switchAdminTab === "function") {
            switchAdminTab(savedAdminTab);
          }
        } else if (targetView === "viewProfile") {
        if (typeof loadUserWalletFromCloud === "function") loadUserWalletFromCloud();
          const savedProfTab = localStorage.getItem("mmo_profile_tab");
          if (savedProfTab && typeof switchProfileTab === "function") {
            switchProfileTab(savedProfTab);
          }
        }
      } catch(e) {}
    }
    window.initMMOApplication = initMMOApplication;
    if (typeof document !== "undefined") {
      document.addEventListener("DOMContentLoaded", function() {
        setTimeout(initMMOApplication, 0);
      });
    }

    if (typeof window !== "undefined") {
      window.addEventListener("resize", function() {
        clearTimeout(window._mobileGridResizeTimer);
        window._mobileGridResizeTimer = setTimeout(function() {
          if (typeof renderRecommended === "function") renderRecommended();
          if (typeof renderProductGrid === "function") renderProductGrid();
        }, 250);
      });
    }

    if (typeof window !== "undefined") {
      window.addEventListener("hashchange", function() {
        const hash = (window.location.hash || "").replace("#", "").trim();
        const validViews = ["viewStore", "viewProductDetail", "viewBlog", "viewBlogDetail", "viewTools", "viewProfile", "viewDeposit", "viewAdmin", "viewAllProducts", "viewSitemap", "viewTerms", "viewPrivacy", "viewWarranty"];
        if (hash && (hash === "viewPrivacy" || hash === "privacy")) {
          switchView("viewPrivacy");
        } else if (hash && validViews.includes(hash)) {
          switchView(hash);
        }
      });
    }

    

    window.openProductDetailById = openProductDetailById;

    window.selectVariant = selectVariant;

    window.changeDtlQty = changeDtlQty;

    window.openAuthModal = openAuthModal;

    window.switchAuthTab = switchAuthTab;
    window.handleRequestPasswordReset = handleRequestPasswordReset;
    window.handleResendForgotOtp = handleResendForgotOtp;
    window.handleConfirmPasswordReset = handleConfirmPasswordReset;

    window.prepareDeposit = prepareDeposit;

    window.switchView = switchView;

    function renderSitemapView() {
      const container = document.getElementById("sitemapProductList");
      if (!container) return;
      const prods = (MOCK_DATA && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products : [];
      container.innerHTML = prods.map(p => {
        return '<div style="border-bottom:1px solid #1e293b; padding-bottom:8px;">' +
          '<a href="?prod=' + encodeURIComponent(p.id) + '&view=viewProductDetail" target="_blank" style="color:#e2e8f0; text-decoration:none; font-size:0.85rem; display:flex; justify-content:space-between; align-items:center; gap:8px;">' +
            '<span style="font-weight:600;"><i class="fa-solid fa-box" style="color:#10b981; font-size:0.75rem; margin-right:6px;"></i>' + escapeHtml(p.name) + '</span>' +
            '<span style="color:#38bdf8; font-weight:700; white-space:nowrap;">' + formatVND(p.price || 0) + '</span>' +
          '</a>' +
        '</div>';
      }).join("");
    }
    window.renderSitemapView = renderSitemapView;

    // [SEO GOOGLE INDEX]: Tự động khai báo danh mục tất cả sản phẩm dưới dạng Schema ItemList cho Googlebot
function injectAllProductsSchema() {
      try {
        // Nếu đang ở URL chi tiết sản phẩm, xóa bỏ schemaAllProductsItemList để Googlebot chỉ thấy DUY NHẤT 1 AggregateRating
        const urlParams = new URLSearchParams(window.location.search);
        if (urlParams.get("prod") || urlParams.get("product") || (window.location.hash && window.location.hash.startsWith("#product_"))) {
          const s = document.getElementById("schemaAllProductsItemList");
          if (s) s.remove();
          return;
        }

        const prods = (MOCK_DATA && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products : [];
        if (prods.length === 0) return;
        const deletedIds = (typeof getDeletedProductIds === "function") ? getDeletedProductIds() : [];
        const visibleProds = prods.filter(p => p && p.id && !deletedIds.includes(p.id));
        if (visibleProds.length === 0) return;

        let scriptEl = document.getElementById("schemaAllProductsItemList");
        if (!scriptEl) {
          scriptEl = document.createElement("script");
          scriptEl.id = "schemaAllProductsItemList";
          scriptEl.type = "application/ld+json";
          document.head.appendChild(scriptEl);
        }
        const baseUrl = window.location.origin + window.location.pathname;
        const siteUrl = "https://www.muabantaikhoanmmo.com/";

        const prodShippingDetails = {
          "@type": "OfferShippingDetails",
          "shippingRate": { "@type": "MonetaryAmount", "value": "0", "currency": "VND" },
          "shippingDestination": { "@type": "DefinedRegion", "addressCountry": "VN" },
          "deliveryTime": {
            "@type": "ShippingDeliveryTime",
            "handlingTime": { "@type": "QuantitativeValue", "minValue": 0, "maxValue": 0, "unitCode": "DAY" },
            "transitTime": { "@type": "QuantitativeValue", "minValue": 0, "maxValue": 0, "unitCode": "DAY" }
          }
        };
        const prodReturnPolicy = {
          "@type": "MerchantReturnPolicy",
          "applicableCountry": "VN",
          "returnPolicyCategory": "https://schema.org/MerchantReturnFiniteReturnWindow",
          "merchantReturnDays": 1,
          "returnMethod": "https://schema.org/ReturnByMail",
          "returnFees": "https://schema.org/FreeReturn"
        };

        const graphSchema = {
          "@context": "https://schema.org",
          "@graph": [
            {
              "@type": "WebSite",
              "@id": siteUrl + "#website",
              "url": siteUrl,
              "name": "MUABANTAIKHOANMMO.COM",
              "description": "He thong mua ban tai khoan mang xa hoi, cong cu MMO, proxy tu dong 24/7 uy tin so 1 Viet Nam",
              "publisher": { "@id": siteUrl + "#organization" }
            },
            {
              "@type": "Organization",
              "@id": siteUrl + "#organization",
              "name": "MUABANTAIKHOANMMO.COM",
              "url": siteUrl,
              "logo": { "@type": "ImageObject", "url": "https://iili.io/nFV4Rln.png" }
            },
            {
              "@type": "ItemList",
              "@id": siteUrl + "#productlist",
              "name": "Danh Sach San Pham Tai Khoan MMO - MUABANTAIKHOANMMO.COM",
              "numberOfItems": visibleProds.length,
              "itemListElement": visibleProds.map((p, idx) => {
                const prodUrl = baseUrl + "?prod=" + encodeURIComponent(p.id) + "&view=viewProductDetail";
                const price = (p.variants && p.variants[0] && p.variants[0].price) ? p.variants[0].price : (p.price || 0);
                const imgUrl = (typeof resolveProductSeoSchemaImage === "function") ? resolveProductSeoSchemaImage(p) : ((p.image && !p.image.startsWith("data:")) ? p.image : "https://iili.io/nFV4Rln.png");
                return {
                  "@type": "ListItem",
                  "position": idx + 1,
                  "item": {
                    "@type": "Product",
                    "@id": prodUrl + "#product",
                    "name": p.name,
                    "description": (p.description || ("Mua " + p.name + " tu dong 24/7 uy tin, gia re nhat Viet Nam.")).slice(0, 300),
                    "url": prodUrl,
                    "image": [imgUrl],
                    "sku": p.id,
                    "mpn": p.id,
                    "identifier_exists": "false",
                    "brand": { "@type": "Brand", "name": "MUABANTAIKHOANMMO" },
                    "category": p.category || "Tai Khoan MMO",
                    "offers": {
                      "@type": "Offer",
                      "url": prodUrl,
                      "priceCurrency": "VND",
                      "price": price,
                      "priceValidUntil": "2027-12-31",
                      "validFrom": "2026-01-01",
                      "availability": (p.stock > 0) ? "https://schema.org/InStock" : "https://schema.org/OutOfStock",
                      "itemCondition": "https://schema.org/NewCondition",
                      "seller": { "@type": "Organization", "name": "MUABANTAIKHOANMMO.COM" },
                      "shippingDetails": prodShippingDetails,
                      "hasMerchantReturnPolicy": prodReturnPolicy
                    }
                  }
                };
              })
            }
          ]
        };
        scriptEl.textContent = JSON.stringify(graphSchema);
      } catch(e) { console.warn("injectAllProductsSchema error:", e); }
    }
    window.injectAllProductsSchema = injectAllProductsSchema;

    // SEO CHUM: Render related products widget
    function renderRelatedProductsSeo(currentProduct) {
      try {
        const container = document.getElementById("dtlSeoRelatedProducts");
        if (!container) return;
        const prods = (MOCK_DATA && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products : [];
        const deletedIds = (typeof getDeletedProductIds === "function") ? getDeletedProductIds() : [];
        const related = prods.filter(p =>
          p && p.id && p.id !== currentProduct.id &&
          !deletedIds.includes(p.id) &&
          p.category === currentProduct.category
        ).slice(0, 6);

        if (related.length === 0) { container.style.display = "none"; return; }
        container.style.display = "block";
        const baseUrl = window.location.origin + window.location.pathname;
        const relItems = related.map(rp => {
          const rpUrl = baseUrl + "?prod=" + encodeURIComponent(rp.id) + "&view=viewProductDetail";
          const rpPrice = (rp.variants && rp.variants[0] && rp.variants[0].price) ? rp.variants[0].price : (rp.price || 0);
          const rpStock = (typeof getProductStockCount === "function") ? getProductStockCount(rp) : (rp.stock || 0);
          const rpPriceStr = (typeof formatVND === "function") ? formatVND(rpPrice) : rpPrice.toLocaleString("vi-VN") + "d";
          const eName = (typeof escapeHtml === "function") ? escapeHtml(rp.name) : rp.name.replace(/</g,"&lt;").replace(/>/g,"&gt;");
          return '<a href="' + rpUrl + '" onclick="event.preventDefault(); openProductDetailById(\'' + rp.id + '\')" '
            + 'style="display:block; background:#0d121f; border:1px solid #1e293b; border-radius:8px; padding:8px; text-decoration:none;" '
            + 'rel="noopener" title="' + eName + '">'
            + '<img src="' + (rp.image || "https://iili.io/nFV4Rln.png") + '" alt="' + eName + '" '
            + 'style="width:100%; height:70px; object-fit:cover; border-radius:5px; margin-bottom:6px;" loading="lazy"/>'
            + '<div style="font-size:0.72rem; color:#cbd5e1; line-height:1.3; margin-bottom:4px;">' + eName + '</div>'
            + '<div style="font-size:0.75rem; color:#10b981; font-weight:700;">' + rpPriceStr + '</div>'
            + '<div style="font-size:0.65rem; color:' + (rpStock > 0 ? '#10b981' : '#ef4444') + ';">' + (rpStock > 0 ? 'Con hang' : 'Het hang') + '</div>'
            + '</a>';
        }).join("");
        container.innerHTML = '<div style="margin-top:20px; border-top:1px solid #1e293b; padding-top:16px;">'
          + '<h3 style="font-size:0.92rem; color:#38bdf8; margin-bottom:12px; display:flex; align-items:center; gap:6px;">'
          + '<i class="fa-solid fa-layer-group"></i> San Pham Lien Quan</h3>'
          + '<div style="display:grid; grid-template-columns:repeat(auto-fill,minmax(140px,1fr)); gap:8px;">'
          + relItems + '</div></div>';
      } catch(e) {}
    }
    window.renderRelatedProductsSeo = renderRelatedProductsSeo;



    window.formatVND = formatVND;

    window.toggleLockUser = toggleLockUser;

    window.handleRemoveAdminEmail = handleRemoveAdminEmail;

