async function callAiChatService(pKey, modelId, promptText, sysPrompt, maxTokens = 4096) {
  const prov = AI_PROVIDERS[pKey] || AI_PROVIDERS.groq;
  let apiKey = MMO_AI_KEYS.get(pKey);
  if (!apiKey) {
    throw new Error('Chưa có API Key cho ' + prov.name + '. Vui lòng bấm link bên dưới lấy key miễn phí và bấm Lưu!');
  }

  const effectiveMaxTokens = Math.min(maxTokens || 8192, 8192);

  if (prov.isOpenAiFormat) {
    const headers = {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + apiKey
    };
    if (prov.extraHeaders) Object.assign(headers, prov.extraHeaders);
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 45000);
    const res = await fetch(prov.endpoint, {
      method: 'POST',
      headers: headers,
      signal: controller.signal,
      body: JSON.stringify({
        model: modelId || prov.defaultModel,
        messages: [
          { role: 'system', content: sysPrompt || 'Bạn là chuyên gia SEO Content Writer tiếng Việt hàng đầu.' },
          { role: 'user', content: promptText }
        ],
        temperature: 0.7,
        max_tokens: effectiveMaxTokens
      })
    });
    clearTimeout(timeoutId);
    if (!res.ok) {
      const errText = await res.text();
      // XỬ LÝ THÔNG MINH CHO LỖI 429 RATE LIMIT HOẶC HẾT QUOTA
      if (res.status === 429) {
        if (pKey === 'mistral' && modelId !== 'open-mistral-7b') {
          // Tự động thử lại với model nhẹ hơn open-mistral-7b sau 1.2s
          try {
            await new Promise(r => setTimeout(r, 1200));
            const retryRes = await fetch(prov.endpoint, {
              method: 'POST',
              headers: headers,
              body: JSON.stringify({
                model: 'open-mistral-7b',
                messages: [
                  { role: 'system', content: sysPrompt || 'Bạn là chuyên gia SEO Content Writer tiếng Việt hàng đầu.' },
                  { role: 'user', content: promptText }
                ],
                temperature: 0.7,
                max_tokens: 2048
              })
            });
            if (retryRes.ok) {
              const retryJson = await retryRes.json();
              const rReply = retryJson.choices && retryJson.choices[0] && retryJson.choices[0].message ? retryJson.choices[0].message.content : '';
              if (rReply) return rReply;
            }
          } catch(e) {}
        }
        throw new Error(prov.name + ' Error 429 (Hết Quota/Vượt giới hạn Free): Tài khoản của bạn đã đạt hạn mức truy vấn. Hãy đổi sang ⚡ Groq (Llama 3.3 70B) hoặc 🤖 Google Gemini để viết bài miễn phí siêu tốc!');
      }
      throw new Error(prov.name + ' Error ' + res.status + ': ' + errText.slice(0, 220));
    }
    const json = await res.json();
    const reply = json.choices && json.choices[0] && json.choices[0].message ? json.choices[0].message.content : '';
    if (!reply) throw new Error(prov.name + ' không phản hồi nội dung.');
    return reply;
  } else {
    let targetModels = [];
    if (modelId) {
      // Map old deprecated names
      let m = modelId;
      if (m === 'gemini-1.5-flash' || m === 'gemini-2.0-flash') m = 'gemini-2.5-flash';
      targetModels.push(m);
    }
    const fallbackList = ['gemini-2.5-flash', 'gemini-1.5-flash-latest', 'gemini-2.0-flash-exp', 'gemini-1.5-flash', 'gemini-1.5-pro-latest'];
    for (const fb of fallbackList) {
      if (!targetModels.includes(fb)) targetModels.push(fb);
    }

    let lastErrText = '';
    for (const curModel of targetModels) {
      const apiVersions = ['v1beta', 'v1'];
      for (const apiVer of apiVersions) {
        try {
          const url = `https://generativelanguage.googleapis.com/${apiVer}/models/${curModel}:generateContent?key=${apiKey}`;
          const controller = new AbortController();
          const timeoutId = setTimeout(() => controller.abort(), 45000);
          const res = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            signal: controller.signal,
            body: JSON.stringify({
              contents: [{ parts: [{ text: (sysPrompt ? sysPrompt + "\n\n" : "") + promptText }] }],
              generationConfig: { maxOutputTokens: effectiveMaxTokens, temperature: 0.7 }
            })
          });
          clearTimeout(timeoutId);
          if (res.ok) {
            const json = await res.json();
            const reply = json.candidates && json.candidates[0] && json.candidates[0].content && json.candidates[0].content.parts && json.candidates[0].content.parts[0] ? json.candidates[0].content.parts[0].text : '';
            if (reply) return reply;
          } else {
            const errBody = await res.text();
            lastErrText = errBody;
            if (res.status === 429) {
              throw new Error('Gemini Quota Exceeded (429): Quota tài khoản Gemini của bạn đã hết. Vui lòng đổi sang nền tảng ⚡ Groq (Llama 3.3 70B) để viết bài miễn phí siêu tốc!');
            }
            if (res.status === 400 && errBody.includes('API_KEY_INVALID')) {
              throw new Error('Gemini API Key không hợp lệ. Vui lòng kiểm tra lại key trong Cấu hình AI.');
            }
          }
        } catch(eCur) {
          if (eCur.message && (eCur.message.includes('Quota') || eCur.message.includes('API_KEY_INVALID'))) {
            throw eCur;
          }
          lastErrText = eCur.message;
        }
      }
    }
    throw new Error('Gemini Error: ' + (lastErrText ? lastErrText.slice(0, 220) : 'Tất cả model Gemini đều không phản hồi. Vui lòng kiểm tra lại API Key hoặc đổi sang Groq.'));
  }
}

async function autoSuggestKeywordsOnly() {
  const topicEl = document.getElementById('aiTopic');
  const kwInput = document.getElementById('aiKeywords');
  let topic = (topicEl || {}).value || '';
  let curKw = (kwInput || {}).value || '';

  if (!topic.trim() && curKw.trim()) {
    topic = curKw.trim().split(',')[0].trim();
    if (topicEl) topicEl.value = topic;
  }

  if (!topic.trim()) {
    showToast('⚠️ Vui lòng nhập Tiêu Đề hoặc Từ Khóa trước khi bấm Gợi ý!', 'warn');
    if (topicEl) topicEl.focus();
    return;
  }
  const statusEl = document.getElementById('aiGenerateStatus');
  const pSel = document.getElementById('aiProviderSelect');
  const mSel = document.getElementById('aiModelSelect');
  const pKey = pSel ? pSel.value : 'groq';
  const modelId = mSel ? mSel.value : '';

  if (statusEl) statusEl.innerHTML = '<span style="color:#a855f7;">⏳ Đang phân tích từ khóa SEO tối ưu...</span>';
  try {
    const prompt = `Phân tích chủ đề sau: "${topic}". Hãy trích xuất và đề xuất bộ 3-5 từ khóa SEO quan trọng nhất (bao gồm 1 từ khóa chính và 2-4 từ khóa phụ LSI liên quan chặt chẽ), phân cách bằng dấu phẩy. Chỉ trả về các từ khóa phân cách bằng dấu phẩy, không thêm bất kỳ lời dẫn hay dấu ngoặc nào.`;
    const resText = await callAiChatService(pKey, modelId, prompt, "Bạn là chuyên gia nghiên cứu từ khóa SEO Google tiếng Việt.");
    const cleaned = resText.replace(/^[\r\n\s]+|[\r\n\s]+$/g, '').replace(/^(Từ khóa|Keywords):\s*/i, '');
    if (kwInput) {
      kwInput.value = cleaned;
      kwInput.setAttribute('data-auto-generated', 'true');
    }
    if (statusEl) statusEl.innerHTML = '<span style="color:#22c55e;">✅ Đã gợi ý từ khóa SEO thành công!</span>';
    showToast('✨ Đã gợi ý từ khóa SEO!', 'success');
  } catch (err) {
    console.error('Keyword suggest error:', err);
    if (statusEl) statusEl.innerHTML = '<span style="color:#f87171;">❌ ' + (err.message || 'Lỗi gợi ý') + '</span>';
    showToast('❌ Lỗi: ' + (err.message || 'Không thể gợi ý từ khóa'), 'error');
  }
}

function convertMarkdownToCleanHtml(str) {
  if (!str) return '';
  let s = str.trim();
  s = s.replace(/^`{3}(html)?\s*/i, '').replace(/`{3}\s*$/i, '').trim();
  s = s.replace(/^(Chào bạn|Dưới đây là|Sau đây là|Đây là bài viết|Tuyệt vời|Dưới đây là nội dung)[^\n]*\n+/i, '');
  s = s.replace(/\*\*\*([^*]+)\*\*\*/g, '<strong><em>$1</em></strong>');
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  s = s.replace(/__([^_]+)__/g, '<strong>$1</strong>');
  s = s.replace(/(^|[^\*])\*([^\*\n]+)\*([^\*]|$)/g, '$1<em>$2</em>$3');
  s = s.replace(/([^\n])\s+##\s+/g, '$1\n\n## ');
  s = s.replace(/([^\n])\s+###\s+/g, '$1\n\n### ');
  s = s.replace(/([^\n])\s+\*\s+\*\*/g, '$1\n* **');
  s = s.replace(/([^\n])\s+-\s+\*\*/g, '$1\n- **');
  const lines = s.split(/\r?\n/);
  const out = [];
  let inList = null;
  let currentP = [];
  function flushP() {
    if (currentP.length > 0) {
      const text = currentP.join(' ').trim();
      if (text) {
        if (/^<(div|blockquote|table|h[1-6])/i.test(text)) {
          out.push(text);
        } else {
          out.push('<p>' + text + '</p>');
        }
      }
      currentP = [];
    }
  }
  function flushList() {
    if (inList) {
      out.push('</' + inList + '>');
      inList = null;
    }
  }
  for (let i = 0; i < lines.length; i++) {
    let line = lines[i].trim();
    if (!line) {
      flushP(); flushList(); continue;
    }
    const h4Match = line.match(/^####\s+(.+)$/);
    if (h4Match) { flushP(); flushList(); out.push("<h4>" + h4Match[1].trim() + "</h4>"); continue; }
    const h3Match = line.match(/^###\s+(.+)$/);
    if (h3Match) { flushP(); flushList(); out.push("<h3>" + h3Match[1].trim() + "</h3>"); continue; }
    const h2Match = line.match(/^##?\s+(.+)$/);
    if (h2Match) { flushP(); flushList(); out.push("<h2>" + h2Match[1].trim() + "</h2>"); continue; }
    if (line.startsWith('>')) { flushP(); flushList(); out.push('<blockquote>' + line.replace(/^>\s*/, '').trim() + '</blockquote>'); continue; }
    const olMatch = line.match(/^[0-9]+\.\s+(.+)$/);
    if (olMatch) {
      flushP();
      if (inList !== 'ol') { flushList(); out.push('<ol>'); inList = 'ol'; }
      out.push('  <li>' + olMatch[1].trim() + '</li>');
      continue;
    }
    const ulMatch = line.match(/^[\*\-•]\s+(.+)$/);
    if (ulMatch) {
      flushP();
      if (inList !== 'ul') { flushList(); out.push('<ul>'); inList = 'ul'; }
      out.push('  <li>' + ulMatch[1].trim() + '</li>');
      continue;
    }
    if (/^<(h[1-6]|ul|ol|div|blockquote|table|p)/i.test(line)) {
      flushP(); flushList(); out.push(line); continue;
    }
    flushList();
    currentP.push(line);
  }
  flushP(); flushList();
  let html = out.join('\n');
  html = html.replace(/#{2,6}\s*/g, '');
  html = html.replace(/\*{2,3}/g, '');
  return html;
}

function extractTitleFromUrl(rawUrl) {
  try {
    const u = new URL(rawUrl);
    let path = decodeURIComponent(u.pathname || '').replace(/\/+$/, '');
    let parts = path.split('/').filter(p => p && !/^(tin-tuc|thu-thuat|blog|post|posts|bai-viet|article|articles|news|category|tag|wiki|news-detail|detail|amp|view)$/i.test(p));
    let slug = parts.pop() || '';
    slug = slug.replace(/\.[a-zA-Z0-9]+$/, '');
    slug = slug.replace(/[-_]?(post|id)?\d{4,}$/i, '');
    slug = slug.replace(/[-_]+/g, ' ').trim();
    if (!slug) return '';
    return slug.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  } catch(e) {
    return '';
  }
}

function isCloudflareChallenge(str) {
  if (!str || typeof str !== 'string') return false;
  const s = str.toLowerCase();
  return s.includes('attention required') || s.includes('just a moment') || s.includes('cloudflare') || 
         s.includes('security verification') || s.includes('captcha') || s.includes('access denied') || 
         s.includes('403 forbidden') || s.includes('error 1027') || s.includes('rate limit');
}

