// HÀM KIỂM TRA SỰ TỒN TẠI VÀ KÍCH THƯỚC ẢNH QUA BROWSER IMAGE PROBE
function probeBrowserImage(url, timeoutMs = 3000) {
  if (!url || typeof url !== 'string') return Promise.resolve(null);
  return new Promise((resolve) => {
    const img = new Image();
    img.referrerPolicy = 'no-referrer';
    let timer = setTimeout(() => {
      img.onload = null;
      img.onerror = null;
      resolve(null);
    }, timeoutMs);
    img.onload = () => {
      clearTimeout(timer);
      if (img.naturalWidth > 60 && img.naturalHeight > 50) {
        resolve({ url: url, width: img.naturalWidth, height: img.naturalHeight });
      } else {
        resolve(null);
      }
    };
    img.onerror = () => {
      clearTimeout(timer);
      // Thử lại 1 lần qua weserv proxy để tránh trường hợp CDN bị chặn cục bộ
      const proxyUrl = 'https://images.weserv.nl/?url=' + encodeURIComponent(url) + '&w=300';
      const imgProxy = new Image();
      imgProxy.referrerPolicy = 'no-referrer';
      let pTimer = setTimeout(() => {
        imgProxy.onload = null;
        imgProxy.onerror = null;
        resolve(null);
      }, 2200);
      imgProxy.onload = () => {
        clearTimeout(pTimer);
        if (imgProxy.naturalWidth > 50) {
          resolve({ url: url, width: imgProxy.naturalWidth, height: imgProxy.naturalHeight });
        } else {
          resolve(null);
        }
      };
      imgProxy.onerror = () => {
        clearTimeout(pTimer);
        resolve(null);
      };
      imgProxy.src = proxyUrl;
    };
    img.src = url;
  });
}

// BỘ THU THẬP HÌNH ẢNH HƯỚNG DẪN THỰC TẾ THEO NỀN TẢNG (FPTSHOP, TGDD, DIENMAYXANH, BLOGS...)
async function harvestPlatformRealImages(cleanUrl, fallbackTitle) {
  const images = [];
  const seenUrls = new Set();
  const lowerUrl = (cleanUrl || '').toLowerCase();

  // 1. FPTSHOP.COM.VN
  if (lowerUrl.includes('fptshop.com.vn')) {
    let artId = '';
    let slug = '';
    const m = cleanUrl.match(/[-_](\d{4,9})(?:[?/#]|$|\.html)/) || cleanUrl.match(/tin-tuc\/.*?-(\d{4,9})/) || cleanUrl.match(/(\d{5,9})/);
    if (m) artId = m[1];
    try {
      const u = new URL(cleanUrl);
      const segs = u.pathname.split('/').filter(Boolean);
      let lastSeg = segs.pop() || '';
      slug = lastSeg.replace(/[-_]\d{4,9}$/, '').replace(/\.html$/, '');
    } catch(e) {}

    if (artId) {
      const candidates = [];
      for (let i = 1; i <= 25; i++) {
        // Pattern 1: Chuẩn nhất của bài viết hướng dẫn FPTShop
        candidates.push({ step: i, priority: 1, url: 'https://cdn2.fptshop.com.vn/unsafe/Uploads/images/tin-tuc/' + artId + '/Originals/' + i + '.jpg' });
        if (slug) {
          candidates.push({ step: i, priority: 2, url: 'https://cdn2.fptshop.com.vn/unsafe/Uploads/images/tin-tuc/' + artId + '/Originals/' + slug + '-' + i + '.jpg' });
        }
        candidates.push({ step: i, priority: 3, url: 'https://cdn2.fptshop.com.vn/unsafe/Uploads/images/tin-tuc/' + artId + '/' + i + '.jpg' });
        if (slug) {
          candidates.push({ step: i, priority: 4, url: 'https://cdn2.fptshop.com.vn/unsafe/Uploads/images/tin-tuc/' + artId + '/' + slug + '-' + i + '.jpg' });
        }
        candidates.push({ step: i, priority: 5, url: 'https://cdn2.fptshop.com.vn/unsafe/Uploads/images/tin-tuc/' + artId + '/Originals/' + i + '.png' });
      }

      // Quét song song bằng probeBrowserImage
      const probes = candidates.map(c => probeBrowserImage(c.url, 2800).then(res => {
        if (res) return { step: c.step, priority: c.priority, url: c.url };
        return null;
      }));

      const results = (await Promise.all(probes)).filter(Boolean);
      // Ưu tiên ảnh priority cao nhất (Originals/i.jpg)
      results.sort((a, b) => a.priority - b.priority);

      // Nhóm theo từng bước để mỗi bước chỉ có 1 ảnh duy nhất chuẩn nhất
      const stepMap = new Map();
      results.forEach(r => {
        if (!stepMap.has(r.step)) {
          stepMap.set(r.step, r.url);
        }
      });

      const sortedSteps = [...stepMap.keys()].sort((a, b) => a - b);
      sortedSteps.forEach(st => {
        const u = stepMap.get(st);
        if (!seenUrls.has(u)) {
          seenUrls.add(u);
          images.push({
            url: u,
            alt: (fallbackTitle || 'Hướng dẫn') + ' - Bước ' + st,
            selected: true
          });
        }
      });
    }
  }

  // 2. THEGIOIDIDONG.COM & DIENMAYXANH.COM
  if (lowerUrl.includes('thegioididong.com') || lowerUrl.includes('dienmayxanh.com')) {
    let artId = '';
    const m = cleanUrl.match(new RegExp("[-_](\\d{4,9})(?:\\.html|/|$|\\?)"));
    if (m) artId = m[1];
    if (artId) {
      const candidates = [];
      for (let i = 1; i <= 20; i++) {
        candidates.push({ step: i, url: 'https://cdn.tgdd.vn/Files/News/' + artId + '/' + i + '.jpg' });
        candidates.push({ step: i, url: 'https://cdn.tgdd.vn/Files/' + artId + '/' + i + '.jpg' });
      }
      const probes = candidates.map(c => probeBrowserImage(c.url, 2800).then(res => {
        if (res) return { step: c.step, url: c.url };
        return null;
      }));
      const results = (await Promise.all(probes)).filter(Boolean);
      results.sort((a, b) => a.step - b.step);
      results.forEach(r => {
        if (!seenUrls.has(r.url)) {
          seenUrls.add(r.url);
          images.push({
            url: r.url,
            alt: (fallbackTitle || 'Hướng dẫn') + ' - Bước ' + r.step,
            selected: true
          });
        }
      });
    }
  }

  return images;
}

async function fetchSampleArticleData(sampleUrl) {
  if (!sampleUrl || typeof sampleUrl !== 'string') return null;
  let cleanUrl = sampleUrl.trim();
  if (!cleanUrl) return null;
  if (!/^https?:\/\//i.test(cleanUrl)) cleanUrl = 'https://' + cleanUrl;

  const fallbackTitle = extractTitleFromUrl(cleanUrl);
  let title = '';
  let textSnippet = '';
  let headings = [];
  const images = [];
  const seenUrls = new Set();
  let isWafProtected = false;

  function addImg(src, alt) {
    if (!src || typeof src !== 'string') return;
    src = src.trim();
    if (src.startsWith('//')) src = 'https:' + src;
    else if (!src.startsWith('http://') && !src.startsWith('https://')) {
      try { src = new URL(src, cleanUrl).href; } catch(e) { return; }
    }
    const lower = src.toLowerCase();
    if (lower.includes('avatar') || lower.includes('favicon') || lower.includes('pixel') || 
        lower.includes('1x1') || lower.includes('track') || lower.includes('gravatar') || 
        lower.includes('share') || lower.includes('icon') || lower.includes('banner-ads') ||
        lower.includes('badge') || lower.includes('emoji') || lower.includes('logo') || 
        lower.startsWith('data:') || lower.endsWith('.svg')) {
      return;
    }

    // Loại bỏ query thu nhỏ thumbnail để giữ nguyên ảnh Full HD sắc nét
    let cleanSrc = src;
    try {
      const uObj = new URL(src);
      ['w', 'width', 'h', 'height', 'resize', 'size', 'fit'].forEach(p => {
        if (uObj.searchParams.has(p)) {
          const val = parseInt(uObj.searchParams.get(p) || '0', 10);
          if (val > 0 && val < 600) uObj.searchParams.delete(p);
        }
      });
      cleanSrc = uObj.href;
    } catch(e) {}

    // Bỏ hậu tố -300x200 hoặc tương tự trong tên file
    cleanSrc = cleanSrc.replace(/-\d{2,4}x\d{2,4}(\.[a-zA-Z]{3,4})/i, '$1');

    const baseClean = cleanSrc.split('?')[0];
    if (!seenUrls.has(baseClean)) {
      seenUrls.add(baseClean);
      images.push({
        url: cleanSrc,
        alt: (alt && alt.trim()) ? alt.trim() : (title || fallbackTitle || 'Hình ảnh minh hoạ bài viết'),
        selected: true
      });
    }
  }

  // 0. Thu hoạch 100% ảnh thật từ các nền tảng hướng dẫn chuyên biệt (FPTSHOP, TGDD, ĐMX...)
  try {
    const platformImgs = await harvestPlatformRealImages(cleanUrl, fallbackTitle);
    if (platformImgs && platformImgs.length > 0) {
      platformImgs.forEach(im => addImg(im.url, im.alt));
      if (!title) title = fallbackTitle;
    }
  } catch(eHarv) {
    console.warn('harvestPlatformRealImages error:', eHarv);
  }

  // 1. Thử qua Microlink API với custom data selector lấy toàn bộ ảnh, headings và bodyText
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 9000);
    const mUrl = `https://api.microlink.io/?url=${encodeURIComponent(cleanUrl)}` +
      `&data.images=${encodeURIComponent(JSON.stringify({ selectorAll: 'article img, .post-content img, .entry-content img, .content img, main img, figure img, img', attr: 'src' }))}` +
      `&data.headings=${encodeURIComponent(JSON.stringify({ selectorAll: 'h2, h3, h4', attr: 'text' }))}` +
      `&data.bodyText=${encodeURIComponent(JSON.stringify({ selector: 'article, .post-content, .entry-content, main, body', attr: 'text' }))}`;
    
    const mRes = await fetch(mUrl, { signal: controller.signal });
    clearTimeout(timeoutId);
    if (mRes.ok) {
      const mJson = await mRes.json();
      if (mJson && mJson.data) {
        const mTitle = mJson.data.title || '';
        if (isCloudflareChallenge(mTitle) || mJson.statusCode === 403) {
          isWafProtected = true;
        } else {
          if (mTitle) title = mTitle.replace(/\s*[\-\|]\s*.*$/, '').trim();
          if (mJson.data.description && !textSnippet) textSnippet = mJson.data.description;
          if (mJson.data.bodyText && mJson.data.bodyText.length > textSnippet.length) {
            textSnippet = mJson.data.bodyText.slice(0, 10000);
          }
          if (Array.isArray(mJson.data.headings) && mJson.data.headings.length > 0) {
            headings = mJson.data.headings.map(h => String(h).trim()).filter(h => h && h.length > 3 && !/đăng nhập|bình luận|bài viết liên quan|menu/i.test(h));
          }
          if (mJson.data.image && mJson.data.image.url) {
            addImg(mJson.data.image.url, title);
          }
          if (Array.isArray(mJson.data.images)) {
            mJson.data.images.forEach((imgUrl, i) => {
              if (imgUrl) addImg(imgUrl, `${title} - Hình ${i + 1}`);
            });
          }
        }
      }
    }
  } catch(e) {
    console.warn('Microlink reader notice:', e);
  }

  // 2. Thử qua các proxy HTML nếu chưa lấy đủ dữ liệu
  if (!textSnippet || textSnippet.length < 500 || images.length < 2) {
    const proxies = [
      `https://api.allorigins.win/get?url=${encodeURIComponent(cleanUrl)}`,
      `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(cleanUrl)}`
    ];

    for (const pUrl of proxies) {
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 7000);
        const res = await fetch(pUrl, {
          signal: controller.signal,
          headers: { 'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8' }
        });
        clearTimeout(timeoutId);
        if (res.ok) {
          const raw = await res.text();
          let candidate = raw;
          if (pUrl.includes('allorigins')) {
            try {
              const j = JSON.parse(raw);
              candidate = j.contents || '';
            } catch(ej) {}
          }
          if (candidate && candidate.length > 500 && !isCloudflareChallenge(candidate)) {
            const parser = new DOMParser();
            const doc = parser.parseFromString(candidate, 'text/html');

            if (!title) {
              const ogTitle = doc.querySelector("meta[property='og:title']");
              if (ogTitle && ogTitle.content) title = ogTitle.content.trim();
              if (!title) {
                const h1 = doc.querySelector('article h1, main h1, .post-title, .entry-title, h1');
                if (h1 && h1.textContent) title = h1.textContent.trim();
              }
              if (!title && doc.title) title = doc.title.trim();
              if (title) title = title.replace(/\s*[\-\|]\s*.*$/, '').trim();
            }

            const ogImg = doc.querySelector("meta[property='og:image']");
            if (ogImg && ogImg.content) addImg(ogImg.content, title);

            const contentScope = doc.querySelector('article, .post-body, .entry-content, .post-content, main, .content, #content') || doc.body;
            const imgNodes = contentScope ? contentScope.querySelectorAll('img') : doc.querySelectorAll('img');
            imgNodes.forEach(node => {
              let src = node.getAttribute('src') || node.getAttribute('data-src') || node.getAttribute('data-original') || node.getAttribute('data-lazy-src') || '';
              if (!src && node.getAttribute('srcset')) {
                const parts = node.getAttribute('srcset').split(',');
                if (parts.length > 0) src = parts[0].trim().split(' ')[0];
              }
              const alt = node.getAttribute('alt') || node.getAttribute('title') || '';
              addImg(src, alt);
            });

            if (headings.length === 0 && contentScope) {
              const hNodes = contentScope.querySelectorAll('h2, h3');
              hNodes.forEach(hn => {
                const ht = hn.textContent.trim();
                if (ht && ht.length > 3 && !/đăng nhập|bình luận|liên quan/i.test(ht)) {
                  headings.push(ht);
                }
              });
            }

            if (!textSnippet || textSnippet.length < 500) {
              const cleanDoc = doc.cloneNode(true);
              const elementsToRemove = cleanDoc.querySelectorAll('script, style, nav, header, footer, aside, noscript, iframe, .sidebar, .comments, .related-posts, .menu, .ads');
              elementsToRemove.forEach(el => el.remove());
              const targetBody = cleanDoc.querySelector('article, .post-body, .entry-content, .post-content, main, .content') || cleanDoc.body;
              let text = targetBody ? (targetBody.innerText || targetBody.textContent || '') : '';
              text = text.replace(/\s+/g, ' ').trim();
              if (text.length > 100) textSnippet = text.slice(0, 10000);
            }

            break;
          }
        }
      } catch(err) {}
    }
  }

  // 3. Nếu không lấy được title hoặc trang bị chặn bởi WAF/Captcha, tự động khôi phục từ URL slug
  if (!title || isCloudflareChallenge(title)) {
    title = fallbackTitle || 'Hướng Dẫn Chi Tiết MMO 2026';
    isWafProtected = true;
  }

  // 4. Nếu danh sách ảnh đang trống, thử quét lại nền tảng hoặc cấp bộ ảnh theo chủ đề
  if (images.length === 0) {
    try {
      const pImgs2 = await harvestPlatformRealImages(cleanUrl, title || fallbackTitle);
      if (pImgs2 && pImgs2.length > 0) {
        pImgs2.forEach(im => addImg(im.url, im.alt));
      }
    } catch(eH2) {}
  }

  if (images.length === 0) {
    const topicImgs = getTopicIllustrativeImages(title, cleanUrl);
    topicImgs.forEach(im => {
      images.push({
        url: im.url,
        alt: im.alt || (title + ' minh họa'),
        selected: true
      });
    });
  } else {
    images.forEach(im => { if (typeof im.selected === 'undefined') im.selected = true; });
  }

  if (!textSnippet) {
    textSnippet = `Bài viết hướng dẫn thực chiến chuyên sâu về ${title}, cung cấp đầy đủ các bước thực hiện chi tiết, các phương pháp kiếm tiền, điều kiện bật kiếm tiền, phân tích ưu nhược điểm, kinh nghiệm thực tế và giải đáp thắc mắc chuẩn SEO E-E-A-T 2026.`;
  }

  return {
    success: true,
    url: cleanUrl,
    title: title,
    headings: headings,
    images: images.slice(0, 30),
    textSnippet: textSnippet,
    isWafProtected: isWafProtected
  };
}

// Biến lưu trữ toàn cục dữ liệu bài viết mẫu hiện tại
window.currentSampleArticleData = null;

// Modal phóng to xem ảnh minh họa chi tiết (z-index cao hơn aiWriterModal để không bị che khuất)
function openSampleImageZoomModal(idx) {
  if (!window.currentSampleArticleData || !Array.isArray(window.currentSampleArticleData.images)) return;
  const img = window.currentSampleArticleData.images[idx];
  if (!img) return;

  let modal = document.getElementById('sampleImageZoomModal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'sampleImageZoomModal';
    document.body.appendChild(modal);
  }
  // Đảm bảo z-index cao nhất tuyệt đối (2147483648 > 2147483647 của aiWriterModal)
  modal.style.cssText = 'position:fixed; top:0; left:0; right:0; bottom:0; width:100vw; height:100vh; background:rgba(0,0,0,0.92); z-index:2147483648 !important; display:flex; align-items:center; justify-content:center; padding:12px; box-sizing:border-box; backdrop-filter:blur(6px); -webkit-backdrop-filter:blur(6px);';

  const isSelected = img.selected !== false;
  modal.innerHTML = `
    <div style="background:#0f172a; border:1px solid #38bdf8; border-radius:12px; max-width:880px; width:100%; max-height:94vh; display:flex; flex-direction:column; overflow:hidden; box-shadow:0 25px 60px rgba(0,0,0,0.9), 0 0 30px rgba(56,189,248,0.25); position:relative; z-index:2147483649 !important;">
      <div style="padding:10px 14px; border-bottom:1px solid #1e293b; display:flex; align-items:center; justify-content:space-between; background:#1e1e38; flex-shrink:0;">
        <div style="display:flex; align-items:center; gap:8px; min-width:0;">
          <span style="font-size:13px; font-weight:700; color:#38bdf8; white-space:nowrap;"><i class="fa-solid fa-magnifying-glass-plus"></i> Ảnh #${idx + 1}</span>
          <span style="font-size:11px; color:#94a3b8; background:#0f172a; padding:2px 8px; border-radius:4px; border:1px solid #334155; max-width:240px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${img.alt || 'Ảnh minh họa bài viết'}</span>
        </div>
        <div style="display:flex; align-items:center; gap:8px; flex-shrink:0;">
          <a href="${img.url}" target="_blank" rel="noopener noreferrer" style="font-size:11px; color:#38bdf8; text-decoration:none; background:#0f172a; padding:4px 8px; border-radius:6px; border:1px solid #334155; display:inline-flex; align-items:center; gap:4px;" title="Mở link ảnh gốc trong tab mới">
            <i class="fa-solid fa-arrow-up-right-from-square"></i> Mở tab mới
          </a>
          <button type="button" onclick="closeSampleImageZoomModal()" style="background:#ef4444; border:none; color:#fff; font-size:14px; font-weight:bold; cursor:pointer; width:28px; height:28px; border-radius:50%; display:flex; align-items:center; justify-content:center; padding:0; line-height:1;">✕</button>
        </div>
      </div>
      <div style="flex:1; min-height:180px; max-height:68vh; overflow:auto; padding:12px; display:flex; align-items:center; justify-content:center; background:#020617;">
        <img src="${img.url}" alt="${img.alt || ''}" referrerpolicy="no-referrer" style="max-width:100%; max-height:64vh; width:auto; height:auto; object-fit:contain; border-radius:8px; box-shadow:0 4px 20px rgba(0,0,0,0.6);" onerror="if(!this.dataset.retry){this.dataset.retry='1'; this.src='https://images.weserv.nl/?url=' + encodeURIComponent('${img.url}');} else { this.src='https://iili.io/nFV4Rln.png'; }" />
      </div>
      <div style="padding:10px 14px; border-top:1px solid #1e293b; display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px; background:#1e1e38; flex-shrink:0;">
        <label style="display:flex; align-items:center; gap:8px; cursor:pointer; font-size:12px; color:#e2e8f0; user-select:none;">
          <input type="checkbox" ${isSelected ? 'checked' : ''} onchange="toggleSampleImageSelection(${idx}, this.checked)" style="width:16px; height:16px; accent-color:#10b981; cursor:pointer;" />
          <span style="font-weight:600;"><i class="fa-solid fa-circle-check" style="color:#10b981;"></i> Chọn chèn ảnh này</span>
        </label>
        <div style="display:flex; gap:8px;">
          <button type="button" onclick="removeSampleArticleImage(${idx}); closeSampleImageZoomModal();" style="background:#ef4444; color:#fff; border:none; padding:6px 12px; border-radius:6px; font-size:11px; font-weight:600; cursor:pointer; display:flex; align-items:center; gap:4px;">
            <i class="fa-solid fa-trash-can"></i> Xóa ảnh
          </button>
          <button type="button" onclick="closeSampleImageZoomModal()" style="background:#334155; color:#e2e8f0; border:none; padding:6px 14px; border-radius:6px; font-size:11px; font-weight:600; cursor:pointer;">
            Đóng
          </button>
        </div>
      </div>
    </div>
  `;
  modal.onclick = (e) => {
    if (e.target === modal) closeSampleImageZoomModal();
  };
  modal.style.setProperty('display', 'flex', 'important');
}
window.openSampleImageZoomModal = openSampleImageZoomModal;

function closeSampleImageZoomModal() {
  const modal = document.getElementById('sampleImageZoomModal');
  if (modal) modal.style.display = 'none';
}
window.closeSampleImageZoomModal = closeSampleImageZoomModal;

// Lắng nghe phím ESC để đóng modal phóng to ảnh
window.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    const modal = document.getElementById('sampleImageZoomModal');
    if (modal && modal.style.display !== 'none') closeSampleImageZoomModal();
  }
});

function toggleSampleImageSelection(idx, isChecked) {
  if (!window.currentSampleArticleData || !Array.isArray(window.currentSampleArticleData.images)) return;
  if (window.currentSampleArticleData.images[idx]) {
    window.currentSampleArticleData.images[idx].selected = isChecked;
    renderSampleArticlePreviewUI(window.currentSampleArticleData);
  }
}
window.toggleSampleImageSelection = toggleSampleImageSelection;

// Thêm ảnh bằng URL do người dùng tự nhập
function addCustomSampleArticleImage() {
  const inp = document.getElementById('addCustomImageUrlInput');
  if (!inp) return;
  const url = inp.value.trim();
  if (!url || !/^https?:\/\//i.test(url)) {
    if (typeof showToast === 'function') showToast('⚠️ Vui lòng nhập link ảnh hợp lệ (https://...)!', 'warn');
    return;
  }
  if (!window.currentSampleArticleData) {
    window.currentSampleArticleData = {
      success: true,
      url: url,
      title: 'Bài viết SEO',
      images: [],
      textSnippet: ''
    };
  }
  window.currentSampleArticleData.images.push({
    url: url,
    alt: 'Ảnh minh họa thêm mới',
    selected: true
  });
  inp.value = '';
  renderSampleArticlePreviewUI(window.currentSampleArticleData);
  if (typeof showToast === 'function') showToast('✅ Đã thêm ảnh mới thành công!', 'success');
}
window.addCustomSampleArticleImage = addCustomSampleArticleImage;

